          const selected = option.id === content.selectedId
          return (
            <button
              key={option.id}
              type="button"
              aria-pressed={selected}
              onClick={() => onAction?.("select", option.id)}
              className={cx(
                "min-w-0 rounded-xl border p-4 text-left transition-colors",
