export { AgentResponse } from "./application/response/response"
export type {
  AgentResponseProps,
  Artifact,
  ToolCall,
} from "./application/response/response"

"use client"

import { Button } from "@/components/boardui/base/buttons/button"
import { cx } from "@/components/boardui/utils/cx"
import { CodeBlockCode } from "@/components/prompt-kit/code-block"
import { Markdown } from "@/components/prompt-kit/markdown"
import {
  Check,
  ChevronRight,
  Circle,
  Copy,
  Download,
  FileCode,
  FileText,
  Loader2,
  RefreshCw,
  Wrench,
  XCircle,
} from "lucide-react"
import { useState } from "react"

/* Tool payloads are intentionally provider-defined. */
/* eslint-disable @typescript-eslint/no-explicit-any */
export type ToolCall = {
  id: string
  name: string
  input: any
  output?: any
  status: "pending" | "running" | "completed" | "failed"
  duration?: number
}
export type Artifact = {
  id: string
  type: "code" | "file" | "image" | "data"
  name: string
  content: string
  language?: string
  size?: string
}
export interface AgentResponseProps {
  message: string
  thinking?: string
  toolCalls?: ToolCall[]
  artifacts?: Artifact[]
  isStreaming?: boolean
  className?: string
  onRegenerate?: () => void
  onCopy?: () => void
}
const statusIcons = {
  pending: Circle,
  running: Loader2,
  completed: Check,
  failed: XCircle,
}

function ToolRow({ tool }: { tool: ToolCall }) {
  const [open, setOpen] = useState(false)
  const Icon = statusIcons[tool.status]
  return (
    <div className="border-separator-border border-b last:border-b-0">
      <button
        type="button"
        aria-expanded={open}
        onClick={() => setOpen((value) => !value)}
        className="hover:bg-background-secondary-hover flex min-h-11 w-full items-center gap-2 px-3 text-left"
      >
        <Icon
          className={cx(
            "text-text-secondary size-4",
            tool.status === "running" && "text-accent-600 animate-spin",
            tool.status === "failed" && "text-foreground-icon-error",
            tool.status === "completed" && "text-foreground-icon-positive"
          )}
        />
        <Wrench className="text-text-tertiary size-4" />
        <span className="text-body-medium min-w-0 flex-1 truncate">
          {tool.name}
        </span>
        <span className="text-caption-1-regular text-text-secondary tabular-nums">
          {tool.duration === undefined ? tool.status : `${tool.duration} ms`}
        </span>
        <ChevronRight
          className={cx(
            "text-text-tertiary size-4 transition-transform",
            open && "rotate-90"
          )}
        />
      </button>
      {open && (
        <div className="border-separator-border bg-background-secondary-default space-y-3 border-t p-3">
          <Payload label="Input" value={tool.input} />
          {tool.output !== undefined && (
            <Payload label="Output" value={tool.output} />
          )}
        </div>
      )}
    </div>
  )
}
function Payload({ label, value }: { label: string; value: unknown }) {
  return (
    <div>
      <p className="text-caption-1-medium text-text-secondary mb-1">{label}</p>
      <pre className="text-caption-1-regular text-text-primary overflow-x-auto whitespace-pre-wrap">
        {JSON.stringify(value, null, 2)}
      </pre>
    </div>
  )
}
function ArtifactView({ artifact }: { artifact: Artifact }) {
  const Icon = artifact.type === "code" ? FileCode : FileText
  return (
    <section className="border-separator-border overflow-hidden rounded-lg border">
      <header className="border-separator-border flex min-h-11 items-center gap-2 border-b px-3">
        <Icon className="text-text-secondary size-4" />
        <span className="text-body-medium min-w-0 flex-1 truncate">
          {artifact.name}
        </span>
        {artifact.size && (
          <span className="text-caption-1-regular text-text-secondary">
            {artifact.size}
          </span>
        )}
        <Button
          size="xs"
          variant="ghost"
          iconOnly
          leadingIcon={Download}
          aria-label={`Download ${artifact.name}`}
        />
      </header>
      <div className="bg-background-secondary-default max-h-96 overflow-auto">
        {artifact.type === "code" ? (
          <CodeBlockCode
            code={artifact.content}
            language={artifact.language || "plaintext"}
            className="rounded-none border-0"
          />
        ) : (
          <pre className="text-body-2-regular p-4 whitespace-pre-wrap">
            {artifact.content}
          </pre>
        )}
      </div>
    </section>
  )
}
export function AgentResponse({
  message,
  thinking,
  toolCalls = [],
  artifacts = [],
  isStreaming = false,
  className,
  onRegenerate,
  onCopy,
}: AgentResponseProps) {
  const [thinkingOpen, setThinkingOpen] = useState(false)
  return (
    <article
      className={cx(
        "border-separator-border bg-background-primary-default overflow-hidden rounded-2xl border",
        className
      )}
    >
      <header className="border-separator-border flex min-h-12 items-center justify-between gap-3 border-b px-4">
        <div>
          <h3 className="text-body-medium">Assistant response</h3>
          <p className="text-caption-1-regular text-text-secondary">
            {isStreaming
              ? "Generating response"
              : `${toolCalls.length} tools  |  ${artifacts.length} artifacts`}
          </p>
        </div>
        {isStreaming && (
          <Loader2 className="text-text-secondary size-4 animate-spin" />
        )}
      </header>
      <div className="space-y-4 p-4">
        {thinking && (
          <div>
            <button
              type="button"
              aria-expanded={thinkingOpen}
              onClick={() => setThinkingOpen((open) => !open)}
              className="text-body-medium text-text-secondary hover:text-text-primary flex min-h-10 items-center gap-2"
            >
              <ChevronRight
                className={cx(
                  "size-4 transition-transform",
                  thinkingOpen && "rotate-90"
                )}
              />
              Reasoning summary
            </button>
            {thinkingOpen && (
              <p className="bg-background-secondary-default text-body-2-regular text-text-secondary rounded-lg p-3 leading-5">
                {thinking}
              </p>
            )}
          </div>
        )}
        {toolCalls.length > 0 && (
          <section>
            <h4 className="text-caption-1-medium text-text-secondary mb-2">
              Tool activity
            </h4>
            <div className="border-separator-border overflow-hidden rounded-lg border">
              {toolCalls.map((tool) => (
                <ToolRow key={tool.id} tool={tool} />
              ))}
            </div>
          </section>
        )}
        <div className="text-body-regular max-w-none leading-6">
          <Markdown>{message}</Markdown>
          {isStreaming && (
            <span className="bg-text-primary ml-1 inline-block h-4 w-px animate-pulse" />
          )}
        </div>
        {artifacts.length > 0 && (
          <section className="space-y-2">
            <h4 className="text-caption-1-medium text-text-secondary">
              Artifacts
            </h4>
            {artifacts.map((artifact) => (
              <ArtifactView key={artifact.id} artifact={artifact} />
            ))}
          </section>
        )}
      </div>
      {!isStreaming && (onCopy || onRegenerate) && (
        <footer className="border-separator-border flex gap-1 border-t px-3 py-2">
          {onCopy && (
            <Button
              size="small"
              variant="ghost"
              leadingIcon={Copy}
              onClick={onCopy}
            >
              Copy
            </Button>
          )}
          {onRegenerate && (
            <Button
              size="small"
              variant="ghost"
              leadingIcon={RefreshCw}
              onClick={onRegenerate}
            >
              Regenerate
            </Button>
          )}
        </footer>
      )}
    </article>
  )
}

import { cx, sortCx } from "@/components/boardui/utils/cx"
import type {
  AnchorHTMLAttributes,
  ButtonHTMLAttributes,
  ComponentType,
  ReactNode,
  Ref,
} from "react"
import { Focusable } from "react-aria-components"

/**
 * Figma source: Board UI → Buttons (node 3656:13819).
 *
 * Variant matrix from Figma:
 *   Type     = Primary | Secondary | Ghost | Danger
 *   Size     = Medium  | Small | Xs
 *   State    = Default | Hover | Active | Disabled        (CSS pseudo)
 *   OnlyIcon = false   | true
 *
 * Sizing (1:1 with Figma):
 *
 *                       Medium                    Small                     Xs
 *   container          h=36, p=8,   r=10         h=32, px=8 py=6, r=8      h=24, px=8, r=4
 *   gap                 2px                       2px                      1.33px→1
 *   icon                20×20                     18×18                    14×14
 *   label wrapper       px=4                      px=2                     px=2
 *   text style          Body 1/Medium             Body 1/Medium            Caption 1/Semibold
 *   icon-only square    36×36 (content-derived)   32×32 (forced size)      24×24 (forced size)
 *
 * `xs` is the smallest tier - first needed for the calendar template's
 * event-details modal ("Join" / edit-icon buttons, node 3920:10954), which
 * scales every dimension down by the same ~0.667 factor from Figma; the
 * table above rounds those to clean pixel values rather than reproducing
 * the fractional source numbers.
 *
 * Icons are rendered by the component itself via the `leadingIcon` /
 * `trailingIcon` props so the consumer can't pass the wrong size. Pass
 * a Remix Icon component reference (`RiAddLine`, not `<RiAddLine />`).
 *
 * For icon-only buttons:
 *   <Button iconOnly leadingIcon={RiAddLine} aria-label="Add" />
 *
 * The HTML `type` prop is preserved; Figma's "Type" enum is renamed to
 * `variant` to avoid the clash.
 */

type ButtonVariant = "primary" | "secondary" | "ghost" | "danger"
type ButtonSize = "medium" | "small" | "xs"

type IconComponent = ComponentType<{
  className?: string
  "aria-hidden"?: boolean | "true" | "false"
}>

export interface ButtonProps
  extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, "children"> {
  variant?: ButtonVariant
  size?: ButtonSize
  iconOnly?: boolean
  leadingIcon?: IconComponent
  trailingIcon?: IconComponent
  children?: ReactNode
  ref?: Ref<HTMLButtonElement>
}

export interface ButtonLinkProps
  extends Omit<AnchorHTMLAttributes<HTMLAnchorElement>, "children"> {
  variant?: ButtonVariant
  size?: ButtonSize
  iconOnly?: boolean
  leadingIcon?: IconComponent
  trailingIcon?: IconComponent
  children?: ReactNode
  ref?: Ref<HTMLAnchorElement>
}

const styles = sortCx({
  base: [
    "inline-flex items-center justify-center gap-0.5 whitespace-nowrap overflow-hidden",
    "font-sans select-none cursor-pointer",
    "button-press-motion",
    "outline-none focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-border-focus-ring",
    "disabled:cursor-not-allowed aria-disabled:cursor-not-allowed",
  ].join(" "),

  // Base shape per size (used when label is present OR medium icon-only).
  size: {
    medium: "h-9 rounded-2lg p-2 text-body-medium",
    small: "h-8 rounded-lg px-2 py-1.5 text-body-medium",
    xs: "h-6 rounded-sm px-2 text-caption-1-semibold",
  },

  // Icon-only override:
  //   Medium → keep p-2; w expands from content (8+20+8 = 36) → square.
  //   Small  → Figma forces 32×32 even though 8+18+8=34, so we hard-set size-8
  //            and zero the padding; the inner flex centers the 18px icon.
  //   Xs     → forces 24×24, content-centered - used for the calendar
  //            template's edit-icon buttons (timezone/participants/reminder).
  iconOnlySize: {
    medium: "", // base size already produces 36×36 with a 20px icon
    small: "size-8 p-0", // hard 32×32, content-centered
    xs: "size-6 p-0", // hard 24×24, content-centered
  },

  icon: {
    medium: "size-5 shrink-0", // 20px
    small: "size-[18px] shrink-0", // 18px
    xs: "size-3.5 shrink-0", // 14px
  },

  label: {
    medium: "inline-flex items-center justify-center px-1 shrink-0", // px=4
    small: "inline-flex items-center justify-center px-0.5 shrink-0", // px=2
    xs: "inline-flex items-center justify-center px-0.5 shrink-0", // px=2
  },

  variant: {
    primary: [
      "bg-button-primary",
      "disabled:text-button-primary-disabled-foreground disabled:shadow-none",
      "aria-disabled:text-button-primary-disabled-foreground aria-disabled:shadow-none",
    ].join(" "),
    danger: [
      "bg-button-danger text-text-white shadow-xs",
      "disabled:text-foreground-disabled-danger disabled:shadow-none",
      "aria-disabled:text-foreground-disabled-danger aria-disabled:shadow-none",
    ].join(" "),
    secondary: [
      "bg-background-primary-default text-text-primary",
      "border border-border-button-default shadow-xs",
      "hover:bg-background-primary-hover  hover:border-border-button-hover",
      "active:bg-background-primary-active active:border-border-button-active",
      "disabled:bg-background-primary-disabled disabled:border-border-button-default disabled:text-text-tertiary disabled:shadow-none",
      "aria-disabled:bg-background-primary-disabled aria-disabled:border-border-button-default aria-disabled:text-text-tertiary aria-disabled:shadow-none",
    ].join(" "),
    ghost: [
      "bg-button-ghost-background text-button-ghost-foreground",
      "hover:bg-button-ghost-hover active:bg-button-ghost-active",
      "disabled:bg-button-ghost-disabled disabled:text-button-ghost-disabled-foreground disabled:shadow-none",
      "aria-disabled:bg-button-ghost-disabled aria-disabled:text-button-ghost-disabled-foreground aria-disabled:shadow-none",
    ].join(" "),
  },
})

export function Button({
  variant = "primary",
  size = "medium",
  iconOnly = false,
  leadingIcon: Leading,
  trailingIcon: Trailing,
  children,
  className,
  type = "button",
  ref,
  ...props
}: ButtonProps) {
  return (
    <Focusable isDisabled={props.disabled}>
      <button
        ref={ref}
        type={type}
        className={cx(
          styles.base,
          styles.size[size],
          styles.variant[variant],
          iconOnly && styles.iconOnlySize[size],
          className
        )}
        {...props}
      >
        {Leading ? <Leading className={styles.icon[size]} aria-hidden /> : null}
        {iconOnly && !Leading && children != null ? (
          <span
            aria-hidden
            className={cx(
              styles.icon[size],
              "inline-flex items-center justify-center [&>svg]:size-full"
            )}
          >
            {children}
          </span>
        ) : null}
        {!iconOnly && children !== undefined && children !== null && (
          <span className={styles.label[size]}>{children}</span>
        )}
        {!iconOnly && Trailing ? (
          <Trailing className={styles.icon[size]} aria-hidden />
        ) : null}
      </button>
    </Focusable>
  )
}

/** Anchor counterpart to Button for navigational actions. */
export function ButtonLink({
  variant = "primary",
  size = "medium",
  iconOnly = false,
  leadingIcon: Leading,
  trailingIcon: Trailing,
  children,
  className,
  ref,
  ...props
}: ButtonLinkProps) {
  return (
    <Focusable>
      <a
        ref={ref}
        className={cx(
          styles.base,
          styles.size[size],
          styles.variant[variant],
          iconOnly && styles.iconOnlySize[size],
          className
        )}
        {...props}
      >
        {Leading ? <Leading className={styles.icon[size]} aria-hidden /> : null}
        {iconOnly && !Leading && children != null ? (
          <span
            aria-hidden
            className={cx(
              styles.icon[size],
              "inline-flex items-center justify-center [&>svg]:size-full"
            )}
          >
            {children}
          </span>
        ) : null}
        {!iconOnly && children !== undefined && children !== null && (
          <span className={styles.label[size]}>{children}</span>
        )}
        {!iconOnly && Trailing ? (
          <Trailing className={styles.icon[size]} aria-hidden />
        ) : null}
      </a>
    </Focusable>
  )
}

/** Style maps, exported for advanced composition and the dev Design Tuner. */
export const buttonStyles = styles

import { extendTailwindMerge } from "tailwind-merge";

/**
 * Text-style classes from styles/typography.css.
 *
 * IMPORTANT: every text-* utility we define via @theme (e.g. `text-body-medium`,
 * `text-title-1-semibold`) must be listed here. Otherwise tailwind-merge — which
 * has no view of our Tailwind theme — treats them as text-color utilities and
 * silently drops them when they appear in the same className as a real color
 * (`text-foreground-full`, `text-text-primary`, etc).
 *
 * If you add or rename a text style in typography.css, mirror the change here.
 */
const TEXT_FAMILIES = [
  "large-title",
  "display-1",
  "display-2",
  "display-3",
  "display-4",
  "title-1",
  "title-2",
  "title-3",
  "headline",
  "body",
  "body-2",
  "caption-1",
  "caption-2",
] as const;

const TEXT_WEIGHTS = ["regular", "medium", "semibold", "bold"] as const;

const TEXT_STYLE_SUFFIXES = TEXT_FAMILIES.flatMap((family) =>
  TEXT_WEIGHTS.map((weight) => `${family}-${weight}`),
);

const twMerge = extendTailwindMerge({
  extend: {
    classGroups: {
      "font-size": [{ text: TEXT_STYLE_SUFFIXES }],
    },
  },
});

/**
 * Merge Tailwind classes safely. Last-write-wins on conflicting utilities.
 */
export const cx = twMerge;

/**
 * Identity helper that gives the Tailwind IntelliSense extension a hook for
 * sorting classes inside style objects (the extension doesn't sort inside
 * plain object literals otherwise).
 */
export function sortCx<
  T extends Record<
    string,
    string | number | Record<string, string | number | Record<string, string | number>>
  >,
>(classes: T): T {
  return classes;
}

"use client"

import { cn } from "@/lib/utils"
import React, { useEffect, useState } from "react"
import { codeToHtml } from "shiki"

export type CodeBlockProps = {
  children?: React.ReactNode
  className?: string
} & React.HTMLProps<HTMLDivElement>

function CodeBlock({ children, className, ...props }: CodeBlockProps) {
  return (
    <div
      className={cn(
        "not-prose flex w-full flex-col overflow-clip border",
        "border-border bg-card text-card-foreground rounded-xl",
        className
      )}
      {...props}
    >
      {children}
    </div>
  )
}

export type CodeBlockCodeProps = {
  code: string
  language?: string
  theme?: string
  className?: string
} & React.HTMLProps<HTMLDivElement>

function CodeBlockCode({
  code,
  language = "tsx",
  theme = "github-light",
  className,
  ...props
}: CodeBlockCodeProps) {
  const [highlightedHtml, setHighlightedHtml] = useState<string | null>(null)

  useEffect(() => {
    async function highlight() {
      if (!code) {
        setHighlightedHtml("<pre><code></code></pre>")
        return
      }

      const html = await codeToHtml(code, { lang: language, theme })
      setHighlightedHtml(html)
    }
    highlight()
  }, [code, language, theme])

  const classNames = cn(
    "w-full overflow-x-auto text-[13px] [&>pre]:px-4 [&>pre]:py-4",
    className
  )

  // SSR fallback: render plain code if not hydrated yet
  return highlightedHtml ? (
    <div
      data-code-theme={theme}
      className={classNames}
      dangerouslySetInnerHTML={{ __html: highlightedHtml }}
      {...props}
    />
  ) : (
    <div data-code-theme={theme} className={classNames} {...props}>
      <pre>
        <code>{code}</code>
      </pre>
    </div>
  )
}

export type CodeBlockGroupProps = React.HTMLAttributes<HTMLDivElement>

function CodeBlockGroup({
  children,
  className,
  ...props
}: CodeBlockGroupProps) {
  return (
    <div
      className={cn("flex items-center justify-between", className)}
      {...props}
    >
      {children}
    </div>
  )
}

export { CodeBlockGroup, CodeBlockCode, CodeBlock }

import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

export function getSitePathname(
  pathname: string,
  basePath = process.env.NEXT_PUBLIC_BASE_PATH || ""
) {
  const base = basePath.replace(/\/+$/, "")
  const path =
    pathname === base || pathname.startsWith(`${base}/`)
      ? pathname.slice(base.length)
      : pathname
  return path.replace(/\/+$/, "") || "/"
}

/**
 * Get the base URL depending on the current environment
 */
export function getBaseUrl() {
  const basePath = (process.env.NEXT_PUBLIC_BASE_PATH || "").replace(/\/$/, "")
  const withBasePath = (url: string) => {
    const base = url.replace(/\/$/, "")
    return basePath && !base.endsWith(basePath) ? `${base}${basePath}` : base
  }
  // For server-side rendering, we need to use environment variables
  if (typeof window === "undefined") {
    // Check for Vercel-specific environment variables
    // Production URL takes precedence if available (works in all environments)
    if (process.env.NEXT_PUBLIC_VERCEL_PROJECT_PRODUCTION_URL) {
      return withBasePath(
        `https://${process.env.NEXT_PUBLIC_VERCEL_PROJECT_PRODUCTION_URL}`
      )
    }

    // For branch deployments
    if (process.env.NEXT_PUBLIC_VERCEL_BRANCH_URL) {
      return withBasePath(
        `https://${process.env.NEXT_PUBLIC_VERCEL_BRANCH_URL}`
      )
    }

    // For regular deployments
    if (process.env.NEXT_PUBLIC_VERCEL_URL) {
      return withBasePath(`https://${process.env.NEXT_PUBLIC_VERCEL_URL}`)
    }

    // Legacy support
    if (process.env.VERCEL_URL) {
      return withBasePath(`https://${process.env.VERCEL_URL}`)
    }

    // Fall back to explicitly set environment variables
    if (process.env.NEXT_PUBLIC_BASE_URL) {
      return withBasePath(process.env.NEXT_PUBLIC_BASE_URL)
    }

    // Default for development - check PORT env var first
    const port = process.env.PORT || 3000
    return withBasePath(
      process.env.NODE_ENV === "development" ? `http://localhost:${port}` : ""
    )
  }

  // For client-side, we can just use the browser's location
  return withBasePath(window.location.origin)
}

import { cn } from "@/lib/utils"
import { marked } from "marked"
import { memo, useId, useMemo } from "react"
import ReactMarkdown, { Components } from "react-markdown"
import remarkBreaks from "remark-breaks"
import remarkGfm from "remark-gfm"
import { CodeBlock, CodeBlockCode } from "./code-block"

export type MarkdownProps = {
  children: string
  id?: string
  className?: string
  components?: Partial<Components>
}

function parseMarkdownIntoBlocks(markdown: string): string[] {
  const tokens = marked.lexer(markdown)
  return tokens.map((token) => token.raw)
}

function extractLanguage(className?: string): string {
  if (!className) return "plaintext"
  const match = className.match(/language-(\w+)/)
  return match ? match[1] : "plaintext"
}

const INITIAL_COMPONENTS: Partial<Components> = {
  code: function CodeComponent({ className, children, ...props }) {
    const isInline =
      !props.node?.position?.start.line ||
      props.node?.position?.start.line === props.node?.position?.end.line

    if (isInline) {
      return (
        <span
          className={cn(
            "bg-primary-foreground rounded-sm px-1 font-mono text-sm",
            className
          )}
          {...props}
        >
          {children}
        </span>
      )
    }

    const language = extractLanguage(className)

    return (
      <CodeBlock className={className}>
        <CodeBlockCode code={children as string} language={language} />
      </CodeBlock>
    )
  },
  pre: function PreComponent({ children }) {
    return <>{children}</>
  },
}

const MemoizedMarkdownBlock = memo(
  function MarkdownBlock({
    content,
    components = INITIAL_COMPONENTS,
  }: {
    content: string
    components?: Partial<Components>
  }) {
    return (
      <ReactMarkdown
        remarkPlugins={[remarkGfm, remarkBreaks]}
        components={components}
      >
        {content}
      </ReactMarkdown>
    )
  },
  function propsAreEqual(prevProps, nextProps) {
    return prevProps.content === nextProps.content
  }
)

MemoizedMarkdownBlock.displayName = "MemoizedMarkdownBlock"

function MarkdownComponent({
  children,
  id,
  className,
  components = INITIAL_COMPONENTS,
}: MarkdownProps) {
  const generatedId = useId()
  const blockId = id ?? generatedId
  const blocks = useMemo(() => parseMarkdownIntoBlocks(children), [children])

  return (
    <div className={className}>
      {blocks.map((block, index) => (
        <MemoizedMarkdownBlock
          key={`${blockId}-block-${index}`}
          content={block}
          components={components}
        />
      ))}
    </div>
  )
}

const Markdown = memo(MarkdownComponent)
Markdown.displayName = "Markdown"

export { Markdown }

@import "tailwindcss";
@import "./theme.css";
@import "./typography.css";

/* ---------------------------------------------------------------------------
 * Dark mode strategy
 *
 * We use a class-based dark variant. Toggle dark mode by adding the `.dark`
 * class to <html> (a theme provider like `next-themes` can do this later).
 *
 *   <html class="dark">  →  every `dark:*` utility activates
 *
 * Components should NOT use `dark:` prefixes directly. Instead they reference
 * semantic color tokens (e.g. `bg-bg-primary`, `text-text-primary`) that flip
 * under `.dark` in styles/theme.css.
 * --------------------------------------------------------------------------- */
@custom-variant dark (&:where(.dark, .dark *));

/* The next theme is revealed by ThemeToggle from the exact interaction point.
 * Native view-transition crossfades are disabled so only the soft circular
 * clip-path animation runs; unsupported browsers simply ignore these rules. */
::view-transition-old(root),
::view-transition-new(root) {
  animation: none;
  mix-blend-mode: normal;
}

@keyframes ai-chat-text-shimmer {
  from {
    background-position: 200% center;
  }

  to {
    background-position: -100% center;
  }
}

.agent-progress-loading-text {
  color: transparent;
  background-image: linear-gradient(
    100deg,
    var(--color-text-secondary) 16%,
    var(--color-text-secondary) 38%,
    var(--color-text-primary) 50%,
    var(--color-text-secondary) 62%,
    var(--color-text-secondary) 84%
  );
  background-position: 200% center;
  background-size: 300% 100%;
  background-clip: text;
  -webkit-background-clip: text;
  animation: ai-chat-text-shimmer 3.4s linear infinite;
  will-change: background-position;
}

@media (prefers-reduced-motion: reduce) {
  .agent-progress-loading-text {
    color: var(--color-text-secondary);
    background-image: none;
    animation: none;
  }
}

::view-transition-old(root) {
  z-index: 1;
}

::view-transition-new(root) {
  z-index: 2;
}

/* Components often have their own hover/focus color transitions. Freeze them
 * while the browser captures the next theme so the expanding circle contains
 * the fully resolved new palette instead of a frame that is still fading from
 * the old one. This is what makes the click-origin reveal read clearly. */
.theme-transitioning,
.theme-transitioning * {
  transition: none !important;
}

/* Reset + base */
html,
body {
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  font-variant-ligatures: contextual;
  font-kerning: normal;
}

html {
  color-scheme: light;
  background-color: var(--color-background-full);
}
html.dark {
  color-scheme: dark;
}
body {
  background-color: var(--color-background-full);
  color: var(--color-text-primary);
}

/* Theme-aware monochrome BoardUI mark. Both images keep their intrinsic
 * dimensions while the root theme class decides which one participates in
 * layout, avoiding a light-logo flash during hydration. */
.theme-logo-dark,
.theme-asset-dark {
  display: none;
}
.dark .theme-logo-light,
.dark .theme-asset-light {
  display: none;
}
.dark .theme-logo-dark,
.dark .theme-asset-dark {
  display: block;
}

/* Tailwind expands shadow utilities into `--tw-shadow` at build time. Point
 * those generated utilities back to the live dark elevation tokens so the
 * class-based theme can adjust opacity without component-level overrides. */
.dark .shadow-2xs {
  --tw-shadow: var(--shadow-2xs);
}
.dark .shadow-xs {
  --tw-shadow: var(--shadow-xs);
}
.dark .shadow-sm {
  --tw-shadow: var(--shadow-sm);
}
.dark .shadow-md {
  --tw-shadow: var(--shadow-md);
}
.dark .shadow-lg {
  --tw-shadow: var(--shadow-lg);
}
.dark .shadow-xl {
  --tw-shadow: var(--shadow-xl);
}
.dark .shadow-card {
  --tw-shadow: var(--shadow-card);
}
.dark .shadow-dropdown {
  --tw-shadow: var(--shadow-dropdown);
}
.dark .shadow-sidebar {
  --tw-shadow: var(--shadow-sidebar);
}
.dark .shadow-waitlist {
  --tw-shadow: var(--shadow-waitlist);
}

/* Hide default expand arrow on Safari */
details summary::-webkit-details-marker {
  display: none;
}

/* Hide default number-input spinners */
input::-webkit-outer-spin-button,
input::-webkit-inner-spin-button {
  -webkit-appearance: none;
  margin: 0;
}
input[type="number"] {
  -moz-appearance: textfield;
}

/* Hide default search clear button */
input[type="search"]::-webkit-search-cancel-button {
  -webkit-appearance: none;
}

/* iOS Safari auto-zooms the page when a focused form field's font-size is
 * under 16px — our text-body-regular/medium tokens are 14px by design, so
 * bump just the font-size (not the whole token) on small screens instead of
 * changing the design system's type scale. */
@media (max-width: 639px) {
  input,
  select,
  textarea {
    font-size: 16px;
  }
}

/* Soft fade applied to an animated number each time its target changes */
@keyframes number-fade {
  from {
    opacity: 0.35;
  }
  to {
    opacity: 1;
  }
}
.animate-number-fade {
  animation: number-fade 220ms ease-out;
}

/* Recharts' accessibility layer makes the chart surface and its shapes
 * (bars, sectors, dots) keyboard-focusable, and Chrome paints the UA focus
 * outline around whichever one you click - a blue box around a ring segment
 * or a bar. Every chart card drives its own focus feedback (hover darkening,
 * headline swap), so the outline is noise: hide it across every Recharts
 * chart. Keyboard users still get the cards' own active states. */
.recharts-wrapper:focus,
.recharts-wrapper:focus-visible,
.recharts-wrapper :focus,
.recharts-wrapper :focus-visible {
  outline: none;
}

/* Liquid glass (landing nav + hero) — the rim light.
 *
 * A fixed conic gradient standing in for a bevel lit from a single direction:
 * bright along the top edge where the light source is, dark down both sides
 * where the glass turns away, and a weaker bounce along the bottom. It does
 * not rotate — a travelling highlight reads as an animation playing on the
 * control, where a real edge just sits there catching the room.
 *
 * Achromatic on purpose: highlights are white, shading is black, nothing in
 * between carries a hue.
 *
 * The two-layer mask (padding-box XOR full box) keeps only the 1.5px ring,
 * letting the gradient paint the stroke without covering the glass. */

.landing-glass-stroke {
  pointer-events: none;
  position: absolute;
  inset: 0;
  border-radius: inherit;
  /* Every value here is set inline by `LiquidGlassSurface` from the shared
   * glass config; the fallbacks are only for a bare use of the class. */
  padding: var(--lg-rim-width, 1.5px);
  background: conic-gradient(
    from var(--lg-rim-angle, 0deg),
    var(--lg-rim-hi, rgb(255 255 255 / 0.9)) 0deg,
    var(--lg-rim-sh, rgb(0 0 0 / 0.14)) 70deg,
    var(--lg-rim-dim, rgb(255 255 255 / 0.1)) 140deg,
    var(--lg-rim-bounce, rgb(255 255 255 / 0.55)) 180deg,
    var(--lg-rim-dim, rgb(255 255 255 / 0.1)) 220deg,
    var(--lg-rim-sh, rgb(0 0 0 / 0.14)) 290deg,
    var(--lg-rim-hi, rgb(255 255 255 / 0.9)) 360deg
  );
  /* Shorthands first, composites last: `-webkit-mask` aliases `mask` in
   * Chromium, so a shorthand placed after a composite silently resets it to
   * `add` — and an un-composited mask paints the full conic wash over the
   * button instead of a ring. */
  -webkit-mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  opacity: var(--lg-rim-o, 1);
  transition: opacity var(--lg-ms, 200ms) ease;
}

/* Liquid glass hover.
 *
 * Resting and hover values arrive together as inline custom properties, and
 * the swap happens here in CSS rather than in React state — hover then costs
 * a style recalculation instead of a re-render of everything inside the glass.
 * `.lg-hover` is the opt-in: a surface without it keeps its resting value. */
.lg-tint {
  background-color: var(--lg-tint, transparent);
  transition: background-color var(--lg-ms, 200ms) ease;
}

.lg-sheen {
  opacity: var(--lg-sheen, 0.5);
  transition: opacity var(--lg-ms, 200ms) ease;
}

.lg-host {
  box-shadow: var(--lg-shadow, none);
  transition:
    box-shadow var(--lg-ms, 200ms) ease,
    transform var(--lg-ms, 200ms) ease;
}

.lg-host:hover {
  box-shadow: var(--lg-shadow-hover, var(--lg-shadow, none));
  transform: translateY(var(--lg-lift, 0px)) scale(var(--lg-scale, 1));
}

.group:hover .lg-tint.lg-hover {
  background-color: var(--lg-tint-hover, var(--lg-tint, transparent));
}

.group:hover .lg-sheen.lg-hover {
  opacity: var(--lg-sheen-hover, var(--lg-sheen, 0.5));
}

.group:hover .landing-glass-stroke.lg-hover {
  opacity: var(--lg-rim-o-hover, var(--lg-rim-o, 1));
}

@media (prefers-reduced-motion: reduce) {
  .lg-tint,
  .lg-sheen,
  .lg-host,
  .landing-glass-stroke {
    transition: none;
  }

  .lg-host:hover {
    transform: none;
  }
}

/* Split-flap ("Solari" board) digit, used by the image-generation countdown.
 * Two leaves hinged on the card's centre seam:
 *   flap-fall  the outgoing digit's TOP half swings down over the incoming
 *              bottom half. Eased IN, because a real flap is falling under
 *              gravity — it accelerates — and it darkens as it tips away
 *              from the light.
 *   flap-rise  the incoming digit's BOTTOM half swings up from edge-on,
 *              starting exactly when the fall lands (delay = fall duration,
 *              `both` so it waits at 90deg instead of flashing flat). The
 *              small overshoot past 0deg is the slap against the stop —
 *              that bounce is what makes it read mechanical rather than
 *              like a plain rotation. */
@keyframes flap-fall {
  from {
    transform: rotateX(0deg);
    filter: brightness(1);
  }
  to {
    transform: rotateX(-90deg);
    filter: brightness(0.86);
  }
}
@keyframes flap-rise {
  0% {
    transform: rotateX(90deg);
    filter: brightness(0.86);
  }
  70% {
    transform: rotateX(-9deg);
  }
  86% {
    transform: rotateX(4deg);
  }
  100% {
    transform: rotateX(0deg);
    filter: brightness(1);
  }
}
.animate-flap-fall {
  transform-origin: bottom center;
  backface-visibility: hidden;
  animation: flap-fall 150ms cubic-bezier(0.55, 0, 0.9, 0.35) forwards;
}
.animate-flap-rise {
  transform-origin: top center;
  backface-visibility: hidden;
  animation: flap-rise 230ms cubic-bezier(0.25, 0.7, 0.35, 1) 150ms both;
}

@media (prefers-reduced-motion: reduce) {
  .animate-flap-fall,
  .animate-flap-rise {
    animation-duration: 1ms;
    animation-delay: 0ms;
  }
}

/* New-row entrance for the Storage settings table. Three coordinated
 * pieces (wrapper pairs with `grid grid-rows-[1fr]` + an overflow-hidden
 * middle layer, content carries the slide):
 *   row-grow-in   wrapper's grid track 0fr → 1fr — pushes the rows below
 *                 down smoothly.
 *   row-slide-in  content translates -100% → 0 with the SAME duration and
 *                 easing, so it stays glued to the growing wrapper's bottom
 *                 edge — visually the row slides out from underneath the
 *                 header row above it.
 *   row-fade-in   opacity/blur on a SHORTER clock than the movement — the
 *                 row is fully visible before it finishes settling (fades
 *                 must complete before movement ends). */
@keyframes row-grow-in {
  from {
    grid-template-rows: 0fr;
  }
  to {
    grid-template-rows: 1fr;
  }
}
@keyframes row-slide-in {
  from {
    translate: 0 -100%;
  }
}
@keyframes row-fade-in {
  from {
    opacity: 0;
    filter: blur(2px);
  }
}
.animate-row-grow-in {
  animation: row-grow-in 400ms ease-out;
}
.animate-row-slide-in {
  animation:
    row-slide-in 400ms ease-out,
    row-fade-in 240ms ease-out;
}

/* Reverse of the Storage row entrance. The content rises into the clipped
 * top edge while its grid track collapses, so the following rows move upward
 * continuously and the deleted row disappears beneath the header surface. */
@keyframes row-collapse-out {
  from {
    grid-template-rows: 1fr;
  }
  to {
    grid-template-rows: 0fr;
  }
}
@keyframes row-slide-out {
  to {
    translate: 0 -100%;
  }
}
@keyframes row-fade-out {
  to {
    opacity: 0;
    filter: blur(2px);
  }
}
.animate-row-collapse-out {
  animation: row-collapse-out 225ms ease-in forwards;
}
.animate-row-slide-out {
  animation:
    row-slide-out 225ms ease-in forwards,
    row-fade-out 160ms ease-in forwards;
}

@media (prefers-reduced-motion: reduce) {
  .animate-row-grow-in,
  .animate-row-slide-in,
  .animate-row-collapse-out,
  .animate-row-slide-out {
    animation-duration: 1ms;
  }
}

/* Transitions.dev — "Texts reveal", used by the Storage dropzone's content
 * swaps (idle copy ↔ file name + status line).
 *
 * Entrance (`.is-shown` on the parent): lines rise 12px from below while
 * un-blurring, 500ms on a soft-landing bezier, staggered 40ms per line so
 * the eye lands on the first line first.
 * Exit (`.is-hiding`): a single quiet 200ms opacity fade in place — no Y
 * return, no blur, no stagger — so the disappearance never reads as a
 * reverse reveal.
 *
 * Deviations from the original snippet: custom props are scoped to
 * `.t-stagger` instead of :root, and `.t-stagger-line` doesn't force
 * `display: block` so flex-based lines (the icon disc) keep their layout. */
.t-stagger {
  --stagger-dur: 500ms;
  --stagger-distance: 12px;
  --stagger-stagger: 40ms;
  --stagger-blur: 3px;
  --stagger-ease: cubic-bezier(0.22, 1, 0.36, 1);
}
.t-stagger-line {
  opacity: 0;
  transform: translateY(var(--stagger-distance));
  filter: blur(var(--stagger-blur));
  transition:
    opacity var(--stagger-dur) var(--stagger-ease),
    transform var(--stagger-dur) var(--stagger-ease),
    filter var(--stagger-dur) var(--stagger-ease);
  will-change: transform, opacity, filter;
}
.t-stagger-line--2 {
  transition-delay: var(--stagger-stagger);
}
.t-stagger-line--3 {
  transition-delay: calc(var(--stagger-stagger) * 2);
}
.t-stagger.is-shown .t-stagger-line {
  opacity: 1;
  transform: translateY(0);
  filter: blur(0);
}
.t-stagger.is-hiding .t-stagger-line {
  opacity: 0;
  transform: translateY(0);
  filter: blur(0);
  transition:
    opacity 200ms ease,
    transform 0s linear,
    filter 0s linear;
  transition-delay: 0s;
}
@media (prefers-reduced-motion: reduce) {
  .t-stagger-line {
    transition: none !important;
  }
}

/* Rolling-counter label swap: the old value lifts 5px and fades out while the
 * new one rises in from 5px below and fades in. */
@keyframes label-out {
  from {
    transform: translateY(0);
    opacity: 1;
  }
  to {
    transform: translateY(-10px);
    opacity: 0;
  }
}
@keyframes label-in {
  from {
    transform: translateY(10px);
    opacity: 0;
  }
  to {
    transform: translateY(0);
    opacity: 1;
  }
}
.animate-label-out {
  animation: label-out 220ms ease-out forwards;
}
.animate-label-in {
  animation: label-in 220ms ease-out;
}

/* Checkbox tick: draws the stroke on like it's being ticked by hand.
 * The path sets pathLength=1 so the dash math is resolution-independent. */
@keyframes check-draw {
  from {
    stroke-dashoffset: 1;
  }
  to {
    stroke-dashoffset: 0;
  }
}
.animate-check-draw {
  stroke-dasharray: 1;
  stroke-dashoffset: 1;
  animation: check-draw 200ms cubic-bezier(0.65, 0, 0.35, 1) forwards;
}
@media (prefers-reduced-motion: reduce) {
  .animate-check-draw {
    animation: none;
    stroke-dashoffset: 0;
  }
}

