}

.landing-showcase-card::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 60;
  pointer-events: none;
  border: 1px solid var(--color-border-button-default);
  border-radius: inherit;
  transition:
    border-color 280ms ease,
    box-shadow 280ms ease;
