export { AgentWebSearch } from "./application/web-search/web-search"
export type {
  AgentWebSearchProps,
  SearchResult,
} from "./application/web-search/web-search"

"use client"

import { Button } from "@/components/boardui/base/buttons/button"
import { Input } from "@/components/boardui/base/input/input"
import { cx } from "@/components/boardui/utils/cx"
import {
  Calendar,
  Copy,
  ExternalLink,
  Filter,
  Globe,
  RefreshCw,
  Search,
} from "lucide-react"
import { useState } from "react"

export interface SearchResult {
  id: string
  title: string
  url: string
  domain: string
  snippet: string
  aiSummary?: string
  publishedDate?: string
  credibilityScore?: number
  relevanceScore?: number
  imageUrl?: string
}
export interface AgentWebSearchProps {
  query?: string
  results?: SearchResult[]
  isSearching?: boolean
  selectedDomains?: string[]
  dateFilter?: "all" | "day" | "week" | "month" | "year"
  onSearch?: (query: string) => void
  onResultClick?: (result: SearchResult) => void
  onCopyLink?: (url: string) => void
  onDomainFilter?: (domains: string[]) => void
  onDateFilter?: (filter: "all" | "day" | "week" | "month" | "year") => void
  onRefresh?: () => void
  showBottomActions?: boolean
  className?: string
  timestamp?: string
}
const dateOptions = ["all", "day", "week", "month", "year"] as const
export function AgentWebSearch({
  query = "AI agent interfaces",
  results = [],
  isSearching = false,
  selectedDomains = [],
  dateFilter = "all",
  onSearch,
  onResultClick,
  onCopyLink,
  onDomainFilter,
  onDateFilter,
  onRefresh,
  showBottomActions = true,
  className,
  timestamp = "2:34 PM",
}: AgentWebSearchProps) {
  const [localQuery, setLocalQuery] = useState(query)
  const [filtersOpen, setFiltersOpen] = useState(false)
  const domains = Array.from(new Set(results.map((result) => result.domain)))
  const toggleDomain = (domain: string) =>
    onDomainFilter?.(
      selectedDomains.includes(domain)
        ? selectedDomains.filter((item) => item !== domain)
        : [...selectedDomains, domain]
    )
  return (
    <section
      className={cx(
        "border-separator-border bg-background-primary-default overflow-hidden rounded-2xl border",
        className
      )}
    >
      <header className="border-separator-border border-b p-3">
        <form
          className="flex gap-2"
          onSubmit={(event) => {
            event.preventDefault()
            onSearch?.(localQuery)
          }}
        >
          <Input
            aria-label="Search query"
            value={localQuery}
            onChange={setLocalQuery}
            placeholder="Search the web"
            isDisabled={isSearching}
            leadingIcon={Search}
          />
          <Button
            type="submit"
            size="medium"
            disabled={isSearching || !localQuery.trim()}
            leadingIcon={isSearching ? RefreshCw : undefined}
          >
            {isSearching ? "Searching" : "Search"}
          </Button>
          <Button
            size="medium"
            variant="secondary"
            iconOnly
            leadingIcon={Filter}
            aria-label="Search filters"
            aria-expanded={filtersOpen}
            onClick={() => setFiltersOpen((open) => !open)}
          />
        </form>
        {filtersOpen && (
          <div className="bg-background-secondary-default mt-3 grid gap-3 rounded-lg p-3 sm:grid-cols-2">
            <fieldset>
              <legend className="text-caption-1-medium text-text-secondary mb-2">
                Date
              </legend>
              <div className="flex flex-wrap gap-1">
                {dateOptions.map((date) => (
                  <Button
                    key={date}
                    size="small"
                    variant={dateFilter === date ? "primary" : "ghost"}
                    onClick={() => onDateFilter?.(date)}
                  >
                    {date === "all" ? "Any time" : `Past ${date}`}
                  </Button>
                ))}
              </div>
            </fieldset>
            {domains.length > 0 && (
              <fieldset>
                <legend className="text-caption-1-medium text-text-secondary mb-2">
                  Domains
                </legend>
                <div className="flex flex-wrap gap-1">
                  {domains.map((domain) => (
                    <Button
                      key={domain}
                      size="small"
                      variant={
                        selectedDomains.includes(domain) ? "primary" : "ghost"
                      }
                      onClick={() => toggleDomain(domain)}
                    >
                      {domain}
                    </Button>
                  ))}
                </div>
              </fieldset>
            )}
          </div>
        )}
      </header>
      <div className="divide-separator-border divide-y">
        {isSearching ? (
          <div className="text-body-2-regular text-text-secondary flex min-h-48 items-center justify-center gap-2">
            <RefreshCw className="size-4 animate-spin" />
            Searching the web
          </div>
        ) : (
          results.map((result, index) => (
            <article
              key={result.id}
              className="hover:bg-background-secondary-hover px-4 py-3"
            >
              <div className="flex items-start gap-3">
                <span className="text-caption-1-regular text-text-tertiary pt-0.5 tabular-nums">
                  {index + 1}
                </span>
                <button
                  type="button"
                  onClick={() => onResultClick?.(result)}
                  className="min-w-0 flex-1 text-left"
                >
                  <h3 className="text-body-medium">{result.title}</h3>
                  <p className="text-caption-1-regular text-text-secondary mt-0.5 flex flex-wrap gap-x-2">
                    <span className="inline-flex items-center gap-1">
                      <Globe className="size-3.5" />
                      {result.domain}
                    </span>
                    {result.publishedDate && (
                      <span className="inline-flex items-center gap-1">
                        <Calendar className="size-3.5" />
                        {new Date(result.publishedDate).toLocaleDateString()}
                      </span>
                    )}
                    {result.credibilityScore !== undefined && (
                      <span>
                        {Math.round(result.credibilityScore * 100)}% credibility
                      </span>
                    )}
                    {result.relevanceScore !== undefined && (
                      <span>
                        {Math.round(result.relevanceScore * 100)}% relevance
                      </span>
                    )}
                  </p>
                  <p className="text-body-2-regular text-text-secondary mt-2 leading-5">
                    {result.snippet}
                  </p>
                  {result.aiSummary && (
                    <p className="border-separator-border text-body-2-regular mt-2 border-l pl-3 leading-5">
                      {result.aiSummary}
                    </p>
                  )}
                </button>
                <div className="flex gap-1">
                  <Button
                    size="small"
                    variant="ghost"
                    iconOnly
                    leadingIcon={ExternalLink}
                    aria-label={`Open ${result.title}`}
                    onClick={() =>
                      window.open(result.url, "_blank", "noopener,noreferrer")
                    }
                  />
                  {onCopyLink && (
                    <Button
                      size="small"
                      variant="ghost"
                      iconOnly
                      leadingIcon={Copy}
                      aria-label={`Copy ${result.title} link`}
                      onClick={() => onCopyLink(result.url)}
                    />
                  )}
                </div>
              </div>
            </article>
          ))
        )}
        {!isSearching && results.length === 0 && (
          <div className="grid min-h-48 place-items-center p-8 text-center">
            <div>
              <p className="text-body-medium">No search results</p>
              <p className="text-body-2-regular text-text-secondary mt-1">
                Run a search to view sources.
              </p>
            </div>
          </div>
        )}
      </div>
      {showBottomActions && (
        <footer className="border-separator-border flex items-center justify-between gap-3 border-t px-4 py-2.5">
          <p className="text-caption-1-regular text-text-secondary">
            {results.length} results | Updated {timestamp}
          </p>
          {onRefresh && (
            <Button
              size="small"
              variant="ghost"
              leadingIcon={RefreshCw}
              onClick={onRefresh}
            >
              Refresh
            </Button>
          )}
        </footer>
      )}
    </section>
  )
}

import { cx, sortCx } from "@/components/boardui/utils/cx"
import type {
  AnchorHTMLAttributes,
  ButtonHTMLAttributes,
  ComponentType,
  ReactNode,
  Ref,
} from "react"
import { Focusable } from "react-aria-components"

/**
 * Figma source: Board UI → Buttons (node 3656:13819).
 *
 * Variant matrix from Figma:
 *   Type     = Primary | Secondary | Ghost | Danger
 *   Size     = Medium  | Small | Xs
 *   State    = Default | Hover | Active | Disabled        (CSS pseudo)
 *   OnlyIcon = false   | true
 *
 * Sizing (1:1 with Figma):
 *
 *                       Medium                    Small                     Xs
 *   container          h=36, p=8,   r=10         h=32, px=8 py=6, r=8      h=24, px=8, r=4
 *   gap                 2px                       2px                      1.33px→1
 *   icon                20×20                     18×18                    14×14
 *   label wrapper       px=4                      px=2                     px=2
 *   text style          Body 1/Medium             Body 1/Medium            Caption 1/Semibold
 *   icon-only square    36×36 (content-derived)   32×32 (forced size)      24×24 (forced size)
 *
 * `xs` is the smallest tier - first needed for the calendar template's
 * event-details modal ("Join" / edit-icon buttons, node 3920:10954), which
 * scales every dimension down by the same ~0.667 factor from Figma; the
 * table above rounds those to clean pixel values rather than reproducing
 * the fractional source numbers.
 *
 * Icons are rendered by the component itself via the `leadingIcon` /
 * `trailingIcon` props so the consumer can't pass the wrong size. Pass
 * a Remix Icon component reference (`RiAddLine`, not `<RiAddLine />`).
 *
 * For icon-only buttons:
 *   <Button iconOnly leadingIcon={RiAddLine} aria-label="Add" />
 *
 * The HTML `type` prop is preserved; Figma's "Type" enum is renamed to
 * `variant` to avoid the clash.
 */

type ButtonVariant = "primary" | "secondary" | "ghost" | "danger"
type ButtonSize = "medium" | "small" | "xs"

type IconComponent = ComponentType<{
  className?: string
  "aria-hidden"?: boolean | "true" | "false"
}>

export interface ButtonProps
  extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, "children"> {
  variant?: ButtonVariant
  size?: ButtonSize
  iconOnly?: boolean
  leadingIcon?: IconComponent
  trailingIcon?: IconComponent
  children?: ReactNode
  ref?: Ref<HTMLButtonElement>
}

export interface ButtonLinkProps
  extends Omit<AnchorHTMLAttributes<HTMLAnchorElement>, "children"> {
  variant?: ButtonVariant
  size?: ButtonSize
  iconOnly?: boolean
  leadingIcon?: IconComponent
  trailingIcon?: IconComponent
  children?: ReactNode
  ref?: Ref<HTMLAnchorElement>
}

const styles = sortCx({
  base: [
    "inline-flex items-center justify-center gap-0.5 whitespace-nowrap overflow-hidden",
    "font-sans select-none cursor-pointer",
    "button-press-motion",
    "outline-none focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-border-focus-ring",
    "disabled:cursor-not-allowed aria-disabled:cursor-not-allowed",
  ].join(" "),

  // Base shape per size (used when label is present OR medium icon-only).
  size: {
    medium: "h-9 rounded-2lg p-2 text-body-medium",
    small: "h-8 rounded-lg px-2 py-1.5 text-body-medium",
    xs: "h-6 rounded-sm px-2 text-caption-1-semibold",
  },

  // Icon-only override:
  //   Medium → keep p-2; w expands from content (8+20+8 = 36) → square.
  //   Small  → Figma forces 32×32 even though 8+18+8=34, so we hard-set size-8
  //            and zero the padding; the inner flex centers the 18px icon.
  //   Xs     → forces 24×24, content-centered - used for the calendar
  //            template's edit-icon buttons (timezone/participants/reminder).
  iconOnlySize: {
    medium: "", // base size already produces 36×36 with a 20px icon
    small: "size-8 p-0", // hard 32×32, content-centered
    xs: "size-6 p-0", // hard 24×24, content-centered
  },

  icon: {
    medium: "size-5 shrink-0", // 20px
    small: "size-[18px] shrink-0", // 18px
    xs: "size-3.5 shrink-0", // 14px
  },

  label: {
    medium: "inline-flex items-center justify-center px-1 shrink-0", // px=4
    small: "inline-flex items-center justify-center px-0.5 shrink-0", // px=2
    xs: "inline-flex items-center justify-center px-0.5 shrink-0", // px=2
  },

  variant: {
    primary: [
      "bg-button-primary",
      "disabled:text-button-primary-disabled-foreground disabled:shadow-none",
      "aria-disabled:text-button-primary-disabled-foreground aria-disabled:shadow-none",
    ].join(" "),
    danger: [
      "bg-button-danger text-text-white shadow-xs",
      "disabled:text-foreground-disabled-danger disabled:shadow-none",
      "aria-disabled:text-foreground-disabled-danger aria-disabled:shadow-none",
    ].join(" "),
    secondary: [
      "bg-background-primary-default text-text-primary",
      "border border-border-button-default shadow-xs",
      "hover:bg-background-primary-hover  hover:border-border-button-hover",
      "active:bg-background-primary-active active:border-border-button-active",
      "disabled:bg-background-primary-disabled disabled:border-border-button-default disabled:text-text-tertiary disabled:shadow-none",
      "aria-disabled:bg-background-primary-disabled aria-disabled:border-border-button-default aria-disabled:text-text-tertiary aria-disabled:shadow-none",
    ].join(" "),
    ghost: [
      "bg-button-ghost-background text-button-ghost-foreground",
      "hover:bg-button-ghost-hover active:bg-button-ghost-active",
      "disabled:bg-button-ghost-disabled disabled:text-button-ghost-disabled-foreground disabled:shadow-none",
      "aria-disabled:bg-button-ghost-disabled aria-disabled:text-button-ghost-disabled-foreground aria-disabled:shadow-none",
    ].join(" "),
  },
})

export function Button({
  variant = "primary",
  size = "medium",
  iconOnly = false,
  leadingIcon: Leading,
  trailingIcon: Trailing,
  children,
  className,
  type = "button",
