// Adapted from Blocks ai-04 (MIT), pinned in components/blocks-so/SOURCE.json.
import {
  IconAdjustmentsHorizontal,
  IconArrowUp,
  IconCamera,
  IconCirclePlus,
  IconClipboard,
  IconFileUpload,
  IconHistory,
  IconLink,
  IconMap,
  IconPaperclip,
  IconPlayerPlay,
  IconPlus,
  IconReportAnalytics,
  IconSparkles,
  IconTemplate,
  IconX,
} from "@tabler/icons-react"
