// Adapted from Blocks ai-05 and its AI Elements dependencies (MIT), pinned in SOURCE.json.
import {
  IconAdjustmentsHorizontal,
  IconArrowDown,
  IconArrowUp,
  IconBolt,
  IconLoader2,
  IconPaperclip,
  IconPlus,
} from "@tabler/icons-react"
