"use client"

import { Button } from "@/components/boardui/base/buttons/button"
import { cx } from "@/components/boardui/utils/cx"
import { Check } from "lucide-react"
import { AnimatePresence, motion, useReducedMotion } from "motion/react"
import * as React from "react"

export type ApprovalAnswer = string | string[]
export interface ApprovalQuestion {
  id: string
  label: string
  type?: "text" | "radio" | "check"
  options?: string[]
  required?: boolean
  value?: ApprovalAnswer
  placeholder?: string
}
export interface ApprovalCardProps {
  title: string
  description?: string
  questions?: ApprovalQuestion[]
  currentStep?: number
  answers?: Record<string, ApprovalAnswer>
  submitted?: boolean
  allowSkip?: boolean
  onStepChange?: (step: number) => void
  onAnswerChange?: (id: string, value: ApprovalAnswer) => void
  onSubmit?: (answers: Record<string, ApprovalAnswer>) => void
  onSkip?: (id: string) => void
  onBack?: (step: number) => void
  onApprove?: () => void
  onDecline?: () => void
  onChange?: (id: string, value: string) => void
  className?: string
}
export function isApprovalAnswerValid(
  question: ApprovalQuestion,
  answer: ApprovalAnswer | undefined
) {
  if (!question.required) return true
  return Array.isArray(answer) ? answer.length > 0 : Boolean(answer?.trim())
}
export function ApprovalCard({
  title,
  description,
  questions = [],
  currentStep,
  answers,
  submitted,
  allowSkip = true,
  onStepChange,
  onAnswerChange,
  onSubmit,
  onSkip,
  onBack,
  onApprove,
  onDecline,
  onChange,
  className,
}: ApprovalCardProps) {
  const reduce = useReducedMotion() ?? false
  const [localStep, setLocalStep] = React.useState(0)
  const [localAnswers, setLocalAnswers] = React.useState<
    Record<string, ApprovalAnswer>
  >(() =>
    Object.fromEntries(
      questions
        .filter((question) => question.value !== undefined)
        .map((question) => [question.id, question.value!])
    )
  )
  const [localSubmitted, setLocalSubmitted] = React.useState(false)
  const step = Math.min(
    Math.max(currentStep ?? localStep, 0),
    Math.max(questions.length - 1, 0)
  )
  const values = answers ?? localAnswers
  const done = submitted ?? localSubmitted
  const question = questions[step]
  const answer = question ? values[question.id] : undefined
  const valid = question ? isApprovalAnswerValid(question, answer) : true
  const changeStep = (next: number) => {
    if (currentStep === undefined) setLocalStep(next)
    onStepChange?.(next)
  }
  const changeAnswer = (id: string, value: ApprovalAnswer) => {
    if (answers === undefined)
      setLocalAnswers((current) => ({ ...current, [id]: value }))
    onAnswerChange?.(id, value)
    if (typeof value === "string") onChange?.(id, value)
  }
  const finish = () => {
    if (!valid) return
    if (submitted === undefined) setLocalSubmitted(true)
    onSubmit?.(values)
    onApprove?.()
  }
  const next = () => {
    if (!valid) return
    if (step >= questions.length - 1) finish()
    else changeStep(step + 1)
  }
  if (done)
    return (
      <section
        className={cx(
          "border-separator-border bg-background-primary-default max-w-sm rounded-xl border p-4",
          className
        )}
      >
        <p className="flex items-center gap-2 text-sm font-medium">
          <Check className="size-4 text-green-600" />
          Answers submitted
        </p>
      </section>
    )
  if (!question)
    return (
      <section
        className={cx(
          "border-separator-border bg-background-primary-default max-w-sm rounded-xl border p-4",
          className
        )}
      >
        <h3 className="text-sm font-semibold">{title}</h3>
        <p className="text-text-secondary mt-2 text-[13px]">
          No questions provided.
        </p>
        {onApprove && (
          <div className="mt-4 flex justify-end">
            <Button size="small" onClick={finish}>
              Approve
            </Button>
          </div>
        )}
      </section>
    )
  const type = question.type ?? "text"
  const selected = Array.isArray(answer) ? answer : []
  return (
    <section
      className={cx(
        "border-separator-border bg-background-primary-default w-full max-w-sm rounded-xl border p-4",
        className
      )}
    >
      <header>
        <div className="flex items-center justify-between gap-3">
          <h3 className="text-sm font-semibold">{title}</h3>
          <span className="text-text-secondary text-xs tabular-nums">
            {step + 1} / {questions.length}
          </span>
        </div>
        {description && (
          <p className="text-text-secondary mt-1 text-[13px] leading-5">
            {description}
          </p>
        )}
      </header>
      <div className="mt-4 min-h-[104px]">
        <AnimatePresence initial={false} mode="wait">
          <motion.div
            key={question.id}
            initial={reduce ? false : { opacity: 0, y: 4 }}
            animate={{ opacity: 1, y: 0 }}
            exit={reduce ? undefined : { opacity: 0, y: -4 }}
            transition={{ duration: reduce ? 0 : 0.16 }}
          >
            <p className="text-sm font-medium">
              {question.label}
              {question.required && (
                <span className="ml-1 text-red-600">*</span>
              )}
            </p>
            {type === "text" ? (
              <input
                value={typeof answer === "string" ? answer : ""}
                placeholder={question.placeholder}
                onChange={(event) =>
                  changeAnswer(question.id, event.target.value)
                }
                className="bg-background-tertiary-default focus:ring-border-focus-ring mt-2 h-9 w-full rounded-lg px-3 text-[13px] outline-none focus:ring-2"
              />
            ) : (
              <div
                role={type === "radio" ? "radiogroup" : "group"}
                aria-label={question.label}
                className="mt-2 flex flex-wrap gap-2"
              >
                {question.options?.map((option) => {
                  const on = selected.includes(option) || answer === option
                  return (
                    <button
                      key={option}
                      type="button"
                      role={type === "radio" ? "radio" : "checkbox"}
                      aria-checked={on}
                      onClick={() =>
                        changeAnswer(
                          question.id,
                          type === "radio"
                            ? option
                            : on
                              ? selected.filter((item) => item !== option)
                              : [...selected, option]
                        )
                      }
                      className={cx(
                        "min-h-8 rounded-full border px-3 text-xs",
                        on
                          ? "border-text-primary bg-button-primary text-text-white"
                          : "border-separator-border hover:bg-background-secondary-default"
                      )}
                    >
                      {option}
                    </button>
                  )
                })}
              </div>
            )}
            {!valid && (
              <p className="mt-2 text-xs text-red-700 dark:text-red-400">
                Choose or enter an answer to continue.
              </p>
            )}
          </motion.div>
        </AnimatePresence>
      </div>
      <footer className="border-separator-border mt-5 flex items-center justify-between border-t pt-3">
        <div className="flex gap-1">
          {onDecline && (
            <Button variant="ghost" size="xs" onClick={onDecline}>
              Decline
            </Button>
          )}
          {step > 0 && (
            <Button
              variant="ghost"
              size="xs"
              onClick={() => {
                onBack?.(step - 1)
                changeStep(step - 1)
              }}
            >
              Back
            </Button>
          )}
        </div>
        <div className="flex gap-1">
          {allowSkip && (
            <Button
              variant="ghost"
              size="xs"
              onClick={() => {
                onSkip?.(question.id)
                if (step >= questions.length - 1) {
                  if (submitted === undefined) setLocalSubmitted(true)
                  onSubmit?.(values)
                  onApprove?.()
                } else changeStep(step + 1)
              }}
            >
              Skip
            </Button>
          )}
          <Button size="xs" disabled={!valid} onClick={next}>
            {step >= questions.length - 1 ? "Submit" : "Continue"}
          </Button>
        </div>
      </footer>
    </section>
  )
}

import { cx, sortCx } from "@/components/boardui/utils/cx"
import type {
  AnchorHTMLAttributes,
  ButtonHTMLAttributes,
  ComponentType,
  ReactNode,
  Ref,
} from "react"
import { Focusable } from "react-aria-components"

/**
 * Figma source: Board UI → Buttons (node 3656:13819).
 *
 * Variant matrix from Figma:
 *   Type     = Primary | Secondary | Ghost | Danger
 *   Size     = Medium  | Small | Xs
 *   State    = Default | Hover | Active | Disabled        (CSS pseudo)
 *   OnlyIcon = false   | true
 *
 * Sizing (1:1 with Figma):
 *
 *                       Medium                    Small                     Xs
 *   container          h=36, p=8,   r=10         h=32, px=8 py=6, r=8      h=24, px=8, r=4
 *   gap                 2px                       2px                      1.33px→1
 *   icon                20×20                     18×18                    14×14
 *   label wrapper       px=4                      px=2                     px=2
 *   text style          Body 1/Medium             Body 1/Medium            Caption 1/Semibold
 *   icon-only square    36×36 (content-derived)   32×32 (forced size)      24×24 (forced size)
 *
 * `xs` is the smallest tier - first needed for the calendar template's
 * event-details modal ("Join" / edit-icon buttons, node 3920:10954), which
 * scales every dimension down by the same ~0.667 factor from Figma; the
 * table above rounds those to clean pixel values rather than reproducing
 * the fractional source numbers.
 *
 * Icons are rendered by the component itself via the `leadingIcon` /
 * `trailingIcon` props so the consumer can't pass the wrong size. Pass
 * a Remix Icon component reference (`RiAddLine`, not `<RiAddLine />`).
 *
 * For icon-only buttons:
 *   <Button iconOnly leadingIcon={RiAddLine} aria-label="Add" />
 *
 * The HTML `type` prop is preserved; Figma's "Type" enum is renamed to
 * `variant` to avoid the clash.
 */

type ButtonVariant = "primary" | "secondary" | "ghost" | "danger"
type ButtonSize = "medium" | "small" | "xs"

type IconComponent = ComponentType<{
  className?: string
  "aria-hidden"?: boolean | "true" | "false"
}>

export interface ButtonProps
  extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, "children"> {
  variant?: ButtonVariant
  size?: ButtonSize
  iconOnly?: boolean
  leadingIcon?: IconComponent
  trailingIcon?: IconComponent
  children?: ReactNode
  ref?: Ref<HTMLButtonElement>
}

export interface ButtonLinkProps
  extends Omit<AnchorHTMLAttributes<HTMLAnchorElement>, "children"> {
  variant?: ButtonVariant
  size?: ButtonSize
  iconOnly?: boolean
  leadingIcon?: IconComponent
  trailingIcon?: IconComponent
  children?: ReactNode
  ref?: Ref<HTMLAnchorElement>
}

const styles = sortCx({
  base: [
    "inline-flex items-center justify-center gap-0.5 whitespace-nowrap overflow-hidden",
    "font-sans select-none cursor-pointer",
    "button-press-motion",
    "outline-none focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-border-focus-ring",
    "disabled:cursor-not-allowed aria-disabled:cursor-not-allowed",
  ].join(" "),

  // Base shape per size (used when label is present OR medium icon-only).
  size: {
    medium: "h-9 rounded-2lg p-2 text-body-medium",
    small: "h-8 rounded-lg px-2 py-1.5 text-body-medium",
    xs: "h-6 rounded-sm px-2 text-caption-1-semibold",
  },

  // Icon-only override:
  //   Medium → keep p-2; w expands from content (8+20+8 = 36) → square.
  //   Small  → Figma forces 32×32 even though 8+18+8=34, so we hard-set size-8
  //            and zero the padding; the inner flex centers the 18px icon.
  //   Xs     → forces 24×24, content-centered - used for the calendar
  //            template's edit-icon buttons (timezone/participants/reminder).
  iconOnlySize: {
    medium: "", // base size already produces 36×36 with a 20px icon
    small: "size-8 p-0", // hard 32×32, content-centered
    xs: "size-6 p-0", // hard 24×24, content-centered
  },

  icon: {
    medium: "size-5 shrink-0", // 20px
    small: "size-[18px] shrink-0", // 18px
    xs: "size-3.5 shrink-0", // 14px
  },

  label: {
    medium: "inline-flex items-center justify-center px-1 shrink-0", // px=4
    small: "inline-flex items-center justify-center px-0.5 shrink-0", // px=2
    xs: "inline-flex items-center justify-center px-0.5 shrink-0", // px=2
  },

  variant: {
    primary: [
      "bg-button-primary",
      "disabled:text-button-primary-disabled-foreground disabled:shadow-none",
      "aria-disabled:text-button-primary-disabled-foreground aria-disabled:shadow-none",
    ].join(" "),
    danger: [
      "bg-button-danger text-text-white shadow-xs",
      "disabled:text-foreground-disabled-danger disabled:shadow-none",
      "aria-disabled:text-foreground-disabled-danger aria-disabled:shadow-none",
    ].join(" "),
    secondary: [
      "bg-background-primary-default text-text-primary",
      "border border-border-button-default shadow-xs",
      "hover:bg-background-primary-hover  hover:border-border-button-hover",
      "active:bg-background-primary-active active:border-border-button-active",
      "disabled:bg-background-primary-disabled disabled:border-border-button-default disabled:text-text-tertiary disabled:shadow-none",
      "aria-disabled:bg-background-primary-disabled aria-disabled:border-border-button-default aria-disabled:text-text-tertiary aria-disabled:shadow-none",
    ].join(" "),
    ghost: [
      "bg-button-ghost-background text-button-ghost-foreground",
      "hover:bg-button-ghost-hover active:bg-button-ghost-active",
      "disabled:bg-button-ghost-disabled disabled:text-button-ghost-disabled-foreground disabled:shadow-none",
      "aria-disabled:bg-button-ghost-disabled aria-disabled:text-button-ghost-disabled-foreground aria-disabled:shadow-none",
    ].join(" "),
  },
})

export function Button({
  variant = "primary",
  size = "medium",
  iconOnly = false,
  leadingIcon: Leading,
  trailingIcon: Trailing,
  children,
  className,
  type = "button",
  ref,
  ...props
}: ButtonProps) {
  return (
    <Focusable isDisabled={props.disabled}>
      <button
        ref={ref}
        type={type}
        className={cx(
          styles.base,
          styles.size[size],
          styles.variant[variant],
          iconOnly && styles.iconOnlySize[size],
          className
        )}
        {...props}
      >
        {Leading ? <Leading className={styles.icon[size]} aria-hidden /> : null}
        {iconOnly && !Leading && children != null ? (
          <span
            aria-hidden
            className={cx(
              styles.icon[size],
              "inline-flex items-center justify-center [&>svg]:size-full"
            )}
          >
            {children}
          </span>
        ) : null}
        {!iconOnly && children !== undefined && children !== null && (
          <span className={styles.label[size]}>{children}</span>
        )}
        {!iconOnly && Trailing ? (
          <Trailing className={styles.icon[size]} aria-hidden />
        ) : null}
      </button>
    </Focusable>
  )
}

/** Anchor counterpart to Button for navigational actions. */
export function ButtonLink({
  variant = "primary",
  size = "medium",
  iconOnly = false,
  leadingIcon: Leading,
  trailingIcon: Trailing,
  children,
  className,
  ref,
  ...props
}: ButtonLinkProps) {
  return (
    <Focusable>
      <a
        ref={ref}
        className={cx(
          styles.base,
          styles.size[size],
          styles.variant[variant],
          iconOnly && styles.iconOnlySize[size],
          className
        )}
        {...props}
      >
        {Leading ? <Leading className={styles.icon[size]} aria-hidden /> : null}
        {iconOnly && !Leading && children != null ? (
          <span
            aria-hidden
            className={cx(
              styles.icon[size],
              "inline-flex items-center justify-center [&>svg]:size-full"
            )}
          >
            {children}
          </span>
        ) : null}
        {!iconOnly && children !== undefined && children !== null && (
          <span className={styles.label[size]}>{children}</span>
        )}
        {!iconOnly && Trailing ? (
          <Trailing className={styles.icon[size]} aria-hidden />
        ) : null}
      </a>
    </Focusable>
  )
}

/** Style maps, exported for advanced composition and the dev Design Tuner. */
export const buttonStyles = styles

import { extendTailwindMerge } from "tailwind-merge";

/**
 * Text-style classes from styles/typography.css.
 *
 * IMPORTANT: every text-* utility we define via @theme (e.g. `text-body-medium`,
 * `text-title-1-semibold`) must be listed here. Otherwise tailwind-merge — which
 * has no view of our Tailwind theme — treats them as text-color utilities and
 * silently drops them when they appear in the same className as a real color
 * (`text-foreground-full`, `text-text-primary`, etc).
 *
 * If you add or rename a text style in typography.css, mirror the change here.
 */
const TEXT_FAMILIES = [
  "large-title",
  "display-1",
  "display-2",
  "display-3",
  "display-4",
  "title-1",
  "title-2",
  "title-3",
  "headline",
  "body",
  "body-2",
  "caption-1",
  "caption-2",
] as const;

const TEXT_WEIGHTS = ["regular", "medium", "semibold", "bold"] as const;

const TEXT_STYLE_SUFFIXES = TEXT_FAMILIES.flatMap((family) =>
  TEXT_WEIGHTS.map((weight) => `${family}-${weight}`),
);

const twMerge = extendTailwindMerge({
  extend: {
    classGroups: {
      "font-size": [{ text: TEXT_STYLE_SUFFIXES }],
    },
  },
});

/**
 * Merge Tailwind classes safely. Last-write-wins on conflicting utilities.
 */
export const cx = twMerge;

/**
 * Identity helper that gives the Tailwind IntelliSense extension a hook for
 * sorting classes inside style objects (the extension doesn't sort inside
 * plain object literals otherwise).
 */
export function sortCx<
  T extends Record<
    string,
    string | number | Record<string, string | number | Record<string, string | number>>
  >,
>(classes: T): T {
  return classes;
}

@import "tailwindcss";
@import "./theme.css";
@import "./typography.css";

/* ---------------------------------------------------------------------------
 * Dark mode strategy
 *
 * We use a class-based dark variant. Toggle dark mode by adding the `.dark`
 * class to <html> (a theme provider like `next-themes` can do this later).
 *
 *   <html class="dark">  →  every `dark:*` utility activates
