"use client"

import { cx } from "@/components/boardui/utils/cx"
import { Check, Circle, GripVertical, LoaderCircle } from "lucide-react"
import * as React from "react"

export interface FlowchartNode {
  id: string
  label: string
  detail?: string
  status: "pending" | "running" | "complete"
  x?: number
  y?: number
  kind?: string
  condition?: { field: string; operator: string; value: string }
}
export interface FlowchartEdge {
  from: string
  to: string
}
export interface FlowchartProps {
  nodes: FlowchartNode[]
  edges?: FlowchartEdge[]
  onSelect?: (id: string) => void
  onNodeMove?: (id: string, position: { x: number; y: number }) => void
  onConditionChange?: (
    id: string,
    condition: FlowchartNode["condition"]
  ) => void
  className?: string
}
export function Flowchart({
  nodes,
  edges,
  onSelect,
  onNodeMove,
  onConditionChange,
  className,
}: FlowchartProps) {
  const initial = React.useMemo(
    () =>
      Object.fromEntries(
        nodes.map((node, index) => [
          node.id,
          { x: node.x ?? 50, y: node.y ?? 38 + index * 116 },
        ])
      ),
    [nodes]
  )
  const [positions, setPositions] = React.useState(initial)
  const links =
    edges ??
    nodes
      .slice(0, -1)
      .map((node, index) => ({ from: node.id, to: nodes[index + 1].id }))
  const drag = React.useRef<{ id: string; dx: number; dy: number } | null>(null)
  const move = (event: React.PointerEvent<HTMLDivElement>) => {
    if (!drag.current) return
    const rect = event.currentTarget.getBoundingClientRect()
    const next = {
      x: Math.max(
        8,
        Math.min(rect.width - 208, event.clientX - rect.left - drag.current.dx)
      ),
      y: Math.max(
        8,
        Math.min(rect.height - 84, event.clientY - rect.top - drag.current.dy)
      ),
    }
    setPositions((current) => ({ ...current, [drag.current!.id]: next }))
    onNodeMove?.(drag.current.id, next)
  }
  return (
    <div
      onPointerMove={move}
      onPointerUp={() => {
        drag.current = null
      }}
      onPointerCancel={() => {
        drag.current = null
      }}
      className={cx(
        "border-separator-border bg-background-primary-default relative h-[360px] min-w-[640px] overflow-hidden rounded-xl border",
        className
      )}
      style={{
        backgroundImage:
          "radial-gradient(circle, color-mix(in srgb, currentColor 12%, transparent) 1px, transparent 1px)",
        backgroundSize: "18px 18px",
      }}
    >
      <svg
        className="pointer-events-none absolute inset-0 h-full w-full"
        aria-hidden
      >
        {links.map((edge) => {
          const from = positions[edge.from],
            to = positions[edge.to]
          if (!from || !to) return null
          const x1 = from.x + 100,
            y1 = from.y + 72,
            x2 = to.x + 100,
            y2 = to.y
          return (
            <path
              key={`${edge.from}-${edge.to}`}
              d={`M${x1},${y1} C${x1},${(y1 + y2) / 2} ${x2},${(y1 + y2) / 2} ${x2},${y2}`}
              fill="none"
              stroke="currentColor"
              strokeOpacity=".25"
              strokeWidth="1.5"
            />
          )
        })}
      </svg>
      {nodes.map((node) => {
        const position = positions[node.id] ?? { x: 0, y: 0 }
        const Icon =
          node.status === "complete"
            ? Check
            : node.status === "running"
              ? LoaderCircle
              : Circle
        return (
          <article
            key={node.id}
            className="border-separator-border bg-background-primary-default absolute w-[200px] touch-none rounded-lg border shadow-sm"
            style={{ transform: `translate(${position.x}px, ${position.y}px)` }}
          >
            <button
              type="button"
              onPointerDown={(event) => {
                const rect =
                  event.currentTarget.parentElement!.getBoundingClientRect()
                drag.current = {
                  id: node.id,
                  dx: event.clientX - rect.left,
                  dy: event.clientY - rect.top,
                }
                event.currentTarget.setPointerCapture(event.pointerId)
              }}
              onClick={() => onSelect?.(node.id)}
              className="border-separator-border flex min-h-9 w-full cursor-grab items-center gap-2 border-b px-3 text-left active:cursor-grabbing"
            >
              <GripVertical className="text-text-secondary size-4" />
              <span className="flex-1 text-xs font-medium">
                {node.kind ?? "Step"}
              </span>
              <Icon
                className={cx(
                  "text-text-secondary size-4",
                  node.status === "running" && "animate-spin"
                )}
              />
            </button>
            <div className="p-3">
              <h3 className="text-[13px] font-medium">{node.label}</h3>
              {node.detail && (
                <p className="text-text-secondary mt-1 text-xs">
                  {node.detail}
                </p>
              )}
              {node.condition && (
                <div className="mt-2 flex flex-wrap gap-1 text-xs">
                  <input
                    aria-label="Condition field"
                    value={node.condition.field}
                    onChange={(event) =>
                      onConditionChange?.(node.id, {
                        ...node.condition!,
                        field: event.target.value,
                      })
                    }
                    className="bg-background-secondary-default w-16 rounded-sm px-1.5 py-1"
                  />
                  <input
                    aria-label="Condition operator"
                    value={node.condition.operator}
                    onChange={(event) =>
                      onConditionChange?.(node.id, {
                        ...node.condition!,
                        operator: event.target.value,
                      })
                    }
                    className="bg-background-secondary-default w-12 rounded-sm px-1.5 py-1"
                  />
                  <input
                    aria-label="Condition value"
                    value={node.condition.value}
                    onChange={(event) =>
                      onConditionChange?.(node.id, {
                        ...node.condition!,
                        value: event.target.value,
                      })
                    }
                    className="bg-background-secondary-default min-w-0 flex-1 rounded-sm px-1.5 py-1"
                  />
                </div>
              )}
            </div>
          </article>
        )
      })}
    </div>
  )
}

import { extendTailwindMerge } from "tailwind-merge";

/**
 * Text-style classes from styles/typography.css.
 *
 * IMPORTANT: every text-* utility we define via @theme (e.g. `text-body-medium`,
 * `text-title-1-semibold`) must be listed here. Otherwise tailwind-merge — which
 * has no view of our Tailwind theme — treats them as text-color utilities and
 * silently drops them when they appear in the same className as a real color
 * (`text-foreground-full`, `text-text-primary`, etc).
 *
 * If you add or rename a text style in typography.css, mirror the change here.
 */
const TEXT_FAMILIES = [
  "large-title",
  "display-1",
  "display-2",
  "display-3",
  "display-4",
  "title-1",
  "title-2",
  "title-3",
  "headline",
  "body",
  "body-2",
  "caption-1",
  "caption-2",
] as const;

const TEXT_WEIGHTS = ["regular", "medium", "semibold", "bold"] as const;

const TEXT_STYLE_SUFFIXES = TEXT_FAMILIES.flatMap((family) =>
  TEXT_WEIGHTS.map((weight) => `${family}-${weight}`),
);

const twMerge = extendTailwindMerge({
  extend: {
    classGroups: {
      "font-size": [{ text: TEXT_STYLE_SUFFIXES }],
    },
  },
});

/**
 * Merge Tailwind classes safely. Last-write-wins on conflicting utilities.
 */
export const cx = twMerge;

/**
 * Identity helper that gives the Tailwind IntelliSense extension a hook for
 * sorting classes inside style objects (the extension doesn't sort inside
 * plain object literals otherwise).
 */
export function sortCx<
  T extends Record<
    string,
    string | number | Record<string, string | number | Record<string, string | number>>
  >,
>(classes: T): T {
  return classes;
}

@import "tailwindcss";
@import "./theme.css";
@import "./typography.css";

/* ---------------------------------------------------------------------------
 * Dark mode strategy
 *
 * We use a class-based dark variant. Toggle dark mode by adding the `.dark`
 * class to <html> (a theme provider like `next-themes` can do this later).
 *
 *   <html class="dark">  →  every `dark:*` utility activates
 *
 * Components should NOT use `dark:` prefixes directly. Instead they reference
 * semantic color tokens (e.g. `bg-bg-primary`, `text-text-primary`) that flip
 * under `.dark` in styles/theme.css.
 * --------------------------------------------------------------------------- */
@custom-variant dark (&:where(.dark, .dark *));

/* The next theme is revealed by ThemeToggle from the exact interaction point.
 * Native view-transition crossfades are disabled so only the soft circular
 * clip-path animation runs; unsupported browsers simply ignore these rules. */
::view-transition-old(root),
::view-transition-new(root) {
  animation: none;
  mix-blend-mode: normal;
}

@keyframes ai-chat-text-shimmer {
  from {
    background-position: 200% center;
  }

  to {
    background-position: -100% center;
  }
}

.agent-progress-loading-text {
  color: transparent;
  background-image: linear-gradient(
    100deg,
    var(--color-text-secondary) 16%,
    var(--color-text-secondary) 38%,
    var(--color-text-primary) 50%,
    var(--color-text-secondary) 62%,
    var(--color-text-secondary) 84%
  );
  background-position: 200% center;
  background-size: 300% 100%;
  background-clip: text;
  -webkit-background-clip: text;
  animation: ai-chat-text-shimmer 3.4s linear infinite;
  will-change: background-position;
}

@media (prefers-reduced-motion: reduce) {
  .agent-progress-loading-text {
    color: var(--color-text-secondary);
    background-image: none;
    animation: none;
  }
}

::view-transition-old(root) {
  z-index: 1;
}

::view-transition-new(root) {
  z-index: 2;
}

/* Components often have their own hover/focus color transitions. Freeze them
 * while the browser captures the next theme so the expanding circle contains
 * the fully resolved new palette instead of a frame that is still fading from
 * the old one. This is what makes the click-origin reveal read clearly. */
.theme-transitioning,
.theme-transitioning * {
  transition: none !important;
}

/* Reset + base */
html,
body {
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  font-variant-ligatures: contextual;
  font-kerning: normal;
}

html {
  color-scheme: light;
  background-color: var(--color-background-full);
}
html.dark {
  color-scheme: dark;
}
body {
  background-color: var(--color-background-full);
  color: var(--color-text-primary);
}

/* Theme-aware monochrome BoardUI mark. Both images keep their intrinsic
 * dimensions while the root theme class decides which one participates in
 * layout, avoiding a light-logo flash during hydration. */
.theme-logo-dark,
.theme-asset-dark {
  display: none;
}
.dark .theme-logo-light,
.dark .theme-asset-light {
  display: none;
}
.dark .theme-logo-dark,
.dark .theme-asset-dark {
  display: block;
}

/* Tailwind expands shadow utilities into `--tw-shadow` at build time. Point
 * those generated utilities back to the live dark elevation tokens so the
 * class-based theme can adjust opacity without component-level overrides. */
.dark .shadow-2xs {
  --tw-shadow: var(--shadow-2xs);
}
.dark .shadow-xs {
  --tw-shadow: var(--shadow-xs);
}
.dark .shadow-sm {
  --tw-shadow: var(--shadow-sm);
}
.dark .shadow-md {
  --tw-shadow: var(--shadow-md);
}
.dark .shadow-lg {
  --tw-shadow: var(--shadow-lg);
}
.dark .shadow-xl {
