    0 1px 1px 0 rgb(0 0 0 / 0.14),
    0 4px 4px 0 rgb(0 0 0 / 0.10);
  --shadow-sidebar:
    0 1px 0 0 rgb(0 0 0 / 0.10),
    0 1px 12px 0 rgb(0 0 0 / 0.16),
    0 0 1px 0 rgb(0 0 0 / 0.42);
