/** A raster of the platform's real pointer. `width`/`height` in CSS px,
 *  `hotX`/`hotY` the click point. `centerX`/`centerY` optionally override
 *  the body centre (default: alpha centroid). */
export interface CursorSprite {
  src: string;
  width: number;
  height: number;
  hotX: number;
  hotY: number;
  centerX?: number;
  centerY?: number;
}

let sprite: CursorSprite | null = null;
let spriteImg: HTMLImageElement | null = null;
/** The display's backing scale (1 or 2 on a Mac). The OS cursor is drawn at
 *  this scale regardless of page zoom; `devicePixelRatio` is backing scale
 *  × browser zoom, so the sprite is drawn at `spriteDpr / devicePixelRatio`
 *  of its CSS size to stay the cursor's true size. A page loaded already
 *  zoomed can't tell the two apart; ≥ 1.5 reads as a Retina display. */
let spriteDpr = 0;

/** CSS scale that keeps the sprite at the OS cursor's device-pixel size. */
function zoomScale(): number {
  const dpr = window.devicePixelRatio || 1;
  return spriteDpr > 0 ? spriteDpr / dpr : 1;
}

/** Put the sprite's hotspot on the pointer, at the zoom-compensated size. */
function placeCursor(x: number, y: number): void {
  if (!curEl || !sprite) return;
  const k = zoomScale();
  const tx = (x - sprite.hotX * k).toFixed(2), ty = (y - sprite.hotY * k).toFixed(2);
  curEl.style.transform = k === 1 ? `translate3d(${tx}px,${ty}px,0)` : `translate3d(${tx}px,${ty}px,0) scale(${k.toFixed(4)})`;
}
/** Off-switch flipped by the fail-safes. An exception disables for the
 *  session; the frame-time watchdog only pauses for a while (`disabledUntil`). */
let cursorDisabled = false;
let disabledUntil = 0;
let slowFrames = 0;
/** Opaque body pixels (sprite-local CSS px, centred on `bodyC`), the alpha
 *  centroid, and a hard mask of the body — built once per sprite. The
 *  silhouette extent in any direction comes from `bodyPts` per frame. */
let bodyPts: Float32Array | null = null;
const bodyC = { x: 0, y: 0 };
/** Hard body alpha at the sprite canvas's device resolution, cached by dpr. */
let bodyAlpha: Uint8ClampedArray | null = null;
let bodyAlphaDpr = 0;

function bodyAlphaFor(img: HTMLImageElement, sp: CursorSprite, dpr: number, w: number, h: number): Uint8ClampedArray | null {
  if (bodyAlpha && bodyAlphaDpr === dpr && bodyAlpha.length === w * h) return bodyAlpha;
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  const g = c.getContext('2d', { willReadFrequently: true });
  if (!g) return null;
  g.scale(dpr, dpr);
  g.drawImage(img, 0, 0, sp.width, sp.height);
  const d = g.getImageData(0, 0, w, h).data;
  const a = new Uint8ClampedArray(w * h);
  for (let i = 0, j = 3; i < a.length; i++, j += 4) a[i] = d[j] >= 128 ? 255 : 0;
  bodyAlpha = a; bodyAlphaDpr = dpr;
  return a;
}

/**
 * Multiply the canvas alpha by a per-pixel factor, in pixel data. Used in
 * place of `destination-in`, which WebKit intermittently misapplies on
 * accelerated canvases (a frame of the unclipped image — a white flash).
 */
function alphaPass(g: CanvasRenderingContext2D, w: number, h: number, factor: (x: number, y: number, i: number) => number): void {
  const img = g.getImageData(0, 0, w, h);
  const px = img.data;
  for (let y = 0, i = 0, j = 3; y < h; y++) {
    for (let x = 0; x < w; x++, i++, j += 4) {
      const a = px[j];
      if (a === 0) continue;
      const f = factor(x, y, i);
      px[j] = f >= 1 ? a : f <= 0 ? 0 : a * f;
    }
  }
  g.putImageData(img, 0, 0);
}

function analyseSprite(img: HTMLImageElement, sp: CursorSprite): void {
  const S = 2;
  const c = document.createElement('canvas');
  c.width = Math.ceil(sp.width * S); c.height = Math.ceil(sp.height * S);
  const g = c.getContext('2d', { willReadFrequently: true });
  if (!g) return;
  g.drawImage(img, 0, 0, c.width, c.height);
  const d = g.getImageData(0, 0, c.width, c.height).data;
  const pts: number[] = [];
  let sx = 0, sy = 0, n = 0;
  for (let y = 0; y < c.height; y++) {
    for (let x = 0; x < c.width; x++) {
      const a = d[(y * c.width + x) * 4 + 3];
      if (a < 128) continue;
      const px = (x + 0.5) / S, py = (y + 0.5) / S;
      pts.push(px, py); sx += px; sy += py; n++;
    }
  }
  if (n === 0) return;
  bodyC.x = sp.centerX ?? sx / n;
  bodyC.y = sp.centerY ?? sy / n;
  const arr = new Float32Array(pts.length);
  for (let i = 0; i < pts.length; i += 2) { arr[i] = pts[i] - bodyC.x; arr[i + 1] = pts[i + 1] - bodyC.y; }
  bodyPts = arr;
}

/** Farthest the body extends from its centre along direction (ux, uy). */
function bodyExtent(ux: number, uy: number): number {
  if (!bodyPts) return 0;
  let best = -Infinity;
  for (let i = 0; i < bodyPts.length; i += 2) {
    const dot = bodyPts[i] * ux + bodyPts[i + 1] * uy;
    if (dot > best) best = dot;
  }
  return best === -Infinity ? 0 : best;
}

/** Supply the pointer raster (or null to turn the cursor effect off). Must
 *  match the OS pointer pixel-for-pixel, or the swap is visible. */
export function setCursorSprite(next: CursorSprite | null): void {
  sprite = next;
  spriteImg = null; bodyPts = null; bodyAlpha = null;
  cursorDisabled = false; disabledUntil = 0; slowFrames = 0;
  const dprNow = typeof window !== 'undefined' ? window.devicePixelRatio || 1 : 1;
  spriteDpr = dprNow >= 1.5 ? 2 : 1;
  hideCursor();
  if (!next || typeof Image === 'undefined') return;
  const img = new Image();
  img.decoding = 'async';
  img.onload = () => { if (sprite === next) { analyseSprite(img, next); spriteImg = img; kick(); } };
  img.src = next.src;
}

// ─── Tracking ─────────────────────────────────────────────────────────────

let attached = 0;
let tracking = false;
let raf = 0;
let last = 0;
let px = Number.NaN, py = Number.NaN; // live pointer, NaN when gone
let lpx = 0, lpy = 0;                 // last known, for the fade-out
let uS = 0;                           // smoothed proximity weight (reach)
let uCS = 0;                          // smoothed proximity weight (cursorReach)
let near: MetalFxInstance | null = null;
const _near = { d: 0, nx: 0, ny: 0, k: 1, left: 0, top: 0 };
const _pt = { x: 0, y: 0 };
const _sc = { r: 255, g: 255, b: 255 }; // smoothed spill tint

let spillEl: HTMLDivElement | null = null;
let spillBg = '';
let spillSize = -1;
let spillBlur = -1;
let spillShown = false;

/** Reference-counted: MetalFx calls attach on mount, detach on unmount. */
export function attachCursorLight(): void {
  attached++;
  ensureTracking();
}

export function detachCursorLight(): void {
  attached = Math.max(0, attached - 1);
  if (attached === 0) stopTracking();
}

const mq = (q: string): boolean => typeof window.matchMedia === 'function' && window.matchMedia(q).matches;

/** Whether replacing the OS cursor is acceptable right now. Re-checked
 *  every frame; all of these can change while the page is open. */
function cursorSwapAllowed(): boolean {
  if (cursorDisabled || performance.now() < disabledUntil || !sprite || !spriteImg) return false;
  if (mq('(prefers-reduced-motion: reduce)') || mq('(forced-colors: active)')) return false;
  if (!mq('(pointer: fine)') || !mq('(hover: hover)')) return false;
  const vv = window.visualViewport;
  if (vv && Math.abs(vv.scale - 1) > 0.001) return false;
  return true;
}

function ensureTracking(): void {
  if (tracking || attached === 0 || typeof document === 'undefined') return;
  if (!mq('(pointer: fine)')) return;
  tracking = true;
  document.addEventListener('pointermove', onMove, { passive: true });
  document.addEventListener('pointerleave', onLeave);
  document.addEventListener('pointercancel', onLeave);
  document.addEventListener('keydown', onKey, { passive: true });
  document.addEventListener('visibilitychange', onLeave);
  window.addEventListener('blur', onLeave);
}

function stopTracking(): void {
  if (!tracking) return;
  tracking = false;
  document.removeEventListener('pointermove', onMove);
  document.removeEventListener('pointerleave', onLeave);
  document.removeEventListener('pointercancel', onLeave);
  document.removeEventListener('keydown', onKey);
  document.removeEventListener('visibilitychange', onLeave);
  window.removeEventListener('blur', onLeave);
  if (raf !== 0) { cancelAnimationFrame(raf); raf = 0; }
  if (near) { near.cursorLight = null; near = null; }
  uS = 0; uCS = 0;
  if (spillEl) { spillEl.remove(); spillEl = null; spillBg = ''; spillSize = -1; spillBlur = -1; spillShown = false; }
  hideCursor();
  if (curEl) { curEl.remove(); curEl = null; }
}

let pointerIsMouse = true;
/** Set on keydown, cleared by the next pointer move — keeps the sprite off
 *  while someone types even though the loop keeps running nearby. */
let typing = false;

function onMove(e: PointerEvent): void {
  pointerIsMouse = e.pointerType === 'mouse' || e.pointerType === '';
  typing = false;
  px = lpx = e.clientX;
  py = lpy = e.clientY;
  // While the sprite is up, hide the OS cursor and move the sprite *inside*
  // the event, not in the next frame. WebKit re-evaluates the cursor only on
  // mouse moves: a hide applied one frame late, after the pointer crossed
  // into a new element and stopped, leaves the real arrow showing until the
  // next move. Moving the sprite here also trims a frame of lag.
  if (curShown && curEl) {
    if (pointerIsMouse && claimCursor(px, py)) {
      placeCursor(px, py);
    } else {
      hideCursor();
    }
  }
  kick();
}

/** macOS hides the pointer while typing; match it, and never leave a fake
 *  arrow sitting over a field someone is keyboard-navigating. */
function onKey(): void {
  typing = true;
  hideCursor();
}

function onLeave(): void {
  px = py = Number.NaN;
  kick();
}

function kick(): void {
  if (!tracking || raf !== 0) return;
  last = performance.now();
  raf = requestAnimationFrame(step);
}

// ─── Geometry ─────────────────────────────────────────────────────────────

/**
 * Signed distance from a box-local point to the ring's outer outline
 * (positive outside), writing the nearest outline point to `out`.
 */
function nearestOutlinePoint(
  lx: number, ly: number, W: number, H: number, R: number, kind: 'pill' | 'circle', out: { x: number; y: number }
): number {
  const rr = kind === 'circle' ? Math.min(W, H) / 2 : Math.max(0, Math.min(R, Math.min(W, H) / 2));
  const cx = W / 2, cy = H / 2;
  const hx = Math.max(0, W / 2 - rr), hy = Math.max(0, H / 2 - rr);
  const qx = Math.max(-hx, Math.min(hx, lx - cx));
  const qy = Math.max(-hy, Math.min(hy, ly - cy));
  const dx = lx - cx - qx, dy = ly - cy - qy;
  const len = Math.hypot(dx, dy);
  if (len > 1e-6) {
    out.x = cx + qx + (dx / len) * rr;
    out.y = cy + qy + (dy / len) * rr;
    return len - rr;
  }
  // Inside the straight-edged core: nearest side.
  const dl = lx, dr = W - lx, dt = ly, db = H - ly;
  const m = Math.min(dl, dr, dt, db);
  if (m === dl) { out.x = 0; out.y = ly; }
  else if (m === dr) { out.x = W; out.y = ly; }
  else if (m === dt) { out.x = lx; out.y = 0; }
  else { out.x = lx; out.y = H; }
  return -m;
}

// ─── Pointer sprite ───────────────────────────────────────────────────────

let curEl: HTMLDivElement | null = null;
let curCanvas: HTMLCanvasElement | null = null;
let curCtx: CanvasRenderingContext2D | null = null;
let refCanvas: HTMLCanvasElement | null = null;
let refCtx: CanvasRenderingContext2D | null = null;
let refCtxReadable = false;
let curDpr = 0, curW = 0, curH = 0;
let curShown = false;
/** Root-level hide (stable while the sprite is up — no churn as the pointer
 *  crosses elements, which is what WebKit shows as flicker), plus one
 *  element-level hide for elements that set their own `cursor: default`. */
let rootHidden = false;
let rootPrev = '';
let hiddenEl: HTMLElement | null = null;
let hiddenPrev = '';

const TEXTY = /^(INPUT|TEXTAREA|SELECT)$/;
/** Per-element verdicts (true = plain arrow, claimable) so a pointermove
 *  doesn't force style resolution on every event. Cleared on release. */
let verdicts = new WeakMap<HTMLElement, boolean>();
let lastClaimMs = 0;
let lastTarget: HTMLElement | null = null;
/** Elements where `cursor: auto` means something other than the arrow. */
function isTextTarget(el: HTMLElement): boolean {
  let n: HTMLElement | null = el;
  while (n && n !== document.body) {
    if (TEXTY.test(n.tagName) || n.isContentEditable) return true;
    n = n.parentElement;
  }
  return false;
}

function ensureCursor(): boolean {
  if (curEl) return true;
  const el = document.createElement('div');
  el.className = 'metal-fx-cursor';
  el.setAttribute('aria-hidden', 'true');
  el.style.cssText = 'position:fixed;left:0;top:0;pointer-events:none;z-index:2147483001;will-change:transform;transform-origin:0 0;display:none';
  const c = document.createElement('canvas');
  c.style.display = 'block';
  el.appendChild(c);
  document.body.appendChild(el);
  const ctx = c.getContext('2d');
  const rc = document.createElement('canvas');
  const rctx = rc.getContext('2d');
  if (!ctx || !rctx) { el.remove(); return false; }
  curEl = el; curCanvas = c; curCtx = ctx; refCanvas = rc; refCtx = rctx;
  return true;
}

/** Hide the OS cursor on the element under the pointer, if it shows the
 *  plain arrow there. Returns whether the sprite may show. */
function claimCursor(x: number, y: number, force = false): boolean {
  // Hit-testing forces layout; while the bend is animating that layout is
  // dirty on every frame, so cap this at ~one per frame unless forced.
  const now = performance.now();
  if (!force && rootHidden && now - lastClaimMs < 12) return true;
  lastClaimMs = now;
  const target = document.elementFromPoint(x, y) as HTMLElement | null;
  if (!target) { releaseCursor(); return false; }
  if (target === lastTarget && rootHidden) return true;
  lastTarget = target;
  let ok = verdicts.get(target);
  if (ok === undefined) {
    ok = !isTextTarget(target);
    if (ok) { const cur = getComputedStyle(target).cursor; ok = cur === 'auto' || cur === 'default' || cur === 'none'; }
    verdicts.set(target, ok);
  }
  if (!ok) { releaseCursor(); return false; }
  if (!rootHidden) {
    const root = document.documentElement;
    rootPrev = root.style.cursor;
    root.style.cursor = 'none';
    rootHidden = true;
  }
  // Elements that set `cursor: default` / `auto` themselves don't inherit the
  // root's `none`; hide on them directly (rare — chips, drag handles).
  if (target !== hiddenEl) {
    if (hiddenEl) { hiddenEl.style.cursor = hiddenPrev; hiddenEl = null; hiddenPrev = ''; }
    if (getComputedStyle(target).cursor !== 'none') {
      hiddenEl = target; hiddenPrev = target.style.cursor;
      target.style.cursor = 'none';
    }
  }
  return true;
}

function releaseCursor(): void {
  if (hiddenEl) {
    if (hiddenEl.isConnected) hiddenEl.style.cursor = hiddenPrev;
    hiddenEl = null; hiddenPrev = '';
  }
  if (rootHidden) {
    document.documentElement.style.cursor = rootPrev;
    rootHidden = false; rootPrev = '';
  }
  lastTarget = null;
  verdicts = new WeakMap();
}

function hideCursor(): void {
  releaseCursor();
  if (curEl && curShown) { curEl.style.display = 'none'; curShown = false; }
}

function drawCursor(inst: MetalFxInstance, cfg: CursorLightConfig, env: number): void {
  if (!curCtx || !refCtx || !curCanvas || !refCanvas || !curEl || !sprite || !spriteImg) return;
  const sp = sprite;
  const dpr = Math.min(3, window.devicePixelRatio || 1);
  if (dpr !== curDpr || sp.width !== curW || sp.height !== curH) {
    curDpr = dpr; curW = sp.width; curH = sp.height;
    curCanvas.width = refCanvas.width = Math.ceil(sp.width * dpr);
    curCanvas.height = refCanvas.height = Math.ceil(sp.height * dpr);
    curCanvas.style.width = `${sp.width}px`;
    curCanvas.style.height = `${sp.height}px`;
  }
  if (!refCtxReadable) { refCtx = refCanvas.getContext('2d', { willReadFrequently: true }); refCtxReadable = true; if (!refCtx) return; }
  const ctx = curCtx, rctx = refCtx;
  const W = sp.width, H = sp.height;

  // The pointer itself.
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.clearRect(0, 0, curCanvas.width, curCanvas.height);
  ctx.scale(dpr, dpr);
  ctx.drawImage(spriteImg, 0, 0, W, H);

  // Light from the ring. Direction from the body centre to the outline
  // point nearest it; the mirror plane sits on the body's silhouette in that
  // direction, so only the face that looks at the ring catches light —
  // cursor left of the button lights the pointer's right side, and so on.
  const rx = _near.left + _near.nx * _near.k, ry = _near.top + _near.ny * _near.k;
  const ccx = lpx - sp.hotX + bodyC.x, ccy = lpy - sp.hotY + bodyC.y;
  const dx = rx - ccx, dy = ry - ccy;
  const dist = Math.hypot(dx, dy);
  const ux0 = dist > 0.01 ? dx / dist : 1, uy0 = dist > 0.01 ? dy / dist : 0;
  const e = bodyExtent(ux0, uy0) + cfg.cursorEdge;
  const dEdge = Math.max(0, dist - e);
  const f0 = Math.max(1, cfg.cursorFalloff);
  const falloff = 1 / (1 + (dEdge / f0) * (dEdge / f0));
  // Sample the ring's colour a little inside its outer edge — the edge pixel
  // itself is anti-aliased toward transparent and reads dark.
  const bcx = inst.cssWidth / 2, bcy = inst.cssHeight / 2;
  const inx = bcx - _near.nx, iny = bcy - _near.ny, inl = Math.hypot(inx, iny) || 1;
  const ins = inst.mask ? 0 : inst.ringCssPx * 0.5 + 1;
  const sxp = _near.nx + (inx / inl) * ins, syp = _near.ny + (iny / inl) * ins;
  const pk = sampleShaderPeakAt(inst, sxp, syp, 4);
  const lum = pk.lum;
  const pr = pk.r, pg = pk.g, pb = pk.b;
  const spec = cfg.cursorStrength * falloff * env;
  const diff = cfg.cursorDiffuse * falloff * (0.5 + 0.5 * Math.min(1, lum / 0.5)) * env;
  if (dist > 0.01 && spec + diff > 0.005) {
    const ux = dx / dist, uy = dy / dist, a = Math.atan2(uy, ux);
    const sdepth = Math.max(0.1, Math.min(1, cfg.cursorDepth));
    // Mirror plane: on the face of the pointer that looks at the ring.
    const mx = bodyC.x + e * ux, my = bodyC.y + e * uy;
    const fl = Math.max(1, cfg.cursorReach);

    rctx.setTransform(1, 0, 0, 1, 0, 0);
    rctx.clearRect(0, 0, refCanvas.width, refCanvas.height);
    rctx.scale(dpr, dpr);

    // Specular: the ring seen in the pointer's surface.
    if (spec > 0.005) {
      rctx.save();
      rctx.filter = cfg.cursorBlur > 0 ? `blur(${cfg.cursorBlur}px)` : 'none';
      const zoom = Math.max(1, cfg.cursorZoom);
      rctx.translate(mx, my);
      rctx.rotate(a);
      rctx.scale(-1, 1);                                // mirror across the plane
      rctx.translate((dist - e) * sdepth, 0);           // ring point, depth-compressed, behind the plane
      rctx.rotate(-a);
      rctx.scale(zoom, zoom);                           // magnify around the ring point
      const o = inst.overscan, k = _near.k;
      const passes = Math.max(1, Math.ceil(spec));
      rctx.globalAlpha = Math.min(1, spec / passes);
      rctx.globalCompositeOperation = 'lighter';
      const srcCanvas = inst.mask && inst.rawCanvas ? inst.rawCanvas : inst.canvas;
      for (let i = 0; i < passes; i++) {
        rctx.drawImage(srcCanvas, -(_near.nx + o) * k, -(_near.ny + o) * k, (inst.cssWidth + 2 * o) * k, (inst.cssHeight + 2 * o) * k);
      }
      rctx.restore();
      // Fade into the body away from the mirror plane.
      const inv = 1 / dpr, fl1 = 1 / fl;
      alphaPass(rctx, refCanvas.width, refCanvas.height, (x, y) => {
        const behind = -(((x + 0.5) * inv - mx) * ux + ((y + 0.5) * inv - my) * uy);
        return behind <= 0 ? 1 : 1 - behind * fl1;
      });
    }

    // Diffuse: the lit rim, in the ring's colour at that point.
    if (diff > 0.005) {
      const peak = Math.max(pr, pg, pb) || 1;
      const cr = Math.round((pr * 255) / peak), cg = Math.round((pg * 255) / peak), cb = Math.round((pb * 255) / peak);
      const dl = fl * 1.2;
      const g = rctx.createLinearGradient(mx + 0.5 * ux, my + 0.5 * uy, mx - dl * ux, my - dl * uy);
      const a0 = Math.min(1, diff);
      g.addColorStop(0, `rgba(${cr},${cg},${cb},${a0.toFixed(3)})`);
      g.addColorStop(0.45, `rgba(${cr},${cg},${cb},${(a0 * 0.4).toFixed(3)})`);
      g.addColorStop(1, `rgba(${cr},${cg},${cb},0)`);
      rctx.globalCompositeOperation = 'lighter';
      rctx.fillStyle = g;
      rctx.fillRect(0, 0, W, H);
      rctx.globalCompositeOperation = 'source-over';
    }

    // Keep the light on the pointer's body only (not its soft shadow).
    const body = bodyAlphaFor(spriteImg, sp, dpr, refCanvas.width, refCanvas.height);
    if (body) alphaPass(rctx, refCanvas.width, refCanvas.height, (_x, _y, i) => body[i] === 0 ? 0 : 1);

    ctx.globalCompositeOperation = 'lighter';
    ctx.drawImage(refCanvas, 0, 0, W, H);
    ctx.globalCompositeOperation = 'source-over';
  }

  placeCursor(lpx, lpy);
  if (!curShown) { curEl.style.display = ''; curShown = true; }
}

// ─── Frame ────────────────────────────────────────────────────────────────

function ensureSpill(): HTMLDivElement {
  if (spillEl) return spillEl;
  const el = document.createElement('div');
  el.className = 'metal-fx-cursor-spill';
  el.setAttribute('aria-hidden', 'true');
  el.style.cssText =
    'position:fixed;left:0;top:0;pointer-events:none;z-index:2147483000;border-radius:50%;' +
    'mix-blend-mode:plus-lighter;will-change:transform,opacity;opacity:0;display:none';
  document.body.appendChild(el);
  spillEl = el;
  return el;
}

function hideSpill(): void {
  if (!spillEl || !spillShown) return;
  spillEl.style.display = 'none';
  spillEl.style.opacity = '0';
  spillShown = false;
}

function step(now: number): void {
  raf = 0;
  if (!tracking) return;
  // Own work only — `now` is the frame timestamp and includes whatever else
  // ran in this frame (React renders, other rAF callbacks), which is not
  // ours to be blamed for.
  const t0 = performance.now();
  try {
    stepInner(now);
  } catch (err) {
    // Whatever broke, the user must get their cursor back.
    cursorDisabled = true;
    hideCursor();
    hideSpill();
    if (near) { near.cursorLight = null; near = null; }
    if (typeof console !== 'undefined') console.warn('metal-fx: cursor light disabled after error', err);
    return;
  }
  // Watchdog: this should cost well under a millisecond. If it keeps not
  // doing so — huge pages, a pathological elementFromPoint — pause the
  // cursor swap for a few seconds and try again.
  const took = performance.now() - t0;
  if (took > 6) {
    if (++slowFrames >= 20) { slowFrames = 0; disabledUntil = performance.now() + 5000; hideCursor(); }
  } else if (slowFrames > 0) slowFrames--;
}

function stepInner(now: number): void {
  const cfg = CURSOR_LIGHT;
  const dt = Math.min(0.05, Math.max(0.001, (now - last) / 1000));
  last = now;

  // Nearest ring within reach.
  let best: MetalFxInstance | null = null;
  let u = 0, uC = 0;
  if (cfg.enabled && SHARED && !Number.isNaN(px)) {
    let bestAbs = Number.POSITIVE_INFINITY;
    const reachA = Math.max(1, cfg.reach);
    const reachC = cfg.cursor && cursorSwapAllowed() ? Math.max(1, cfg.cursorDistance) : 0;
    const reach = Math.max(reachA, reachC);
    for (const inst of SHARED.instances) {
      // Paused instances still hold a painted ring — they can light the
      // pointer; only their glow tick is skipped further down.
      if (!inst.visible || !inst.canvas.isConnected) continue;
      const r = inst.canvas.getBoundingClientRect();
      if (r.width <= 0) continue;
      const o = inst.overscan;
      const k = r.width / (inst.cssWidth + 2 * o);
      const left = r.left + o * k, top = r.top + o * k;
      const rk = reach * k;
      if (px < left - rk || px > left + inst.cssWidth * k + rk || py < top - rk || py > top + inst.cssHeight * k + rk) continue;
      const lx = (px - left) / k, ly = (py - top) / k;
      const d = nearestOutlinePoint(lx, ly, inst.cssWidth, inst.cssHeight, inst.cornerRadius, inst.kind, _pt);
      const ad = Math.abs(d);
      if (ad <= reach && ad < bestAbs) {
        bestAbs = ad; best = inst;
        _near.d = d; _near.nx = _pt.x; _near.ny = _pt.y; _near.k = k; _near.left = left; _near.top = top;
      }
    }
    if (best) {
      if (bestAbs <= reachA) { const t = 1 - bestAbs / reachA; u = t * t * (3 - 2 * t); }
      if (bestAbs <= reachC) uC = Math.min(1, (1 - bestAbs / reachC) * 3);
      if (best.mask) {
        // Metal text: the light is the word itself, not its box edge. Point
        // the light at the box centre and keep the unmasked sheet around for
        // the mirror image — three thin glyphs mirror as almost nothing.
        _near.nx = best.cssWidth / 2; _near.ny = best.cssHeight / 2;
        best.wantRaw = true;
      }
    }
  }

  // Envelope on the proximity weight — no pops on enter/leave/jump.
  const a = 1 - Math.exp(-(dt * 1000) / (Math.max(1, cfg.fadeMs) / 3));
  uS += (u - uS) * a;
  uCS += (uC - uCS) * a;

  if (best && best !== near) {
    if (near) { near.cursorLight = null; tickInstanceGlow(near, now); }
    near = best;
  }
  if (!best && uS < 0.002 && uCS < 0.002) {
    uS = 0; uCS = 0;
    if (near) { near.cursorLight = null; tickInstanceGlow(near, now); near = null; }
    hideSpill();
    hideCursor();
    return;
  }
  if (!near) return;

  // C — hand the glow a light source and tick it at pointer rate.
  if (cfg.catchLight) {
    const cl = near.cursorLight ?? (near.cursorLight = { x: 0, y: 0, w: 0 });
    cl.x = _near.nx; cl.y = _near.ny; cl.w = uS;
  } else if (near.cursorLight) {
    near.cursorLight = null;
  }
  tickInstanceGlow(near, now);

  // A — the ring on the cursor.
  if (cfg.cursor && uCS > 0.002 && pointerIsMouse && !typing && !Number.isNaN(px) && cursorSwapAllowed() && ensureCursor() && claimCursor(px, py)) {
    drawCursor(near, cfg, uCS);
  } else {
    hideCursor();
  }

  // B — the glint under the pointer.
  if (cfg.spill) {
    const el = ensureSpill();
    const rgb = sampleShaderRGBAt(near, _near.nx, _near.ny, 2);
    const lum = sampleShaderLumAt(near, _near.nx, _near.ny, 3);
    const peak = Math.max(rgb.r, rgb.g, rgb.b) || 1;
    const hsv = rgbToHsv((rgb.r * 255) / peak, (rgb.g * 255) / peak, (rgb.b * 255) / peak);
    const [cr, cg, cb] = hsvToRgb(hsv[0], Math.min(1, hsv[1] * cfg.spillSaturation), 1);
    _sc.r += (cr - _sc.r) * 0.15; _sc.g += (cg - _sc.g) * 0.15; _sc.b += (cb - _sc.b) * 0.15;
    // Quantise so the gradient string (and its repaint) only changes on a
    // visible step.
    const qr = Math.round(_sc.r / 6) * 6, qg = Math.round(_sc.g / 6) * 6, qb = Math.round(_sc.b / 6) * 6;
    const bg = `radial-gradient(closest-side, rgba(${qr},${qg},${qb},1) 0%, rgba(${qr},${qg},${qb},0.35) 45%, rgba(${qr},${qg},${qb},0) 100%)`;
    if (bg !== spillBg) { spillBg = bg; el.style.background = bg; }

    const R = Math.max(1, cfg.spillRadius * _near.k);
    if (R !== spillSize) { spillSize = R; el.style.width = `${(2 * R).toFixed(1)}px`; el.style.height = `${(2 * R).toFixed(1)}px`; }
    if (cfg.spillBlur !== spillBlur) { spillBlur = cfg.spillBlur; el.style.filter = cfg.spillBlur > 0 ? `blur(${cfg.spillBlur}px)` : ''; }

    const rx = _near.left + _near.nx * _near.k, ry = _near.top + _near.ny * _near.k;
    const sx = lpx + (rx - lpx) * cfg.spillOffset, sy = lpy + (ry - lpy) * cfg.spillOffset;
    el.style.transform = `translate3d(${(sx - R).toFixed(2)}px,${(sy - R).toFixed(2)}px,0)`;

    const lf = Math.min(1, Math.max(0, lum / 0.3));
    const lumMix = 1 - cfg.spillLumGain + cfg.spillLumGain * lf;
    const insideMul = _near.d < 0 ? cfg.spillInside : 1;
    const op = Math.max(0, Math.min(1, cfg.spillStrength * uS * lumMix * insideMul));
    if (!spillShown) { el.style.display = ''; spillShown = true; }
    el.style.opacity = op.toFixed(3);
  } else {
    hideSpill();
  }

  raf = requestAnimationFrame(step);
}

/**
 * Pre-rendered glow sprites.
 *
 * The halo used to be four blurred SVG strokes re-rasterised through
 * `feGaussianBlur` on every move. Here the same strokes are rendered once,
 * in white, into small alpha bitmaps; the per-frame work is then a couple of
 * `drawImage` calls. Blur is a 3-pass box blur on the alpha channel (a close
 * gaussian approximation) so it doesn't depend on `ctx.filter` support.
 *
 * Sprites are cached by everything that shapes them — half-length, scale,
 * device pixel ratio and the GLOW markup values — and shared by every
 * instance with the same key.
 */
import { GLOW } from './config';

export interface Sprite {
  canvas: HTMLCanvasElement;
  /** Alpha per device pixel, row-major — the source for tinting. */
  alpha: Uint8ClampedArray;
  /** CSS-px size to draw it at. */
  w: number;
  h: number;
  /** CSS-px offset from the sprite's top-left to its anchor (stroke centre). */
  ax: number;
  ay: number;
}

const cache = new Map<string, Sprite>();

// ─── Blur ─────────────────────────────────────────────────────────────────

/** Box sizes for `n` passes approximating a gaussian of `sigma` (Kutskir). */
function boxesForGauss(sigma: number, n: number): number[] {
  const wIdeal = Math.sqrt((12 * sigma * sigma) / n + 1);
  let wl = Math.floor(wIdeal);
  if (wl % 2 === 0) wl--;
  const wu = wl + 2;
  const mIdeal = (12 * sigma * sigma - n * wl * wl - 4 * n * wl - 3 * n) / (-4 * wl - 4);
  const m = Math.round(mIdeal);
  const sizes: number[] = [];
  for (let i = 0; i < n; i++) sizes.push(i < m ? wl : wu);
  return sizes;
}

function boxBlurH(src: Float32Array, dst: Float32Array, w: number, h: number, r: number): void {
  const iarr = 1 / (r + r + 1);
  for (let y = 0; y < h; y++) {
    const row = y * w;
    let acc = 0;
    for (let x = -r; x <= r; x++) acc += src[row + Math.min(w - 1, Math.max(0, x))];
    for (let x = 0; x < w; x++) {
      dst[row + x] = acc * iarr;
      const out = row + Math.max(0, x - r), inn = row + Math.min(w - 1, x + r + 1);
      acc += src[inn] - src[out];
    }
  }
}

function boxBlurV(src: Float32Array, dst: Float32Array, w: number, h: number, r: number): void {
  const iarr = 1 / (r + r + 1);
  for (let x = 0; x < w; x++) {
    let acc = 0;
    for (let y = -r; y <= r; y++) acc += src[Math.min(h - 1, Math.max(0, y)) * w + x];
    for (let y = 0; y < h; y++) {
      dst[y * w + x] = acc * iarr;
      const out = Math.max(0, y - r) * w + x, inn = Math.min(h - 1, y + r + 1) * w + x;
      acc += src[inn] - src[out];
    }
  }
}

export function gaussBlur(a: Float32Array, w: number, h: number, sigma: number): Float32Array {
  if (sigma <= 0.05) return a;
  const tmp = new Float32Array(a.length);
  const cur = a;
  for (const box of boxesForGauss(sigma, 3)) {
    const r = (box - 1) / 2;
    boxBlurH(cur, tmp, w, h, r);
    boxBlurV(tmp, cur, w, h, r);
  }
  return cur;
}

// ─── Rasterising ──────────────────────────────────────────────────────────

interface Layer { stroke: number; blur: number; opacity: number }

/** Alpha of a horizontal round-capped line of `halfLen` at the given width,
 *  rendered through the 2D canvas so the AA matches what SVG produced. */
function strokeAlpha(halfLen: number, strokeW: number, w: number, h: number, dpr: number, ax: number, ay: number): Float32Array {
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  const g = c.getContext('2d', { willReadFrequently: true });
  const out = new Float32Array(w * h);
  if (!g) return out;
  g.scale(dpr, dpr);
  g.strokeStyle = '#fff';
  g.lineCap = 'round';
  g.lineJoin = 'round';
  g.lineWidth = strokeW;
  g.beginPath();
  g.moveTo(ax - halfLen, ay);
  g.lineTo(ax + halfLen, ay);
  g.stroke();
  const d = g.getImageData(0, 0, w, h).data;
  for (let i = 0, j = 3; i < out.length; i++, j += 4) out[i] = d[j] / 255;
  return out;
}

function compose(layers: Layer[], halfLen: number, s: number, dpr: number, fade: number): Sprite {
  let padMax = 0;
  for (const l of layers) padMax = Math.max(padMax, (l.stroke / 2 + 3 * l.blur) * s);
  const pad = Math.ceil(padMax) + 1;
  const cw = 2 * halfLen + 2 * pad, ch = 2 * pad;
  const w = Math.ceil(cw * dpr), h = Math.ceil(ch * dpr);
  const acc = new Float32Array(w * h);
  for (const l of layers) {
    let a = strokeAlpha(halfLen, l.stroke * s, w, h, dpr, pad, pad);
    a = gaussBlur(a, w, h, l.blur * s * dpr);
    const op = l.opacity;
    // White over white: only alpha composes.
    for (let i = 0; i < acc.length; i++) { const la = a[i] * op; acc[i] = acc[i] + la * (1 - acc[i]); }
  }
  if (fade > 0) {
    // SVG luminance mask: white to 0.30, #404040 (0.25) at 0.65, black at 1.
    const cx = pad * dpr, cy = pad * dpr, R = fade * s * dpr;
    for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
      const t = Math.hypot(x + 0.5 - cx, y + 0.5 - cy) / R;
      let m: number;
      if (t <= 0.3) m = 1;
      else if (t <= 0.65) m = 1 - ((t - 0.3) / 0.35) * 0.75;
      else if (t < 1) m = 0.25 * (1 - (t - 0.65) / 0.35);
      else m = 0;
      acc[y * w + x] *= m;
    }
  }
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  const g = c.getContext('2d');
  const alpha = new Uint8ClampedArray(w * h);
  for (let i = 0; i < acc.length; i++) alpha[i] = Math.round(Math.min(1, acc[i]) * 255);
  if (g) {
    const img = g.createImageData(w, h);
    const d = img.data;
    for (let i = 0, j = 0; i < acc.length; i++, j += 4) {
      d[j] = 255; d[j + 1] = 255; d[j + 2] = 255; d[j + 3] = alpha[i];
    }
    g.putImageData(img, 0, 0);
  }
  return { canvas: c, alpha, w: cw, h: ch, ax: pad, ay: pad };
}

function markupKey(): string {
  return [
    GLOW.haloStrokeXl, GLOW.haloStrokeLg, GLOW.haloStrokeMd, GLOW.haloStrokeSm,
    GLOW.haloBlurXl, GLOW.haloBlurLg, GLOW.haloBlurMd, GLOW.haloBlurSm,
    GLOW.haloOpXl, GLOW.haloOpLg, GLOW.haloOpMd, GLOW.haloOpSm,
    GLOW.extraStrokeOuter, GLOW.extraStrokeCore, GLOW.extraBlurOuter, GLOW.extraBlurCore,
    GLOW.extraFadeR, GLOW.extraOpOuter,
  ].join(',');
}

/** The wide halo: four blurred strokes stacked, at `halfLen` half-length. */
export function bakeHalo(halfLen: number, s: number, dpr: number): Sprite {
  const key = `h|${halfLen.toFixed(2)}|${s}|${dpr}|${markupKey()}`;
  let sp = cache.get(key);
  if (!sp) {
    sp = compose([
      { stroke: GLOW.haloStrokeXl, blur: GLOW.haloBlurXl, opacity: GLOW.haloOpXl },
      { stroke: GLOW.haloStrokeLg, blur: GLOW.haloBlurLg, opacity: GLOW.haloOpLg },
      { stroke: GLOW.haloStrokeMd, blur: GLOW.haloBlurMd, opacity: GLOW.haloOpMd },
      { stroke: GLOW.haloStrokeSm, blur: GLOW.haloBlurSm, opacity: GLOW.haloOpSm },
    ], halfLen, s, dpr, 0);
    cache.set(key, sp);
  }
  return sp;
}

/** The catch-light: two tight strokes with a radial fade at the ends. */
export function bakeExtra(halfLen: number, s: number, dpr: number): Sprite {
  const key = `e|${halfLen.toFixed(2)}|${s}|${dpr}|${markupKey()}`;
  let sp = cache.get(key);
  if (!sp) {
    sp = compose([
      { stroke: GLOW.extraStrokeOuter, blur: GLOW.extraBlurOuter, opacity: GLOW.extraOpOuter },
      { stroke: GLOW.extraStrokeCore, blur: GLOW.extraBlurCore, opacity: 1 },
    ], halfLen, s, dpr, GLOW.extraFadeR);
    cache.set(key, sp);
  }
  return sp;
}

/** A tinted copy of a white sprite. `holder` caches by tint so the re-tint
 *  only happens when the colour actually changes. Pixel-data based on
 *  purpose: no `source-in` compositing, which WebKit intermittently gets
 *  wrong on accelerated canvases (a solid rectangle instead of the shape). */
export interface Tinted { canvas: HTMLCanvasElement | null; img: ImageData | null; tint: number; src: Sprite | null }

export function tintSprite(src: Sprite, r: number, g: number, b: number, holder: Tinted): HTMLCanvasElement {
  const key = (r << 16) | (g << 8) | b;
  if (holder.canvas && holder.tint === key && holder.src === src) return holder.canvas;
  let c = holder.canvas;
  let img = holder.img;
  if (!c || !img || holder.src !== src) {
    c = document.createElement('canvas');
    c.width = src.canvas.width; c.height = src.canvas.height;
    img = c.getContext('2d')?.createImageData(c.width, c.height) ?? null;
  }
  const ctx = c.getContext('2d');
  if (ctx && img) {
    const d = img.data, a = src.alpha;
    for (let i = 0, j = 0; i < a.length; i++, j += 4) { d[j] = r; d[j + 1] = g; d[j + 2] = b; d[j + 3] = a[i]; }
    ctx.putImageData(img, 0, 0);
  }
  holder.canvas = c; holder.img = img; holder.tint = key; holder.src = src;
  return c;
}

/**
 * Pure geometry + SVG markup for the glow overlay.
 *
 * Perimeter math (rounded-rect / circle arc-length sampling), blob path
 * generation, SVG filter/mask construction, and HSV colour helpers.
 * No state — every function is a pure transform.
 */
import { PERIM_SAMPLES } from '../perfConfig';

import { GLOW } from './config';
import { outlinePathD, roundRectOutline } from '../renderer/outline';

export { PERIM_SAMPLES };

export interface GlowOptions {
  width: number;
  height: number;
  cornerRadius: number;
  kind: 'pill' | 'circle';
  /** Master multiplier for absolute SVG units (stroke widths, blur,
   *  fade-circle radius). 1 is the canonical 1× rendering. Set to 2 when
   *  the host element is rendered at a 2× layout (e.g. CSS zoom: 2) so
   *  the glow grows proportionally. */
  scale?: number;
  /**
   * Point mode (custom-mask instances). `samplePoints` are box-local CSS-px
   * positions inside the mask where luminance is sampled and the hotspot can
   * sit; `maskDataUrl` is the mask rendered white-on-transparent, used to clip
   * the glow to the glyphs instead of the ring band.
   */
  samplePoints?: Pt[];
  maskDataUrl?: string;
}
export interface Pt { x: number; y: number }
export interface PerimSample extends Pt { arc: number }

export function rrPerim(w: number, h: number, r: number): number {
  const rr = Math.max(0, Math.min(r, Math.min(w, h) / 2));
  return 2 * Math.max(0, w - 2 * rr) + 2 * Math.max(0, h - 2 * rr) + 2 * Math.PI * rr;
}

export function shapePerim(w: number, h: number, r: number, kind: 'pill' | 'circle'): number {
  if (kind === 'circle') return 2 * Math.PI * Math.max(0, Math.min(r, Math.min(w, h) / 2));
  return rrPerim(w, h, r);
}

export function sampleAtArc(s: number, w: number, h: number, r: number, inset: number, outward: number, kind: 'pill' | 'circle', out?: Pt): Pt {
  const o = out || { x: 0, y: 0 };
  const rr = Math.max(0, Math.min(r, Math.min(w, h) / 2));
  if (kind === 'circle') {
    const perim = 2 * Math.PI * rr;
    if (perim <= 0.0001) { o.x = w * 0.5; o.y = h * 0.5; return o; }
    s = ((s % perim) + perim) % perim;
    const theta = -Math.PI / 2 + (s / perim) * Math.PI * 2;
    const rad = Math.max(0, rr - inset + outward);
    o.x = w * 0.5 + rad * Math.cos(theta);
    o.y = h * 0.5 + rad * Math.sin(theta);
    return o;
  }
  const topLen = Math.max(0, w - 2 * rr), sideLen = Math.max(0, h - 2 * rr);
  const arcLen = (Math.PI * rr) / 2;
  const perim = 2 * (topLen + sideLen) + 4 * arcLen;
  s = ((s % perim) + perim) % perim;
  const rad = Math.max(0, rr - inset + outward);
  let d = s;
  if (d < topLen) { o.x = rr + d; o.y = inset - outward; return o; }
  d -= topLen;
  if (d < arcLen) {
    const theta = -Math.PI / 2 + (arcLen > 0 ? d / arcLen : 0) * (Math.PI / 2);
    o.x = (w - rr) + rad * Math.cos(theta); o.y = rr + rad * Math.sin(theta); return o;
  }
  d -= arcLen;
  if (d < sideLen) { o.x = w - inset + outward; o.y = rr + d; return o; }
  d -= sideLen;
  if (d < arcLen) {
    const theta = (arcLen > 0 ? d / arcLen : 0) * (Math.PI / 2);
    o.x = (w - rr) + rad * Math.cos(theta); o.y = (h - rr) + rad * Math.sin(theta); return o;
  }
  d -= arcLen;
  if (d < topLen) { o.x = w - rr - d; o.y = h - inset + outward; return o; }
  d -= topLen;
  if (d < arcLen) {
    const theta = Math.PI / 2 + (arcLen > 0 ? d / arcLen : 0) * (Math.PI / 2);
    o.x = rr + rad * Math.cos(theta); o.y = (h - rr) + rad * Math.sin(theta); return o;
  }
  d -= arcLen;
  if (d < sideLen) { o.x = inset - outward; o.y = h - rr - d; return o; }
  d -= sideLen;
  const theta = Math.PI + (arcLen > 0 ? d / arcLen : 0) * (Math.PI / 2);
  o.x = rr + rad * Math.cos(theta); o.y = rr + rad * Math.sin(theta);
  return o;
}

/**
 * Inverse of `sampleAtArc` at inset 0: the arc-length position on the outline
 * nearest a box-local point. Points off the outline project onto it.
 */
export function arcAtPoint(x: number, y: number, w: number, h: number, r: number, kind: 'pill' | 'circle'): number {
  const rr = Math.max(0, Math.min(r, Math.min(w, h) / 2));
  if (kind === 'circle') {
    const perim = 2 * Math.PI * rr;
    if (perim <= 0.0001) return 0;
    const theta = Math.atan2(y - h / 2, x - w / 2);
    const s = ((theta + Math.PI / 2) / (2 * Math.PI)) * perim;
    return ((s % perim) + perim) % perim;
  }
  const topLen = Math.max(0, w - 2 * rr), sideLen = Math.max(0, h - 2 * rr);
  const arcLen = (Math.PI * rr) / 2, Q = Math.PI / 2;
  const s1 = topLen, s2 = s1 + arcLen, s3 = s2 + sideLen, s4 = s3 + arcLen, s5 = s4 + topLen, s6 = s5 + arcLen, s7 = s6 + sideLen;
  const inX = x >= rr && x <= w - rr, inY = y >= rr && y <= h - rr;
  if (inX && inY) {
    const dl = x, dr = w - x, dt = y, db = h - y, m = Math.min(dl, dr, dt, db);
    if (m === dt) return x - rr;
    if (m === dr) return s2 + (y - rr);
    if (m === db) return s4 + (w - rr - x);
    return s6 + (h - rr - y);
  }
  if (inX) return y < h / 2 ? x - rr : s4 + (w - rr - x);
  if (inY) return x > w / 2 ? s2 + (y - rr) : s6 + (h - rr - y);
  if (x > w / 2 && y < h / 2) { const t = Math.atan2(y - rr, x - (w - rr)); return s1 + ((t + Q) / Q) * arcLen; }
  if (x > w / 2) { const t = Math.atan2(y - (h - rr), x - (w - rr)); return s3 + (t / Q) * arcLen; }
  if (y > h / 2) { const t = Math.atan2(y - (h - rr), x - rr); return s5 + ((t - Q) / Q) * arcLen; }
  const t = Math.atan2(y - rr, x - rr);
  return s7 + ((t + Math.PI) / Q) * arcLen;
}

export function buildStaticBlobPath(halfLen: number, segments: number): string {
  const step = (halfLen * 2) / segments;
  let d = '';
  for (let i = 0; i <= segments; i++) {
    const x = -halfLen + i * step;
    d += (i === 0 ? 'M ' : 'L ') + x.toFixed(3) + ' 0 ';
  }
  return d;
}

const _ta: Pt = { x: 0, y: 0 };
const _tb: Pt = { x: 0, y: 0 };

export function tangentAngleAtArc(s: number, w: number, h: number, r: number, inset: number, kind: 'pill' | 'circle'): number {
  const eps = 0.1;
  sampleAtArc(s - eps, w, h, r, inset, 0, kind, _ta);
  sampleAtArc(s + eps, w, h, r, inset, 0, kind, _tb);
  return Math.atan2(_tb.y - _ta.y, _tb.x - _ta.x);
}

export function smoothstep(a: number, b: number, x: number): number {
  if (a === b) return x < a ? 0 : 1;
  const t = Math.max(0, Math.min(1, (x - a) / (b - a)));
  return t * t * (3 - 2 * t);
}

export function buildPerimTable(opts: GlowOptions): PerimSample[] {
  if (opts.samplePoints && opts.samplePoints.length > 0) {
    // Point mode: `arc` is just the index — relocation logic works on
    // indices, and positioning bypasses arc math entirely.
    return opts.samplePoints.map((p, i) => ({ x: p.x, y: p.y, arc: i }));
  }
  const perim = shapePerim(opts.width, opts.height, opts.cornerRadius, opts.kind);
  const insetS = GLOW.inset * (opts.scale ?? 1);
  const table: PerimSample[] = [];
  for (let i = 0; i < PERIM_SAMPLES; i++) {
    const arc = (i / PERIM_SAMPLES) * perim;
    const pt = sampleAtArc(arc, opts.width, opts.height, opts.cornerRadius, insetS, 0, opts.kind);
    table.push({ x: pt.x, y: pt.y, arc });
  }
  return table;
}

export function buildSvgMarkup(opts: GlowOptions, p: string): string {
  const { width: W, height: H, cornerRadius: R } = opts;
  const s = opts.scale ?? 1;
  const ringInset = opts.kind === 'circle' ? 2 : 1;
  const innerR = Math.max(0, R - ringInset);
  // Filter region grows with scale so blurred strokes don't get clipped at
  // bigger sizes. The 200/540/440 baseline matches the canonical 1× pill.
  const fX = (-200 * s).toFixed(0), fY = fX;
  const fW = (540 * s).toFixed(0), fH = (440 * s).toFixed(0);
  const fRect = `x="${fX}" y="${fY}" width="${fW}" height="${fH}"`;
  const fr = `${fRect} filterUnits="userSpaceOnUse" color-interpolation-filters="sRGB"`;
  // Stroke widths and blur stdDeviations are absolute SVG units; multiply
  // by `s` so they remain proportional when viewBox grows with the host.
  const sw = (n: number) => (n * s).toFixed(3);
  const sd = (n: number) => (n * s).toFixed(3);
  return [
    '<defs>',
    `<filter id="${p}_bXl" ${fr}><feGaussianBlur stdDeviation="${sd(GLOW.haloBlurXl)}"/></filter>`,
    `<filter id="${p}_bLg" ${fr}><feGaussianBlur stdDeviation="${sd(GLOW.haloBlurLg)}"/></filter>`,
    `<filter id="${p}_bMd" ${fr}><feGaussianBlur stdDeviation="${sd(GLOW.haloBlurMd)}"/></filter>`,
    `<filter id="${p}_bSm" ${fr}><feGaussianBlur stdDeviation="${sd(GLOW.haloBlurSm)}"/></filter>`,
    `<filter id="${p}_ebO" ${fr}><feGaussianBlur stdDeviation="${sd(GLOW.extraBlurOuter)}"/></filter>`,
    `<filter id="${p}_ebC" ${fr}><feGaussianBlur stdDeviation="${sd(GLOW.extraBlurCore)}"/></filter>`,
    `<radialGradient id="${p}_fg" cx="0.5" cy="0.5" r="0.5"><stop offset="0" stop-color="white"/><stop offset="0.30" stop-color="white"/><stop offset="0.65" stop-color="#404040"/><stop offset="1" stop-color="black"/></radialGradient>`,
    `<mask id="${p}_fm" maskUnits="userSpaceOnUse" ${fRect}><rect ${fRect} fill="black"/><circle id="${p}_fc" cx="0" cy="0" r="${(GLOW.extraFadeR * s).toFixed(3)}" fill="url(#${p}_fg)"/></mask>`,
    opts.maskDataUrl
      // Point mode clips hard to the glyphs (black surround); the halo's
      // blurred energy outside the strokes is discarded, so `pointGain`
      // compensates inside them.
      ? `<mask id="${p}_rm" maskUnits="userSpaceOnUse" ${fRect}><rect ${fRect} fill="black"/><image href="${opts.maskDataUrl}" x="0" y="0" width="${W}" height="${H}" preserveAspectRatio="none"/></mask>`
      : `<mask id="${p}_rm" maskUnits="userSpaceOnUse" ${fRect}><rect ${fRect} fill="#808080"/><path id="${p}_rmO" d="${outlinePathD(roundRectOutline(0, 0, W, H, R, null))}" fill="white"/><path id="${p}_rmI" d="${outlinePathD(roundRectOutline(ringInset, ringInset, W - ringInset * 2, H - ringInset * 2, innerR, null))}" fill="black"/></mask>`,
    '</defs>',
    // Safari clips mask to the masked element's bbox; our horizontal strokes
    // have zero height, so the mask becomes a sliver. These spacer rects
    // inflate the bbox to the full filter region.
    `<g id="${p}_h" mask="url(#${p}_rm)" opacity="0">`,
    `<rect ${fRect} fill="none" pointer-events="none"/>`,
    `<g id="${p}_hI" stroke="white">`,
    `<path id="${p}_pXl" stroke-width="${sw(GLOW.haloStrokeXl)}" stroke-linecap="round" stroke-linejoin="round" fill="none" opacity="${GLOW.haloOpXl}" filter="url(#${p}_bXl)"/>`,
    `<path id="${p}_pLg" stroke-width="${sw(GLOW.haloStrokeLg)}" stroke-linecap="round" stroke-linejoin="round" fill="none" opacity="${GLOW.haloOpLg}" filter="url(#${p}_bLg)"/>`,
    `<path id="${p}_pMd" stroke-width="${sw(GLOW.haloStrokeMd)}" stroke-linecap="round" stroke-linejoin="round" fill="none" opacity="${GLOW.haloOpMd}" filter="url(#${p}_bMd)"/>`,
    `<path id="${p}_pSm" stroke-width="${sw(GLOW.haloStrokeSm)}" stroke-linecap="round" stroke-linejoin="round" fill="none" opacity="${GLOW.haloOpSm}" filter="url(#${p}_bSm)"/>`,
    '</g></g>',
    `<g id="${p}_e" mask="url(#${p}_rm)" opacity="0">`,
    `<rect ${fRect} fill="none" pointer-events="none"/>`,
    `<g mask="url(#${p}_fm)">`,
    `<g id="${p}_eI" stroke="white">`,
    `<path id="${p}_eO" stroke-width="${sw(GLOW.extraStrokeOuter)}" stroke-linecap="round" stroke-linejoin="round" fill="none" opacity="${GLOW.extraOpOuter}" filter="url(#${p}_ebO)"/>`,
    `<path id="${p}_eC" stroke-width="${sw(GLOW.extraStrokeCore)}" stroke-linecap="round" stroke-linejoin="round" fill="none" opacity="1.0" filter="url(#${p}_ebC)"/>`,
    '</g></g></g>',
  ].join('');
}

/**
 * Inner-shadow rim on the metal ring — the same treatment the "Pro" text
 * carries (Figma: white 90 %, offset 0/1, blur 0.5): a hairline of light
 * along the top inside edge of the band.
 *
 * Computed, not CSS: band alpha minus the same alpha shifted down by the
 * offset leaves exactly the top rim (outer edge on the ring's upper half,
 * inner edge on its lower half — what a light from above does to a torus).
 * Blurred, tinted, drawn to a small overlay canvas above the metal. Redrawn
 * only when the outline changes (deform), so it's free at rest.
 */
import type { DeformFn } from './renderer/core';
import { gaussBlur } from './glow/bake';
import { type OutlineBuf, createOutlineBuf, roundRectOutline } from './renderer/outline';

export interface RimOptions {
  /** Shadow offset, CSS px (positive = light from above). */
  offsetY: number;
  /** Blur, CSS px. */
  blur: number;
  /** Peak opacity of the rim (0..1). */
  alpha: number;
  /** Rim colour, `#rrggbb`. */
  color: string;
}

export const RIM_DEFAULTS: Readonly<RimOptions> = Object.freeze({ offsetY: 1, blur: 0.5, alpha: 0.9, color: '#ffffff' });

export interface RimHandles {
  canvas: HTMLCanvasElement;
  ctx: CanvasRenderingContext2D;
  scratch: HTMLCanvasElement;
  sctx: CanvasRenderingContext2D;
  width: number; height: number; cornerRadius: number; kind: 'pill' | 'circle'; ring: number;
  margin: number; dpr: number;
  opts: RimOptions;
  mO: OutlineBuf; mI: OutlineBuf;
  /** Checksum of the outline last drawn; unchanged composites are skipped. */
  sum: number;
}

export function injectRim(
  container: HTMLElement,
  dims: { width: number; height: number; cornerRadius: number; kind: 'pill' | 'circle'; ring: number },
  opts: RimOptions
): RimHandles | null {
  const dpr = Math.min(3, typeof window !== 'undefined' ? window.devicePixelRatio || 1 : 1);
  const margin = Math.ceil(3 * opts.blur + Math.abs(opts.offsetY) + 1);
  const cw = dims.width + 2 * margin, ch = dims.height + 2 * margin;
  const canvas = document.createElement('canvas');
  canvas.className = 'metal-fx-rim-canvas';
  canvas.setAttribute('aria-hidden', 'true');
  canvas.width = Math.ceil(cw * dpr); canvas.height = Math.ceil(ch * dpr);
  canvas.style.cssText = `position:absolute;left:${-margin}px;top:${-margin}px;width:${cw}px;height:${ch}px;pointer-events:none`;
  const ctx = canvas.getContext('2d');
  const scratch = document.createElement('canvas');
  scratch.width = canvas.width; scratch.height = canvas.height;
  const sctx = scratch.getContext('2d', { willReadFrequently: true });
  if (!ctx || !sctx) return null;
  container.appendChild(canvas);
  const h: RimHandles = {
    canvas, ctx, scratch, sctx,
    width: dims.width, height: dims.height, cornerRadius: dims.cornerRadius, kind: dims.kind, ring: dims.ring,
    margin, dpr, opts, mO: createOutlineBuf(), mI: createOutlineBuf(), sum: Number.NaN,
  };
  updateRim(h, null, true);
  return h;
}

function trace(g: CanvasRenderingContext2D, buf: OutlineBuf, off: number): void {
  const xy = buf.xy;
  for (let i = 0; i < buf.n; i++) {
    const x = xy[i * 2] + off, y = xy[i * 2 + 1] + off;
    if (i === 0) g.moveTo(x, y); else g.lineTo(x, y);
  }
  g.closePath();
}

/** Redraw if the (deformed) outline changed. Cheap when it hasn't. */
export function updateRim(h: RimHandles, deform: DeformFn | null, force = false): void {
  const { width: W, height: H, cornerRadius: R, ring, margin: m, dpr } = h;
  roundRectOutline(0, 0, W, H, R, deform, h.mO);
  roundRectOutline(ring, ring, W - 2 * ring, H - 2 * ring, Math.max(0, R - ring), deform, h.mI);
  let sum = 0;
  const xy = h.mO.xy;
  for (let i = 0; i < h.mO.n; i += 4) sum += xy[i * 2] * 1.37 + xy[i * 2 + 1];
  if (!force && sum === h.sum) return;
  h.sum = sum;

  const { sctx: g, scratch: sc, ctx, canvas: cv, opts } = h;
  const w = sc.width, hh = sc.height;
  g.setTransform(1, 0, 0, 1, 0, 0);
  g.clearRect(0, 0, w, hh);
  g.scale(dpr, dpr);
  g.fillStyle = '#fff';
  g.beginPath();
  trace(g, h.mO, m);
  trace(g, h.mI, m);
  g.fill('evenodd');

  const d = g.getImageData(0, 0, w, hh).data;
  const n = w * hh;
  const a = new Float32Array(n);
  for (let i = 0, j = 3; i < n; i++, j += 4) a[i] = d[j] / 255;
  const shift = Math.round(opts.offsetY * dpr) * w;
  // Coverage the shifted band doesn't cover. A difference, not a product:
  // on anti-aliased edges both values are partial and a product lit every
  // edge instead of only the top one.
  const rim = new Float32Array(n);
  if (shift >= 0) {
    for (let i = 0; i < n; i++) rim[i] = Math.max(0, a[i] - (i >= shift ? a[i - shift] : 0));
  } else {
    for (let i = 0; i < n; i++) rim[i] = Math.max(0, a[i] - (i - shift < n ? a[i - shift] : 0));
  }
  const blurred = gaussBlur(rim, w, hh, opts.blur * dpr);

  const cr = parseInt(opts.color.slice(1, 3), 16), cg = parseInt(opts.color.slice(3, 5), 16), cb = parseInt(opts.color.slice(5, 7), 16);
  const img = ctx.createImageData(w, hh);
  const o = img.data;
  for (let i = 0, j = 0; i < n; i++, j += 4) {
    o[j] = cr; o[j + 1] = cg; o[j + 2] = cb;
    // Inner shadow: clipped to the band so the blur never leaks outside it.
    o[j + 3] = Math.round(Math.min(1, blurred[i] * a[i] * opts.alpha) * 255);
  }
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.putImageData(img, 0, 0);
  void cv;
}

export function removeRim(h: RimHandles | null): void {
  if (h) h.canvas.remove();
}

/** Proximity reflection — public API and per-frame paint loop. */
import type { MetalFxInstance } from '../renderer/core';
import {
  ATTACH_RANGE_PX,
  BASE_ALPHA,
  BOOST_ALPHA,
  BORDER_HILITE_ALPHA,
  BORDER_HILITE_PX,
  FILL_CIRCLE_ATTENUATION,
  FILL_EXTRA_ALPHA,
  FILL_OPACITY_MUL,
  GLOBAL_ATTENUATION,
  GRAD_FAR,
  GRAD_MID,
  GRAD_NEAR,
  OVERLAP_MIN_PX,
  INTENSITY_MULT,
  MAX_ALPHA_STACK,
  RANGE_PX,
  REF_DRAW_CSS_W,
  REFLECTION_BLOCKED_TAGS,
  STROKE_CSS_PX,
  STROKE_EXTRA_ALPHA,
  type ReflectionTarget,
} from './constants';
import {
  type BoxRect,
  type DrawDst,
  drawBorderHighlight,
  isHorizontalNeighbour,
  isVerticalNeighbour,
  maskedFillPasses,
  maskedStrokePasses,
  shortestRectDistance,
} from './geometry';
import { attachObservers, detachObservers, readCornerRadius, readHairlineSpec } from './observers';

export type { ReflectionTarget } from './constants';

const targets: Set<ReflectionTarget> = new Set();

// ─── Cursor occluder ──────────────────────────────────────────────────────
// The reflection is light leaving the anchor and landing on the target. A
// pointer sitting in the gap between them blocks some of that light, so we
// cut a soft shadow band out of the painted reflection at the pointer's
// position across the layout axis. The band widens with distance from the
// target (penumbra from an extended source) and is only applied while the
// pointer is actually inside the gap.

export interface ReflectionOccluderConfig {
  enabled: boolean;
  /** Occluder radius, CSS px — how "big" the cursor is as a light blocker. */
  radius: number;
  /** Peak shadow depth (0..1) with the pointer right at the target's edge. */
  strength: number;
  /** Penumbra growth: band half-height multiplier at the anchor's edge. */
  penumbra: number;
  /** How much depth is lost as the pointer moves from target edge (0) to
   *  anchor edge (1). 0 = same shadow everywhere in the gap. */
  falloff: number;
  /** Fade-in distance at the gap's ends, as a multiple of `radius`. */
  edgeFade: number;
  /** Band profile. 1 = smooth triangle, 0 = hard-edged plateau. */
  softness: number;
  /** Repaint throttle while the pointer moves, ms. */
  repaintMs: number;
}

export const REFLECTION_OCCLUDER_DEFAULTS: Readonly<ReflectionOccluderConfig> = Object.freeze({
  enabled: true,
  radius: 11.5,
  strength: 0.57,
  penumbra: 0.55,
  falloff: 0.21,
  edgeFade: 0.7,
  softness: 0.24,
  repaintMs: 36,
});

export const REFLECTION_OCCLUDER: ReflectionOccluderConfig = { ...REFLECTION_OCCLUDER_DEFAULTS };

export function setReflectionOccluderConfig(patch: Partial<ReflectionOccluderConfig>): void {
  Object.assign(REFLECTION_OCCLUDER, patch);
  scheduleOccluderRepaint();
}

export function resetReflectionOccluderConfig(): void {
  setReflectionOccluderConfig({ ...REFLECTION_OCCLUDER_DEFAULTS });
}

let occluder: { x: number; y: number } | null = null;
let occluderRaf = 0;
let occluderLastMs = 0;
let pointerTracked = false;

function scheduleOccluderRepaint(): void {
  if (occluderRaf !== 0 || typeof requestAnimationFrame === 'undefined') return;
  occluderRaf = requestAnimationFrame((now) => {
    occluderRaf = 0;
    // 30 fps is plenty for a shadow that follows a hand.
    if (now - occluderLastMs < REFLECTION_OCCLUDER.repaintMs) { scheduleOccluderRepaint(); return; }
    occluderLastMs = now;
    paintReflections();
  });
}

// Repaint only while the pointer can actually cast a shadow — inside the
// region spanning some anchor and its target (expanded by the occluder
// radius) — plus one more repaint on the way out to clear it. Without this
// every mouse move anywhere on the page re-rasterised every reflection.
let occluderWasNear = false;
function pointerNearAnyGap(x: number, y: number): boolean {
  const r = REFLECTION_OCCLUDER.radius;
  for (const t of targets) {
    const a = t.anchorEl.getBoundingClientRect();
    const b = t.el.getBoundingClientRect();
    const l = Math.min(a.left, b.left) - r, rt = Math.max(a.right, b.right) + r;
    const tp = Math.min(a.top, b.top) - r, bt = Math.max(a.bottom, b.bottom) + r;
    if (x >= l && x <= rt && y >= tp && y <= bt) return true;
  }
  return false;
}
function onOccluderMove(e: PointerEvent): void {
  occluder = { x: e.clientX, y: e.clientY };
  if (!REFLECTION_OCCLUDER.enabled) return;
  const near = pointerNearAnyGap(e.clientX, e.clientY);
  if (near || occluderWasNear) scheduleOccluderRepaint();
  occluderWasNear = near;
}
function onOccluderLeave(): void {
  occluder = null;
  if (occluderWasNear) scheduleOccluderRepaint();
  occluderWasNear = false;
}

function ensurePointerTracking(on: boolean): void {
  if (typeof document === 'undefined' || on === pointerTracked) return;
  pointerTracked = on;
  if (on) {
    document.addEventListener('pointermove', onOccluderMove, { passive: true });
    document.addEventListener('pointerleave', onOccluderLeave);
    window.addEventListener('blur', onOccluderLeave);
  } else {
    document.removeEventListener('pointermove', onOccluderMove);
    document.removeEventListener('pointerleave', onOccluderLeave);
    window.removeEventListener('blur', onOccluderLeave);
    occluder = null;
  }
}

/**
 * Cut the pointer's shadow out of a freshly painted reflection.
 * `horiz` — layout axis; light travels along x when true.
 */
function applyOccluderShadow(
  ctx: CanvasRenderingContext2D,
  strokeCtx: CanvasRenderingContext2D,
  aRect: DOMRect,
  tRect: DOMRect,
  horiz: boolean,
  tw: number,
  th: number,
  overscanCssPx: number,
  dpr: number
): void {
  if (!occluder) return;
  const cfg = REFLECTION_OCCLUDER;
  if (!cfg.enabled || cfg.strength <= 0) return;
  const r = cfg.radius;

  // Gap along the layout axis between the two facing edges, and the overlap
  // band across it. Pointer must be inside (expanded by r) for any effect.
  let gapStart: number, gapEnd: number, along: number, across: number, bandLo: number, bandHi: number;
  if (horiz) {
    const anchorRight = aRect.left >= tRect.right;
    gapStart = anchorRight ? tRect.right : aRect.right;   // target-side edge
    gapEnd = anchorRight ? aRect.left : tRect.left;       // anchor-side edge
    along = occluder.x; across = occluder.y;
    bandLo = Math.max(aRect.top, tRect.top); bandHi = Math.min(aRect.bottom, tRect.bottom);
  } else {
    const anchorBelow = aRect.top >= tRect.bottom;
    gapStart = anchorBelow ? tRect.bottom : aRect.bottom;
    gapEnd = anchorBelow ? aRect.top : tRect.top;
    along = occluder.y; across = occluder.x;
    bandLo = Math.max(aRect.left, tRect.left); bandHi = Math.min(aRect.right, tRect.right);
  }
  const lo = Math.min(gapStart, gapEnd), hi = Math.max(gapStart, gapEnd);
  const gapW = Math.max(1, hi - lo);
  if (along < lo - r || along > hi + r) return;
  if (across < bandLo - r || across > bandHi + r) return;

  // 0 at the target's edge, 1 at the anchor's edge.
  const t = Math.max(0, Math.min(1, Math.abs(along - gapStart) / gapW));
  // Fade at the region's edges on both axes so entering/leaving from any
  // side eases in instead of popping — coming at the gap from above or
  // below used to land the full band in one frame.
  const fadePx = Math.max(0.5, r * cfg.edgeFade);
  const endFade = Math.min(1, Math.min(along - (lo - r), (hi + r) - along) / fadePx);
  const sideFade = Math.min(1, Math.min(across - (bandLo - r), (bandHi + r) - across) / fadePx);
  const depth = cfg.strength * (1 - cfg.falloff * t) * endFade * sideFade;
  if (depth <= 0.001) return;

  const halfBand = r * dpr * (1 + cfg.penumbra * t);
  // Position across the target, in the target canvas' device space.
  const c = horiz
    ? (across - tRect.top + overscanCssPx) * dpr
    : (across - tRect.left + overscanCssPx) * dpr;
  // softness 1 → triangle; 0 → flat plateau across the whole band.
  const core = Math.max(0, Math.min(0.5, (1 - cfg.softness) * 0.5));
  const ramp = Math.max(1e-3, 0.5 - core);

  // Cut the band out in pixel data. Not `destination-out`: WebKit
  // intermittently misapplies composite ops on accelerated canvases and
  // paints the band's rectangle instead — a flash at the band's edges.
  const span = horiz ? th : tw;
  const p0 = Math.max(0, Math.floor(c - halfBand)), p1 = Math.min(span, Math.ceil(c + halfBand));
  if (p1 <= p0) return;
  const factor = new Float32Array(p1 - p0);
  for (let i = p0; i < p1; i++) {
    const p = (i + 0.5 - (c - halfBand)) / (2 * halfBand);
    const a = p < ramp ? p / ramp : p > 1 - ramp ? (1 - p) / ramp : 1;
    factor[i - p0] = 1 - depth * Math.max(0, Math.min(1, a));
  }
  for (const c2d of [ctx, strokeCtx]) {
    const x = horiz ? 0 : p0, y = horiz ? p0 : 0;
    const w = horiz ? tw : p1 - p0, h = horiz ? p1 - p0 : th;
    const img = c2d.getImageData(x, y, w, h);
    const d = img.data;
    if (horiz) {
      for (let row = 0; row < h; row++) {
        const f = factor[row];
        if (f >= 0.999) continue;
        for (let j = row * w * 4 + 3, e = (row + 1) * w * 4; j < e; j += 4) d[j] = d[j] * f;
      }
    } else {
      for (let row = 0; row < h; row++) {
        for (let col = 0; col < w; col++) {
          const f = factor[col];
          if (f >= 0.999) continue;
          const j = (row * w + col) * 4 + 3;
          d[j] = d[j] * f;
        }
      }
    }
    c2d.putImageData(img, x, y);
  }
}

// Scratch pair for multi-edge (contained) targets. Each masked pass ends with
// a `destination-in` gradient over the whole ring clip, which would erase the
// previous edge's ink — so every edge after the first paints here and is
// composited back with `lighter`.
let scratchFill: HTMLCanvasElement | null = null;
let scratchStroke: HTMLCanvasElement | null = null;
let scratchFillCtx: CanvasRenderingContext2D | null = null;
let scratchStrokeCtx: CanvasRenderingContext2D | null = null;
function ensureScratch(w: number, h: number): boolean {
  if (!scratchFill) {
    scratchFill = document.createElement('canvas');
    scratchStroke = document.createElement('canvas');
    scratchFillCtx = scratchFill.getContext('2d', { alpha: true });
    scratchStrokeCtx = scratchStroke.getContext('2d', { alpha: true });
  }
  if (!scratchFillCtx || !scratchStrokeCtx || !scratchFill || !scratchStroke) return false;
  if (scratchFill.width !== w) { scratchFill.width = w; scratchStroke.width = w; }
  if (scratchFill.height !== h) { scratchFill.height = h; scratchStroke.height = h; }
  scratchFillCtx.setTransform(1, 0, 0, 1, 0, 0);
  scratchStrokeCtx.setTransform(1, 0, 0, 1, 0, 0);
  scratchFillCtx.globalCompositeOperation = 'source-over';
  scratchStrokeCtx.globalCompositeOperation = 'source-over';
  scratchFillCtx.clearRect(0, 0, w, h);
  scratchStrokeCtx.clearRect(0, 0, w, h);
  return true;
}

export function addReflectionTarget(
  el: HTMLElement,
  anchor: MetalFxInstance,
  anchorEl: HTMLElement,
  strength = 1
): ReflectionTarget | null {
  if (typeof document === 'undefined') return null;
  if (REFLECTION_BLOCKED_TAGS.has(el.tagName)) return null;
  for (const existing of targets) {
    if (existing.el === el) { existing.strength = strength; return existing; }
  }

  const wrap = document.createElement('div');
  wrap.setAttribute('data-metal-fx-reflection', '');
  wrap.setAttribute('aria-hidden', 'true');

  const canvas = document.createElement('canvas');
  canvas.className = 'metal-fx-reflection-canvas';
  const ctx = canvas.getContext('2d', { alpha: true, willReadFrequently: true });
  if (!ctx) return null;

  const strokeCanvas = document.createElement('canvas');
  strokeCanvas.className = 'metal-fx-reflection-stroke-canvas';
  const strokeCtx = strokeCanvas.getContext('2d', { alpha: true, willReadFrequently: true });
  if (!strokeCtx) return null;

  wrap.appendChild(canvas);
  wrap.appendChild(strokeCanvas);

  const cs = getComputedStyle(el);
  let appliedPositionRelative = false;
  if (cs.position === 'static') {
    el.style.position = 'relative';
    appliedPositionRelative = true;
  }
  let appliedIsolation = false;
  if (cs.isolation !== 'isolate') {
    el.style.isolation = 'isolate';
    appliedIsolation = true;
  }
  el.setAttribute('data-metal-fx-reflect-host', '');
  el.insertBefore(wrap, el.firstChild);

  const initialSpec = readHairlineSpec(el);
  const target: ReflectionTarget = {
    el,
    anchor,
    anchorEl,
    strength,
    wrap,
    canvas,
    ctx,
    strokeCanvas,
    strokeCtx,
    cornerRadius: readCornerRadius(el),
    hairlineWidth: initialSpec.width,
    hairlineOuterCssPx: initialSpec.outerCssPx,
    appliedPositionRelative,
    appliedIsolation,
    resizeObserver: null,
    mutationObserver: null,
  };
  attachObservers(target);
  targets.add(target);
  ensurePointerTracking(true);
  return target;
}

export function removeReflectionTarget(el: HTMLElement): void {
  for (const target of targets) {
    if (target.el === el) {
      detachObservers(target);
      target.canvas.width = 0;
      target.canvas.height = 0;
      target.strokeCanvas.width = 0;
      target.strokeCanvas.height = 0;
      if (target.wrap.parentNode === target.el) {
        target.el.removeChild(target.wrap);
      }
      target.el.removeAttribute('data-metal-fx-reflect-host');
      if (target.appliedPositionRelative) target.el.style.position = '';
      if (target.appliedIsolation) target.el.style.isolation = '';
      targets.delete(target);
      if (targets.size === 0) ensurePointerTracking(false);
      return;
    }
  }
}

/** Bounding box of pixels with alpha > 8 inside a sub-rect, device px. */
function alphaBBox(
  canvas: HTMLCanvasElement, x0: number, y0: number, w: number, h: number
): { x: number; y: number; w: number; h: number } | null {
  if (w < 1 || h < 1) return null;
  const g = canvas.getContext('2d');
  if (!g) return null;
  const d = g.getImageData(x0, y0, w, h).data;
  let minX = w, minY = h, maxX = -1, maxY = -1;
  for (let y = 0; y < h; y++) {
    const row = y * w;
    for (let x = 0; x < w; x++) {
      if (d[(row + x) * 4 + 3] > 8) {
        if (x < minX) minX = x; if (x > maxX) maxX = x;
        if (y < minY) minY = y; if (y > maxY) maxY = y;
      }
    }
  }
  if (maxX < 0) return null;
  return { x: x0 + minX, y: y0 + minY, w: maxX - minX + 1, h: maxY - minY + 1 };
}

export function paintReflections(): void {
  if (targets.size === 0) return;
  const dpr = typeof window !== 'undefined' ? window.devicePixelRatio || 1 : 1;

  const anchorRects = new Map<HTMLElement, DOMRect>();

  for (const t of targets) {
    const tRect = t.el.getBoundingClientRect();
    let aRect = anchorRects.get(t.anchorEl);
    if (!aRect) {
      aRect = t.anchorEl.getBoundingClientRect();
      anchorRects.set(t.anchorEl, aRect);
    }
    if (tRect.width < 1 || tRect.height < 1) continue;
    if (aRect.width < 1 || aRect.height < 1) continue;
    // Glyph targets (text masked to its letterforms, see `data-metal-fx-text`)
    // are lit differently from a chip: no rim stroke or border highlight —
    // those are a white hairline along a box edge, which on text reads as a
    // flat light on the last letter — just the mirrored metal itself, at its
    // natural size so its banding stays legible, fading over a longer run so
    // more than one letter catches it.
    const glyph = t.el.hasAttribute('data-metal-fx-text');
    if (glyph && !t.glyphStyled) {
      // The chip blur (4 px) exists to melt the ring into a soft rim glow. On
      // letters it erases exactly the detail the mirror should show — the
      // stripes and dispersion fringes — so keep it to anti-aliasing width.
      t.canvas.style.filter = 'blur(0.4px) saturate(1.35) brightness(1.2)';
      t.glyphStyled = true;
    }

    if (
      !isHorizontalNeighbour(aRect, tRect, OVERLAP_MIN_PX, ATTACH_RANGE_PX) &&
      !isVerticalNeighbour(aRect, tRect, OVERLAP_MIN_PX, ATTACH_RANGE_PX)
    ) {
      if (t.canvas.width !== 1) { t.canvas.width = 1; t.canvas.height = 1; }
      if (t.strokeCanvas.width !== 1) { t.strokeCanvas.width = 1; t.strokeCanvas.height = 1; }
      continue;
    }

    // Glyph target on a masked anchor: mirror the metal *sheet*, not the
    // three thin letters cut from it. A mirror facing the "Pro" glyphs shows
    // the material's stripes across its whole face; the masked canvas would
    // give mostly transparency with a few slivers.
    const useRaw = glyph && !!t.anchor.mask;
    if (useRaw && !t.anchor.wantRaw) t.anchor.wantRaw = true;
    if (!t.anchor.wantRing) t.anchor.wantRing = true;
    // While bending, mirror the ring-only snapshot, not the canvas that also
    // carries the host's bent fill and rims.
    const bending = !!t.anchor.deform && !!t.anchor.ringCanvas;
    const anchorCanvas = (useRaw && t.anchor.rawCanvas) ? t.anchor.rawCanvas : bending ? t.anchor.ringCanvas! : t.anchor.canvas;
    // Sample only the anchor's CSS box. While a vector bend is active the
    // canvas carries an `overscan` margin on every side; reading it whole
    // would shrink the ring to the middle of the slice and miss the band.
    const ovs = Math.round(t.anchor.overscan * dpr);
    let ssx = ovs, ssy = ovs;
    let sw = (anchorCanvas.width | 0) - 2 * ovs;
    let sh = (anchorCanvas.height | 0) - 2 * ovs;
    // Custom-mask anchors (metal text): the metal is wherever the mask
    // painted, not at the box edge. Crop the source to its alpha bounding
    // box so the glyphs' edge — not the padding — lands on the target.
    if (t.anchor.mask && !useRaw) {
      const bb = alphaBBox(anchorCanvas, ssx, ssy, sw, sh);
      if (bb) { ssx = bb.x; ssy = bb.y; sw = bb.w; sh = bb.h; }
    }
    if (sw < 4 || sh < 4) continue;

    const acx = (aRect.left + aRect.right) * 0.5;
    const acy = (aRect.top + aRect.bottom) * 0.5;
    const tcx = (tRect.left + tRect.right) * 0.5;
    const tcy = (tRect.top + tRect.bottom) * 0.5;
    const dx = acx - tcx;
    const dy = acy - tcy;

    const edgeGapH = Math.max(aRect.left - tRect.right, tRect.left - aRect.right, 0);
    const edgeGapV = Math.max(aRect.top - tRect.bottom, tRect.top - aRect.bottom, 0);
    const isHorizontalLayout = edgeGapH >= edgeGapV;

    const dist = shortestRectDistance(aRect, tRect);
    let proximity = 1 - Math.min(1, dist / RANGE_PX);
    proximity = proximity * proximity * (3 - 2 * proximity);
    const intensity = BASE_ALPHA + (BOOST_ALPHA - BASE_ALPHA) * proximity;

    const reflectionAlpha = Math.min(
      MAX_ALPHA_STACK,
      intensity * INTENSITY_MULT * GLOBAL_ATTENUATION
    ) * t.strength;

    // A target that contains the anchor (the card the button lives in) has no
    // single "facing" edge — the button sits near a corner, so the echo lands
    // on both the closest vertical and closest horizontal inner edge.
    const contained =
      aRect.left >= tRect.left && aRect.right <= tRect.right &&
      aRect.top >= tRect.top && aRect.bottom <= tRect.bottom;
    const layouts: boolean[] = contained ? [true, false] : [isHorizontalLayout];

    // Effective scale of the host element. Anything drawn on the reflection
    // canvas (strokes, border-highlight) is in DEVICE pixels, so it doesn't
    // automatically grow when the host is rendered at non-1× layout (CSS
    // zoom: 2, etc.). Multiply absolute-pixel constants by the anchor's
    // scale so the reflection scales together with the metal effect itself.
    const sScale = t.anchor.scale ?? 1;
    const hairlineCssPx = Math.max(STROKE_CSS_PX * sScale, t.hairlineWidth);
    const strokeBandPx = Math.max(1, Math.round(hairlineCssPx * dpr));
    const borderHighlightPx = Math.max(
      1,
      Math.round(Math.max(BORDER_HILITE_PX * sScale, t.hairlineWidth) * dpr)
    );

    const overscanCssPx = t.hairlineOuterCssPx;
    t.wrap.style.inset = `${-overscanCssPx}px`;
    t.wrap.style.borderRadius = `${Math.max(0, t.cornerRadius)}px`;

    const tw = Math.max(1, Math.round((tRect.width + overscanCssPx * 2) * dpr));
    const th = Math.max(1, Math.round((tRect.height + overscanCssPx * 2) * dpr));
    if (t.canvas.width !== tw) t.canvas.width = tw;
    if (t.canvas.height !== th) t.canvas.height = th;
    if (t.strokeCanvas.width !== tw) t.strokeCanvas.width = tw;
    if (t.strokeCanvas.height !== th) t.strokeCanvas.height = th;

    const ctx = t.ctx;
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.clearRect(0, 0, tw, th);
    const strokeCtx = t.strokeCtx;
    strokeCtx.setTransform(1, 0, 0, 1, 0, 0);
    strokeCtx.clearRect(0, 0, tw, th);

    for (const [li, horiz] of layouts.entries()) {
      // First edge paints straight into the target; later edges go via scratch.
      const viaScratch = li > 0 && ensureScratch(tw, th);
      const fCtx = viaScratch ? (scratchFillCtx as CanvasRenderingContext2D) : ctx;
      const sCtx = viaScratch ? (scratchStrokeCtx as CanvasRenderingContext2D) : strokeCtx;
      const bandDevPx = Math.min((glyph ? RANGE_PX * 1.5 : RANGE_PX) * dpr, Math.max(tw, th));
      let g0x: number, g0y: number, g1x: number, g1y: number;
      if (horiz) {
        g0x = dx > 0 ? tw : 0; g1x = dx > 0 ? tw - bandDevPx : bandDevPx;
        g0y = th * 0.5; g1y = th * 0.5;
      } else {
        g0y = dy > 0 ? th : 0; g1y = dy > 0 ? th - bandDevPx : bandDevPx;
        g0x = tw * 0.5; g1x = tw * 0.5;
      }
      const grad = ctx.createLinearGradient(g0x, g0y, g1x, g1y);
      grad.addColorStop(0, `rgba(0,0,0,${GRAD_NEAR})`);
      grad.addColorStop(0.5, `rgba(0,0,0,${GRAD_MID})`);
      grad.addColorStop(1, `rgba(0,0,0,${GRAD_FAR})`);

      const anchorCssW = sw / dpr;
      const refWdpr = glyph
        ? Math.max(1, Math.min(horiz ? tw : th, Math.round(horiz ? sw : sh)))
        : Math.max(1, Math.round(REF_DRAW_CSS_W * Math.max(0.1, anchorCssW / 140) * dpr));

      let drawX: number, drawY: number, drawW: number, drawH: number;
      let flipX = false, flipY = false;
      if (horiz) {
        const overlapTop = Math.max(aRect.top, tRect.top);
        const overlapBot = Math.min(aRect.bottom, tRect.bottom);
        flipX = true;
        drawX = dx > 0 ? tw - refWdpr : 0;
        drawY = Math.round((overlapTop - tRect.top + overscanCssPx) * dpr);
        drawW = refWdpr;
        drawH = Math.max(1, Math.round((overlapBot - overlapTop) * dpr));
      } else {
        const overlapLeft = Math.max(aRect.left, tRect.left);
        const overlapRight = Math.min(aRect.right, tRect.right);
        flipY = true;
        drawX = Math.round((overlapLeft - tRect.left + overscanCssPx) * dpr);
        drawY = dy > 0 ? th - refWdpr : 0;
        drawW = Math.max(1, Math.round((overlapRight - overlapLeft) * dpr));
        drawH = refWdpr;
      }
      const drawDst: DrawDst = { x: drawX, y: drawY, w: drawW, h: drawH, flipX, flipY, sx: ssx, sy: ssy };

      const strokeBox: BoxRect = { x: 0, y: 0, w: tw, h: th, r: Math.max(0, t.cornerRadius * dpr) };

      // Glyphs: one pass, never over 1 — stacking `lighter` passes clips the
      // metal's highlights to white and the colour is gone.
      const fillReflectionAlpha = glyph
        ? Math.min(1, reflectionAlpha * FILL_OPACITY_MUL)
        : Math.min(MAX_ALPHA_STACK, reflectionAlpha * FILL_EXTRA_ALPHA * FILL_OPACITY_MUL * FILL_CIRCLE_ATTENUATION);
      maskedFillPasses(fCtx, anchorCanvas, sw, sh, tw, th, fillReflectionAlpha, grad, drawDst, strokeBox, dpr, glyph ? Math.max(tw, th) : undefined);

      if (!glyph) {
        maskedStrokePasses(
          sCtx, anchorCanvas, sw, sh, tw, th,
          strokeBox, reflectionAlpha, strokeBandPx, grad, STROKE_EXTRA_ALPHA, drawDst
        );

        drawBorderHighlight(
          sCtx, strokeBox, borderHighlightPx,
          g0x, g0y, g1x, g1y,
          Math.min(0.85, BORDER_HILITE_ALPHA * reflectionAlpha)
        );
      }

      if (viaScratch) {
        ctx.globalCompositeOperation = 'lighter';
        ctx.drawImage(scratchFill as HTMLCanvasElement, 0, 0);
        strokeCtx.globalCompositeOperation = 'lighter';
        strokeCtx.drawImage(scratchStroke as HTMLCanvasElement, 0, 0);
      }
    }

    for (const horiz of layouts) {
      applyOccluderShadow(ctx, strokeCtx, aRect, tRect, horiz, tw, th, overscanCssPx, dpr);
    }

    ctx.globalCompositeOperation = 'source-over';
    strokeCtx.globalCompositeOperation = 'source-over';
  }
}

/**
 * Canonical constants and types for proximity reflections.
 *
 * Verbatim from `Image loader/index.html` L5851-5915. Shared across
 * the observer, geometry, and paint modules.
 */
import type { MetalFxInstance } from '../renderer/core';

export const RANGE_PX = 12;
export const ATTACH_RANGE_PX = 32;
export const OVERLAP_MIN_PX = 1;
export const BASE_ALPHA = 0.55;
export const BOOST_ALPHA = 1.0;
export const GRAD_NEAR = 1.0;
export const GRAD_MID = 0.85;
export const GRAD_FAR = 0.0;
export const INTENSITY_MULT = 1.3;
export const MAX_ALPHA_STACK = 3.6;
export const GLOBAL_ATTENUATION = 0.7;
export const STROKE_CSS_PX = 1;
export const STROKE_EXTRA_ALPHA = 0.52;
export const BORDER_HILITE_PX = 1.0;
export const BORDER_HILITE_ALPHA = 0.044;
export const REF_DRAW_CSS_W = 235;
export const FILL_EXTRA_ALPHA = 2.535;
export const FILL_OPACITY_MUL = 0.7;
export const FILL_CIRCLE_ATTENUATION = 0.5;

export const REFLECTION_BLOCKED_TAGS = new Set(['INPUT', 'TEXTAREA', 'SELECT', 'OPTION']);

export interface ReflectionTarget {
  el: HTMLElement;
  anchor: MetalFxInstance;
  anchorEl: HTMLElement;
  /** Per-target alpha multiplier from the public API. 1 = canonical. */
  strength: number;
  wrap: HTMLDivElement;
  canvas: HTMLCanvasElement;
  ctx: CanvasRenderingContext2D;
  strokeCanvas: HTMLCanvasElement;
  strokeCtx: CanvasRenderingContext2D;
  cornerRadius: number;
  hairlineWidth: number;
  hairlineOuterCssPx: number;
  appliedPositionRelative: boolean;
  appliedIsolation: boolean;
  resizeObserver: ResizeObserver | null;
  mutationObserver: MutationObserver | null;
  /** Glyph-target canvas styling applied (see paint). */
  glyphStyled?: boolean;
}

/**
 * Canvas 2D drawing primitives for proximity reflections.
 *
 * All the low-level compositing passes — rounded-rect paths, ring clips,
 * fill/stroke multi-pass alpha stacking, mirror-flip drawImage, and the
 * border-highlight gradient stroke.
 */
import { RANGE_PX } from './constants';

// ─── Layout helpers ───────────────────────────────────────────────────────

export function shortestRectDistance(a: DOMRect, b: DOMRect): number {
  const dx = Math.max(a.left - b.right, b.left - a.right, 0);
  const dy = Math.max(a.top - b.bottom, b.top - a.bottom, 0);
  return Math.sqrt(dx * dx + dy * dy);
}

export function isHorizontalNeighbour(anchorRect: DOMRect, targetRect: DOMRect, overlapMin: number, attachRange: number): boolean {
  const verticalOverlap =
    Math.min(anchorRect.bottom, targetRect.bottom) -
    Math.max(anchorRect.top, targetRect.top);
  if (verticalOverlap < overlapMin) return false;
  const horizontalGap = Math.max(
    anchorRect.left - targetRect.right,
    targetRect.left - anchorRect.right,
    0
  );
  if (horizontalGap > attachRange) return false;
  return true;
}

export function isVerticalNeighbour(anchorRect: DOMRect, targetRect: DOMRect, overlapMin: number, attachRange: number): boolean {
  const horizontalOverlap =
    Math.min(anchorRect.right, targetRect.right) -
    Math.max(anchorRect.left, targetRect.left);
  if (horizontalOverlap < overlapMin) return false;
  const verticalGap = Math.max(
    anchorRect.top - targetRect.bottom,
    targetRect.top - anchorRect.bottom,
    0
  );
  return verticalGap <= attachRange;
}

// ─── Path helpers ─────────────────────────────────────────────────────────

export function roundRectPath(
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  w: number,
  h: number,
  r: number
): void {
  const rr = Math.max(0, Math.min(r, w * 0.5, h * 0.5));
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const native = (ctx as any).roundRect;
  if (typeof native === 'function') {
    native.call(ctx, x, y, w, h, rr);
    return;
  }
  ctx.moveTo(x + rr, y);
  ctx.lineTo(x + w - rr, y);
  ctx.quadraticCurveTo(x + w, y, x + w, y + rr);
  ctx.lineTo(x + w, y + h - rr);
  ctx.quadraticCurveTo(x + w, y + h, x + w - rr, y + h);
  ctx.lineTo(x + rr, y + h);
  ctx.quadraticCurveTo(x, y + h, x, y + h - rr);
  ctx.lineTo(x, y + rr);
  ctx.quadraticCurveTo(x, y, x + rr, y);
}

// ─── Draw source (mirror flip) ───────────────────────────────────────────

export interface DrawDst {
  x: number;
  y: number;
  w: number;
  h: number;
  flipX: boolean;
  flipY: boolean;
  /** Source-rect origin in the anchor canvas, device px. Non-zero while the
   *  anchor is overscanned (vector bend) so only its CSS box is sampled. */
  sx?: number;
  sy?: number;
}

export function drawSource(
  ctx: CanvasRenderingContext2D,
  src: CanvasImageSource,
  sw: number,
  sh: number,
  dst: DrawDst
): void {
  if (!dst.flipX && !dst.flipY) {
    ctx.drawImage(src, dst.sx ?? 0, dst.sy ?? 0, sw, sh, dst.x, dst.y, dst.w, dst.h);
    return;
  }
  ctx.save();
  if (dst.flipX) {
    ctx.translate(dst.x + dst.w, 0);
    ctx.scale(-1, 1);
  }
  if (dst.flipY) {
    ctx.translate(0, dst.y + dst.h);
    ctx.scale(1, -1);
  }
  ctx.drawImage(
    src,
    dst.sx ?? 0,
    dst.sy ?? 0,
    sw,
    sh,
    dst.flipX ? 0 : dst.x,
    dst.flipY ? 0 : dst.y,
    dst.w,
    dst.h
  );
  ctx.restore();
}

// ─── Clip + compositing passes ────────────────────────────────────────────

export interface BoxRect {
  x: number;
  y: number;
  w: number;
  h: number;
  r: number;
}

const FILL_BLUR_CSS_PX = 4;

function fillRingClip(
  ctx: CanvasRenderingContext2D,
  x: number, y: number, w: number, h: number,
  radiusDevPx: number, bandDevPx: number
): void {
  if (w <= 2 * bandDevPx || h <= 2 * bandDevPx) {
    ctx.beginPath();
    roundRectPath(ctx, x, y, w, h, radiusDevPx);
    ctx.clip();
    return;
  }
  ctx.beginPath();
  roundRectPath(ctx, x, y, w, h, radiusDevPx);
  roundRectPath(ctx, x + bandDevPx, y + bandDevPx, w - 2 * bandDevPx, h - 2 * bandDevPx, Math.max(0, radiusDevPx - bandDevPx));
  ctx.clip('evenodd');
}

export function maskedFillPasses(
  ctx: CanvasRenderingContext2D,
  src: CanvasImageSource,
  sw: number, sh: number,
  tw: number, th: number,
  totalAlpha: number,
  grad: CanvasGradient,
  dst: DrawDst,
  fillBox: BoxRect,
  dpr: number,
  /** Override for the edge band the fill is clipped to, device px. Glyph
   *  targets pass the whole box — letters have no "rim" to hug. */
  bandDevPxOverride?: number
): void {
  const fillBandDevPx = bandDevPxOverride ?? Math.max(1, Math.round((RANGE_PX + FILL_BLUR_CSS_PX * 3) * dpr));
  let remaining = Math.max(0, totalAlpha);
  let firstChunk = true;
  for (let i = 0; i < 3 && remaining > 1e-4; i++) {
    const a = Math.min(1, remaining);
    ctx.save();
    fillRingClip(ctx, fillBox.x, fillBox.y, fillBox.w, fillBox.h, fillBox.r, fillBandDevPx);
    ctx.globalCompositeOperation = firstChunk ? 'source-over' : 'lighter';
    firstChunk = false;
    ctx.globalAlpha = a;
    drawSource(ctx, src, sw, sh, dst);
    ctx.globalAlpha = 1;
    ctx.globalCompositeOperation = 'destination-in';
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, tw, th);
    ctx.restore();
    remaining -= a;
  }
}

function insideStrokeEvenOddClip(
  ctx: CanvasRenderingContext2D,
  x: number, y: number, w: number, h: number,
  radiusDevPx: number, strokeDevPx: number
): void {
  const r = strokeDevPx | 0;
  if (r < 1 || w <= 2 * r || h <= 2 * r) {
    ctx.beginPath();
    roundRectPath(ctx, x, y, w, h, radiusDevPx);
    ctx.clip();
    return;
  }
  ctx.beginPath();
  roundRectPath(ctx, x, y, w, h, radiusDevPx);
  roundRectPath(ctx, x + r, y + r, w - 2 * r, h - 2 * r, Math.max(0, radiusDevPx - r));
  ctx.clip('evenodd');
}

export function maskedStrokePasses(
  ctx: CanvasRenderingContext2D,
  src: CanvasImageSource,
  sw: number, sh: number,
  tw: number, th: number,
  strokeBox: BoxRect,
  intensity: number,
  strokeBandPx: number,
  grad: CanvasGradient,
  strokeExtraAlpha: number,
  dst: DrawDst
): void {
  let remaining = intensity * strokeExtraAlpha;
  let firstChunk = true;
  for (let i = 0; i < 3 && remaining > 1e-4; i++) {
    const a = Math.min(1, remaining);
    ctx.save();
    insideStrokeEvenOddClip(ctx, strokeBox.x, strokeBox.y, strokeBox.w, strokeBox.h, strokeBox.r, strokeBandPx);
    ctx.globalCompositeOperation = firstChunk ? 'source-over' : 'lighter';
    firstChunk = false;
    ctx.globalAlpha = a;
    drawSource(ctx, src, sw, sh, dst);
    ctx.globalAlpha = 1;
    ctx.globalCompositeOperation = 'destination-in';
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, tw, th);
    ctx.restore();
    remaining -= a;
  }
}

export function drawBorderHighlight(
  ctx: CanvasRenderingContext2D,
  strokeBox: BoxRect,
  strokeDevPx: number,
  g0x: number, g0y: number,
  g1x: number, g1y: number,
  alpha: number
): void {
  const grad = ctx.createLinearGradient(g0x, g0y, g1x, g1y);
  grad.addColorStop(0, `rgba(255,255,255,${alpha.toFixed(3)})`);
  grad.addColorStop(0.5, `rgba(255,255,255,${(alpha * 0.45).toFixed(3)})`);
  grad.addColorStop(1, 'rgba(255,255,255,0)');

  ctx.save();
  insideStrokeEvenOddClip(ctx, strokeBox.x, strokeBox.y, strokeBox.w, strokeBox.h, strokeBox.r, strokeDevPx);
  ctx.globalCompositeOperation = 'lighter';
  ctx.lineWidth = strokeDevPx * 2;
  ctx.strokeStyle = grad;
  ctx.beginPath();
  roundRectPath(ctx, strokeBox.x, strokeBox.y, strokeBox.w, strokeBox.h, strokeBox.r);
  ctx.stroke();
  ctx.restore();
}

/**
 * Style observation for reflection targets.
 *
 * Reads corner radii and hairline specs from computed styles, and
 * attaches ResizeObserver / MutationObserver so values stay fresh
 * without per-frame getComputedStyle calls.
 */
import type { ReflectionTarget } from './constants';

export function readCornerRadius(el: HTMLElement): number {
  const cs = getComputedStyle(el);
  const radii = [
    parseFloat(cs.borderTopLeftRadius) || 0,
    parseFloat(cs.borderTopRightRadius) || 0,
    parseFloat(cs.borderBottomRightRadius) || 0,
    parseFloat(cs.borderBottomLeftRadius) || 0,
  ].filter((v) => v > 0);
  return radii.length ? Math.min.apply(null, radii) : 0;
}

/**
 * Read the visible "hairline" geometry of the host so the 1-px stroke
 * reflection sits exactly on the host's existing ring.
 *
 * Returns the visible thickness (`width`) and the OUTWARD extent past the
 * padding-box edge (`outerCssPx`) — the wrap is overscanned by `outerCssPx`
 * on every side so its outer rim lines up with the host's visible silhouette.
 *
 * Source contributions:
 *   - CSS `border-*-width` (max across the 4 sides)
 *   - smallest `inset` `box-shadow` with spread > 0
 *   - smallest outset `box-shadow` with spread > 0
 */
export function readHairlineSpec(el: HTMLElement): { width: number; outerCssPx: number } {
  const cs = getComputedStyle(el);
  const borderMax = Math.max(
    parseFloat(cs.borderTopWidth) || 0,
    parseFloat(cs.borderRightWidth) || 0,
    parseFloat(cs.borderBottomWidth) || 0,
    parseFloat(cs.borderLeftWidth) || 0
  );

  let smallestInsetSpread = 0;
  let smallestOutsetSpread = 0;
  const shadow = cs.boxShadow;
  if (shadow && shadow !== 'none') {
    const safe = shadow.replace(/rgba?\([^)]*\)/g, (m) => m.replace(/,/g, '\u0000'));
    const parts = safe.split(/,\s*/);
    let inset = Infinity;
    let outset = Infinity;
    for (const part of parts) {
      const nums = part.match(/-?\d+(?:\.\d+)?px/g);
      if (!nums || nums.length < 4) continue;
      const spread = parseFloat(nums[3]);
      if (!(spread > 0)) continue;
      if (/\binset\b/.test(part)) {
        if (spread < inset) inset = spread;
      } else if (spread < outset) {
        outset = spread;
      }
    }
    if (Number.isFinite(inset)) smallestInsetSpread = inset;
    if (Number.isFinite(outset)) smallestOutsetSpread = outset;
  }

  const outerCssPx = Math.max(borderMax, smallestOutsetSpread);
  const width =
    Math.max(borderMax, smallestInsetSpread, smallestOutsetSpread) || 1;

  return { width, outerCssPx };
}

function refreshTargetStyles(t: ReflectionTarget): void {
  t.cornerRadius = readCornerRadius(t.el);
  const spec = readHairlineSpec(t.el);
  t.hairlineWidth = spec.width;
  t.hairlineOuterCssPx = spec.outerCssPx;
}

export function attachObservers(t: ReflectionTarget): void {
  if (typeof ResizeObserver !== 'undefined') {
    t.resizeObserver = new ResizeObserver(() => refreshTargetStyles(t));
    t.resizeObserver.observe(t.el);
  }
  if (typeof MutationObserver !== 'undefined') {
    t.mutationObserver = new MutationObserver(() => refreshTargetStyles(t));
    t.mutationObserver.observe(t.el, {
      attributes: true,
      attributeFilter: ['style', 'class'],
    });
  }
}

export function detachObservers(t: ReflectionTarget): void {
  t.resizeObserver?.disconnect();
  t.resizeObserver = null;
  t.mutationObserver?.disconnect();
  t.mutationObserver = null;
}

/**
 * Auxiliary RAF driver for *target-side* work (currently: dark-mode reflections).
 *
 * Reflections run at 15 fps — the CSS blur(4px) on the fill canvas hides
 * temporal stepping completely. The scheduler coalesces rapid calls and
 * skips frames that arrive faster than the target interval.
 */
import { REFLECTION_INTERVAL_MS } from '../perfConfig';
import { paintReflections } from './paint';

let scheduled = false;
let lastReflectionMs = 0;

export function scheduleReflectionPaint(): void {
  if (scheduled) return;
  scheduled = true;
  if (typeof requestAnimationFrame === 'undefined') return;
  requestAnimationFrame((now) => {
    scheduled = false;
    if (now - lastReflectionMs < REFLECTION_INTERVAL_MS) return;
    lastReflectionMs = now;
    paintReflections();
  });
}

const STYLE_ID = 'metal-fx-styles';

const CSS = /* css */ `
.metal-fx-root {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  isolation: isolate;
  overflow: visible;
  background: #272727;
  color: #f8f8f8;
}
.metal-fx-root[data-theme='light'] {
  background: #ffffff;
  color: #1d1d1d;
}

.metal-fx-root::before {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  pointer-events: none;
  z-index: 2;
  box-shadow: inset 0 0 50px 0 rgba(255, 255, 255, 0.02);
}
.metal-fx-root[data-theme='light']::before {
  box-shadow: inset 0 0 50px 0 rgba(0, 0, 0, 0.02);
}

.metal-fx-root::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  pointer-events: none;
  z-index: 4;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.1);
}
.metal-fx-root[data-theme='light']::after {
  box-shadow: inset 0 0 0 1px rgba(0, 0, 0, 0.06);
}
/* Circle variant gets a thicker outer rim than the button variant. */
.metal-fx-root[data-variant='circle']::after {
  box-shadow: inset 0 0 0 2px rgba(255, 255, 255, 0.1);
}
.metal-fx-root[data-theme='light'][data-variant='circle']::after {
  box-shadow: inset 0 0 0 2px rgba(0, 0, 0, 0.06);
}

.metal-fx-canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  z-index: 0;
  pointer-events: none;
  border-radius: inherit;
}

/* The inner spacer — defines the inset geometry where the metal ring meets
   the interior (3 px for Button, 1-2 px for Circle) and carries the Circle dark
   hairline ('box-shadow: inset' rules below). Intentionally transparent so
   the wrapper's background propagates through to the punched shader centre,
   giving consumers a single surface tone to override. See "Single-surface
   background" in the file header for the rationale. */
.metal-fx-inner {
  position: absolute;
  inset: 3px;
  border-radius: inherit;
  z-index: 1;
  pointer-events: none;
}

.metal-fx-root[data-variant='button'][data-shape='pill'] .metal-fx-inner {
  border-radius: calc(var(--mfx-radius, 20px) - 3px);
}
.metal-fx-root[data-variant='button'][data-shape='circle'] .metal-fx-inner {
  border-radius: calc(var(--mfx-radius, 16px) - 3px);
}
.metal-fx-root[data-variant='circle'][data-shape='pill'] .metal-fx-inner {
  inset: 0;
  border-radius: var(--mfx-radius, 20px);
  box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.45);
}
.metal-fx-root[data-variant='circle'][data-shape='circle'] .metal-fx-inner {
  inset: 0;
  border-radius: var(--mfx-radius, 16px);
  box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.45);
}
/* Circle-variant hairline alpha — light mode.
   Source-of-truth: index.html L2261-2267. The 0.45-alpha black inset that
   reads as a single-pixel frame against the dark interior is too heavy
   on a #ffffff inner: it ends up looking like a hard 2-px black ring
   against the iridescent shader. Suppressed entirely (alpha 0) — the
   shader's own iridescent rim already defines the silhouette in light
   mode, so an extra dark hairline only competes with it. The rule is
   kept (rather than deleted) as a tunable hook in case a future variant
   wants to re-introduce a soft edge. NOTE: we keep the dark-mode inset
   and border-radius values because — unlike index.html — our renderer
   does NOT overscan the canvas in light mode, so there is no 1-px gap
   between inner element and shader to compensate for. */
.metal-fx-root[data-theme='light'][data-variant='circle'][data-shape='pill'] .metal-fx-inner,
.metal-fx-root[data-theme='light'][data-variant='circle'][data-shape='circle'] .metal-fx-inner {
  box-shadow: 0 0 0 1px rgba(0, 0, 0, 0);
}

/* ─── Combined glow SVG (z=3) ──────────────────────────────────────────────
   Single SVG per instance that holds BOTH the wide-halo group
   (#mfx_haloTravel) and the catch-light group (#mfx_extraTravel), exactly
   mirroring canonical's _buildGlowSvgInner (index.html L8078). One
   mix-blend-mode: screen lifts the combined composite onto the shader
   ring; per-frame opacity attributes on each inner group still drive the
   independent fade-in / fade-out cycles for the halo and the catch-light.

   Why a single SVG: the circle variant anchors halo + catch-light at the same
   perimeter point, so they overlap in the bright zone. Two separately-
   screened SVGs would double-screen the overlap (A + B + C - AB - AC -
   BC + ABC instead of A + B + C - AB - AC once both groups composite
   in source-over inside one SVG and then screen against the host once).
   That overlap looked muted versus canonical specifically on the circle
   variant where both layers travel together.

   Source-of-truth opacity: #btnGlowSvg drops to 0.7 in dark and 0.2746 in
   light (index.html L632/L643). */
.metal-fx-glow-svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  overflow: visible;
  z-index: 3;
  pointer-events: none;
  opacity: 0.7;
}
.metal-fx-root[data-theme='light'] .metal-fx-glow-svg {
  /* Light-mode 1-px overscan mirrors .btn-glow-svg in metal.html so the
     halo stays glued to the visible silhouette (the shader ring there sits
     1 px outside the host's padding box). */
  inset: -1px;
  width: calc(100% + 2px);
  height: calc(100% + 2px);
  mix-blend-mode: multiply;
  /* Source-of-truth: html[data-theme="light"] #btnGlowSvg { opacity: 0.2746 }
     → −35 % from 0.4225 from the original 0.7 dark-mode opacity. */
  opacity: 0.2746;
  filter: saturate(5.355) brightness(0.78);
}
/* Circle light-mode small variants (e.g. 36×36 send button): the geometrically
   shrunk halo loses density when multiplied against #ffffff. Mirror the
   canonical override at index.html L2316 — bump saturation + drop brightness
   so the small glow holds together visually. */
.metal-fx-root[data-variant='circle'][data-shape='circle'][data-theme='light'] .metal-fx-glow-svg {
  filter: saturate(7.5) brightness(0.6);
}

/* The wrapped child — hoisted into z=5 so it sits above every overlay, with
   normalized chrome so consumer button styles don't fight the metal frame. */
.metal-fx-content {
  position: relative;
  z-index: 5;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  pointer-events: none;
}
.metal-fx-content > * {
  pointer-events: auto;
}
.metal-fx-root[data-normalize='true'] .metal-fx-content > * {
  background: transparent !important;
  border: 0 !important;
  outline: 0 !important;
  box-shadow: none !important;
  /* Sizing: we deliberately DO NOT force \`width: 100%; height: 100%\` on the
     child here. That used to be the contract ("the wrapper is the visible
     button surface; the child stretches to fill it"), but it created a cyclic
     percentage dependency: the wrapper is \`inline-flex\` with no intrinsic
     size, .metal-fx-content is \`width/height: 100%\` of the wrapper, and the
     child was \`100%\` of .metal-fx-content. With nothing breaking the cycle,
     icon-only / class-sized children collapsed.

     The new contract: the child sizes itself (intrinsic content, CSS class,
     or inline style — all work), and the wrapper's \`inline-flex\` wraps it
     tightly. Consumers who want a metal frame BIGGER than the child (e.g.
     padding around an icon) size <MetalFx style={{ width, height }}> AND
     explicitly set width/height on the child to fill (or accept that the
     child renders at its intrinsic size, centered).

     Typography is intentionally NOT touched. We used to apply
     \`color: inherit; font: inherit;\` here to "match" the wrapper, but
     \`font: inherit\` is a shorthand that overrides font-family, font-size,
     font-weight, AND line-height on the child — which (a) shrank the
     button height (line-height changes propagate through the flex
     content box) and (b) scaled em-based icons / font-icons inside the
     child to whatever the wrapper inherited. The wrapper now stays out
     of the child's typography entirely; consumers who want typographic
     normalization can apply it themselves on the child element. */
}

[data-metal-fx-reflection] {
  position: absolute;
  inset: 0;
  pointer-events: none;
  border-radius: inherit;
  overflow: hidden;
  z-index: 0;
  isolation: isolate;
}
.metal-fx-reflection-canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  filter: blur(4px) saturate(1.2) brightness(1.58);
}
.metal-fx-reflection-stroke-canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  filter: saturate(1.35) brightness(1.75);
}
/* Hosts that participate as reflection targets need positioning + isolation
   so the wrap composites only against the host (not the parent stack). The
   wrap injects these inline as well, but stating them here keeps reflections
   working on hosts that already have other inline styles applied. */
[data-metal-fx-reflect-host] {
  isolation: isolate;
}
`;

let injected = false;

export function ensureStylesInjected(): void {
  if (injected) return;
  if (typeof document === 'undefined') return;
  if (document.getElementById(STYLE_ID)) { injected = true; return; }
  const style = document.createElement('style');
  style.id = STYLE_ID;
  style.textContent = CSS;
  document.head.appendChild(style);
  injected = true;
}

import type { CSSProperties, ReactNode, HTMLAttributes, RefObject } from 'react';
import type { MaskFn } from './engine/renderer/core';

/**
 * Variant for the metal effect.
 * - 'button' (default): pill-shaped 134×40 baseline with shaderScale 1.6
 * - 'circle': compact 32×32 circle baseline with shaderScale 1.3
 *
 * In practice the wrapped child's measured dimensions drive the visible size —
 * the variant only controls the shader sampling scale and ring thickness.
 */
export type MetalFxVariant = 'button' | 'circle';

/**
 * Theme mode for the metal effect.
 *
 * - `auto` (default): follows the user's `prefers-color-scheme` and updates
 *   live when the OS / browser theme changes (also gracefully falls back to
 *   `dark` during SSR or when `matchMedia` is unavailable).
 * - `dark`: pin to the dark-mode tunings regardless of system preference.
 * - `light`: pin to the light-mode tunings regardless of system preference.
 *
 * Drive this from your app's theme state if you have a manual toggle that
 * doesn't follow the OS — otherwise `auto` is the right default.
 */
export type MetalFxTheme = 'dark' | 'light' | 'auto';

/**
 * Bundled preset names. Each preset ships both a dark and light mode block.
 */
export type MetalFxPreset = 'chromatic' | 'silver' | 'gold';

/**
 * A reflection target: either a bare ref, or a ref plus a per-target
 * `strength` multiplier (0..1+). Use the object form when a surface should
 * only catch a faint echo of the metal — a container the button sits inside,
 * for example — without turning down every other target.
 */
export type MetalFxReflectionTarget =
  | RefObject<HTMLElement | null>
  | { ref: RefObject<HTMLElement | null>; strength?: number };

/**
 * Props for the MetalFx React component.
 */
export interface MetalFxProps extends Omit<HTMLAttributes<HTMLDivElement>, 'children'> {
  /**
   * The single host element to wrap with the metal effect. Must be a single
   * React node (button, anchor, div, ...). MetalFx measures this element each
   * frame via `ResizeObserver` and paints its canvas + glow on top.
   */
  children: ReactNode;

  /**
   * Variant — controls the shader sampling scale + ring width.
   * - `button` (default): pill-style ring at 1 px wide, scale 1.6
   * - `circle`: compact circle with a 2 px ring, scale 1.3
   */
  variant?: MetalFxVariant;

  /**
   * Color preset. All three presets ship both dark and light mode tunings —
   * `theme` picks the right side at runtime.
   * @default 'chromatic'
   */
  preset?: MetalFxPreset;

  /**
   * Theme mode. `'auto'` (default) resolves via
   * `matchMedia('(prefers-color-scheme: dark)')` and switches live when the
   * OS theme changes. Pass `'dark'` or `'light'` to pin a specific mode.
   * @default 'auto'
   */
  theme?: MetalFxTheme;

  /**
   * Effect strength (0..1). Multiplies the shader bitmap opacity and the glow
   * SVG alpha. The shader continues to animate at full intensity at any value;
   * only the rendered alpha onto the host is scaled. Lighter values let the
   * underlying child surface show through more strongly.
   * @default 1
   */
  strength?: number;

  /**
   * Multiplier on the glow only (halo + catch-light), on top of `strength`.
   * Use it when the shader runs at low `strength` but the glow should still
   * read — e.g. metal text. Clamped to 0..1 after multiplying.
   * @default 1
   */
  glowGain?: number;

  /**
   * Pause the shader animation. The visible canvas keeps the last painted
   * frame so the metal silhouette stays on screen.
   * @default false
   */
  paused?: boolean;

  /**
   * Optional explicit border radius (CSS px). When omitted, MetalFx reads the
   * computed border-radius of the wrapped child each resize.
   */
  borderRadius?: number;

  /**
   * When true, MetalFx normalizes the host element's outer chrome (border /
   * outline / box-shadow) so user-provided component styles don't clash with
   * the metal ring. Inner fills, typography, and content remain untouched.
   * @default true
   */
  normalizeHostStyles?: boolean;

  /**
   * Neighbour elements that should receive a soft proximity reflection of the
   * metal effect. Reflections only render when the resolved theme is `dark` —
   * pass-through in light mode (no DOM scan, no per-frame work).
   *
   * Pass refs to the sibling DOM elements you want to receive the reflection
   * (chips next to a send button, search field next to an Upgrade pill, ...).
   *
   * A target that *contains* the wrapped element (its parent card, say)
   * receives the reflection on both the nearest vertical and horizontal
   * inner edges. Pair with `{ ref, strength }` to keep that subtle.
   */
  reflectionTargets?: ReadonlyArray<MetalFxReflectionTarget>;

  /**
   * Disable the wandering halo overlay. The shader ring still renders.
   * @default false
   */
  disableGlow?: boolean;

  /**
   * Light rim along the top inside edge of the ring — an inner shadow from
   * above, like the one on metal text. `true` uses the design defaults
   * (white 90 %, offset 1 px, blur 0.5 px); pass an object to tune.
   * @default undefined (off)
   */
  innerShadow?: boolean | { offsetY?: number; blur?: number; alpha?: number; color?: string };

  /**
   * Override the shader sampling scale. Larger values zoom into the shared
   * shader (visibly bigger pattern features); smaller values zoom out.
   * Defaults to the variant's baseline (1.6 for `'button'`, 1.3 for
   * `'circle'`) multiplied by `scale`.
   */
  shaderScale?: number;

  /**
   * Override the ring thickness in CSS pixels. Defaults to the variant's
   * baseline (1 for `'button'`, 2 for `'circle'`) multiplied by `scale`.
   */
  ringCssPx?: number;

  /**
   * Master scale multiplier for every absolute-pixel constant the engine
   * uses internally. Set this when you render the wrapped element at a
   * non-1× size (e.g. inside a CSS `zoom: 2` container, or when you've
   * doubled all your Tailwind sizes by hand). It scales:
   *   - shader sampling (so pattern features grow proportionally)
   *   - ring thickness on the canvas
   *   - glow SVG stroke widths, blur radii, fade-circle radius, and the
   *     small inset/outward offsets that position the catch-light
   *   - reflection canvas stroke band, border-highlight thickness, and the
   *     reference draw width baseline
   * @default 1
   */
  scale?: number;

  /**
   * Custom alpha mask painter. When set, the shader is kept only where the
   * mask paints (device px, origin at the wrapper's top-left) and the ring
   * punch is skipped — for metal-filled text or glyphs. Pair with
   * `disableGlow`; the glow assumes a ring perimeter.
   */
  mask?: MaskFn;

  /**
   * How the glow is placed when `mask` is set. `'mask'` (default) samples
   * points inside the mask and clips the halo to it — right for metal text.
   * `'ring'` keeps the rounded-rect perimeter behaviour — a halo along the
   * element's edge — for a full-fill mask like a badge.
   */
  glowMode?: 'mask' | 'ring';

  /**
   * Forwarded class name for the wrapper element.
   */
  className?: string;

  /**
   * Forwarded inline styles for the wrapper element.
   */
  style?: CSSProperties;
}

/**
 * Bare metal-filled text — the Pro badge's glyph treatment without the pill.
 * Figma: Portfolio › 1471:40925 ("Plan Pro" card).
 *
 * MetalFx's `mask` paints the word with the same font and metrics as the
 * live span, so layout and hit-testing stay DOM. The metal is composited
 * over the live text, so `color` is the tone the shader blends onto — the
 * design's own colour, not white. The canvas is lifted above the content
 * layer and the glow (clipped to the glyphs) above that.
 */
import React, { useCallback, useEffect, useRef, type CSSProperties } from 'react';
import { MetalFx } from './MetalFx';
import type { MetalFxReflectionTarget, MetalFxTheme } from './types';
import type { MaskFn } from './engine/renderer/core';
import { gaussBlur } from './engine/glow/bake';
import { paintTextRun } from './engine/textMask';

/**
 * Figma inner shadow on the text (1471:40930): white 90 %, offset 0/1,
 * blur 0.5 — a hairline of light along the top inside edge of every glyph.
 * CSS has no inner shadow for text, so it's computed: glyph alpha minus the
 * same alpha shifted down by the offset leaves exactly that top rim, which is
 * then blurred and drawn white on an overlay above the metal.
 */
export interface TextInnerShadow { offsetY: number; blur: number; alpha: number }
const FIGMA_INNER_SHADOW: TextInnerShadow = { offsetY: 1, blur: 0.5, alpha: 0.9 };
/** Tuned on the demo's "Plan Pro" card. */
export const METAL_TEXT_DEFAULTS = Object.freeze({ metalOpacity: 0.62, shaderScale: 2.8, glowGain: 2.5, innerShadow: FIGMA_INNER_SHADOW });

function drawInnerShadow(cv: HTMLCanvasElement, root: HTMLElement, textEl: HTMLElement, sh: TextInnerShadow): void {
  const dpr = window.devicePixelRatio || 1;
  const rr = root.getBoundingClientRect();
  const w = Math.max(1, Math.round(rr.width * dpr)), h = Math.max(1, Math.round(rr.height * dpr));
  const off = document.createElement('canvas');
  off.width = w; off.height = h;
  const og = off.getContext('2d', { willReadFrequently: true });
  const g = cv.getContext('2d');
  if (!og || !g) return;
  og.fillStyle = '#fff';
  paintTextRun(og, root, textEl, dpr);
  const d = og.getImageData(0, 0, w, h).data;
  const n = w * h;
  const a = new Float32Array(n);
  for (let i = 0, j = 3; i < n; i++, j += 4) a[i] = d[j] / 255;
  const shift = Math.max(1, Math.round(sh.offsetY * dpr)) * w;
  const rim = new Float32Array(n);
  for (let i = 0; i < n; i++) {
    const above = i >= shift ? a[i - shift] : 0;
    // Coverage the shifted glyph doesn't cover — the strip along the top
    // edge. A difference, not a product: on anti-aliased side edges both
    // values are partial and a product lit every edge of every glyph.
    rim[i] = Math.max(0, a[i] - above);
  }
  const blurred = gaussBlur(rim, w, h, sh.blur * dpr);
  cv.width = w; cv.height = h;
  cv.style.width = `${rr.width}px`; cv.style.height = `${rr.height}px`;
  const img = g.createImageData(w, h);
  const o = img.data;
  for (let i = 0, j = 0; i < n; i++, j += 4) {
    o[j] = 255; o[j + 1] = 255; o[j + 2] = 255;
    // Inner shadow: clipped to the glyph, so the blur never leaks outside
    // the letterform (it read as a halo, worst when zoomed in).
    o[j + 3] = Math.round(Math.min(1, blurred[i] * a[i] * sh.alpha) * 255);
  }
  g.putImageData(img, 0, 0);
}

// MetalFx dresses its root as a button: fill, inset rims (::before/::after)
// and the inner hairline. Bare text wants none of that — only the glyphs.
const BARE_STYLE_ID = 'mfx-bare-style';
const BARE_CSS =
  '.metal-fx-root[data-mfx-bare]{background:transparent!important}' +
  '.metal-fx-root[data-mfx-bare]::before,.metal-fx-root[data-mfx-bare]::after{box-shadow:none!important}' +
  '.metal-fx-root[data-mfx-bare] .metal-fx-inner{display:none!important}';

export function MetalText({
  children,
  font,
  color,
  strength = 1,
  theme,
  reflectionTargets,
  className,
  innerShadow = FIGMA_INNER_SHADOW,
  glow = false,
  glowGain = METAL_TEXT_DEFAULTS.glowGain,
  metalOpacity = METAL_TEXT_DEFAULTS.metalOpacity,
  shaderScale = METAL_TEXT_DEFAULTS.shaderScale,
}: {
  children: string;
  /** CSS `font` shorthand for the live span, e.g. `500 24px/1 Inter, sans-serif`. */
  font: string;
  /** Base text colour from the design; the metal composites over it. */
  color: string;
  strength?: number;
  theme?: MetalFxTheme;
  reflectionTargets?: ReadonlyArray<MetalFxReflectionTarget>;
  className?: string;
  /** Top-edge light rim inside the glyphs. Pass null to disable. */
  innerShadow?: TextInnerShadow | null;
  /** Halo on the glyphs. Off by default — the design has none. */
  glow?: boolean;
  /** Glow multiplier when `glow` is on. */
  glowGain?: number;
  /** How much metal shows over the base colour (0..1), multiplied with `strength`. */
  metalOpacity?: number;
  /** Zoom of the metal inside the glyphs. */
  shaderScale?: number;
}) {
  const rootRef = useRef<HTMLDivElement>(null);
  const textRef = useRef<HTMLSpanElement>(null);
  useEffect(() => {
    if (!document.getElementById(BARE_STYLE_ID)) {
      const st = document.createElement('style');
      st.id = BARE_STYLE_ID;
      st.textContent = BARE_CSS;
      document.head.appendChild(st);
    }
    rootRef.current?.setAttribute('data-mfx-bare', '');
    const cv = rootRef.current?.querySelector<HTMLCanvasElement>('canvas.metal-fx-canvas');
    if (cv) cv.style.zIndex = '6';
    const host = rootRef.current?.querySelector<HTMLElement>('.metal-fx-glow-svg')?.parentElement;
    if (host) host.style.zIndex = '7';
  }, []);

  // Inner-shadow overlay: above the metal (6) and the glow (7), redrawn when
  // fonts land or the box changes. Static otherwise.
  useEffect(() => {
    const root = rootRef.current, t = textRef.current;
    if (!root || !t || !innerShadow) return;
    const cv = document.createElement('canvas');
    cv.className = 'metal-fx-text-rim';
    cv.setAttribute('aria-hidden', 'true');
    cv.style.cssText = 'position:absolute;left:0;top:0;pointer-events:none;z-index:8';
    root.appendChild(cv);
    const draw = () => drawInnerShadow(cv, root, t, innerShadow);
    draw();
    let alive = true;
    document.fonts?.ready.then(() => { if (alive) draw(); });
    const ro = new ResizeObserver(draw);
    ro.observe(root);
    // Browser zoom changes the DPR without changing the CSS box, so the
    // ResizeObserver stays quiet; re-rasterise from a resolution query.
    let mql: MediaQueryList | null = null;
    const watchDpr = () => {
      mql?.removeEventListener('change', onDpr);
      mql = typeof window.matchMedia === 'function' ? window.matchMedia(`(resolution: ${window.devicePixelRatio || 1}dppx)`) : null;
      mql?.addEventListener('change', onDpr);
    };
    const onDpr = () => { if (!alive) return; draw(); watchDpr(); };
    watchDpr();
    return () => { alive = false; ro.disconnect(); mql?.removeEventListener('change', onDpr); cv.remove(); };
  }, [innerShadow]);

  const mask = useCallback<MaskFn>((ctx, _w, _h, dpr) => {
    const root = rootRef.current, t = textRef.current;
    if (root && t) paintTextRun(ctx, root, t, dpr);
  }, []);

  const style: CSSProperties = { font, color, letterSpacing: 0, whiteSpace: 'nowrap' };

  return (
    <MetalFx
      ref={rootRef}
      preset="chromatic"
      theme={theme}
      strength={strength * metalOpacity}
      glowGain={glowGain}
      disableGlow={!glow}
      mask={mask}
      reflectionTargets={reflectionTargets}
      shaderScale={shaderScale}
      borderRadius={4}
      style={{ background: 'transparent', borderRadius: 4 }}
    >
      <span ref={textRef} className={className} style={style} aria-label={children}>
        {children}
      </span>
    </MetalFx>
  );
}

/**
 * Paint an element's text run onto a canvas with the DOM's own font and
 * metrics, so canvas glyphs land on the DOM glyphs to within a device px.
 * Shared by the Pro badge's metal fill and the text reflection mask.
 *
 * `ctx` is expected in device px with origin at `root`'s top-left; the
 * function scales by `dpr` internally.
 */
export function paintTextRun(
  ctx: CanvasRenderingContext2D,
  root: HTMLElement,
  textEl: HTMLElement,
  dpr: number
): void {
  const cs = getComputedStyle(textEl);
  const rr = root.getBoundingClientRect();
  const range = document.createRange();
  range.selectNodeContents(textEl);
  const tr = range.getBoundingClientRect();
  range.detach();
  ctx.save();
  ctx.scale(dpr, dpr);
  ctx.font = `${cs.fontStyle} ${cs.fontWeight} ${cs.fontSize} ${cs.fontFamily}`;
  ctx.textAlign = 'left';
  ctx.textBaseline = 'alphabetic';
  const text = textEl.textContent ?? '';
  const m = ctx.measureText(text);
  const asc = m.fontBoundingBoxAscent ?? parseFloat(cs.fontSize) * 0.9;
  const desc = m.fontBoundingBoxDescent ?? parseFloat(cs.fontSize) * 0.2;
  const x = tr.left - rr.left;
  const baseline = tr.top - rr.top + (tr.height - (asc + desc)) / 2 + asc;
  ctx.fillText(text, x, baseline);
  ctx.restore();
}

/** Render `textEl`'s glyphs white-on-transparent over `root`'s box → data URL. */
export function textMaskDataUrl(root: HTMLElement, textEl: HTMLElement): string | null {
  const dpr = window.devicePixelRatio || 1;
  const rr = root.getBoundingClientRect();
  const c = document.createElement('canvas');
  c.width = Math.max(1, Math.round(rr.width * dpr));
  c.height = Math.max(1, Math.round(rr.height * dpr));
  const g = c.getContext('2d');
  if (!g) return null;
  g.fillStyle = '#fff';
  paintTextRun(g, root, textEl, dpr);
  return c.toDataURL('image/png');
}

/**
 * "New" badge — Figma: Portfolio › tab 3 (1458:40880), applied verbatim.
 *
 *   45×25, pill r 55.556. Layers bottom→top:
 *     1. white fill
 *     2. metal texture (a static PNG in Figma — here the live shader, via a
 *        full-pill mask so it covers the fill)
 *     3. gradient rgba(255,255,255,.6) → 0, top→bottom
 *     3b. clean white core under the label — transitions.dev get-pro-button
 *         mechanism inverted: radial ellipse 46%, solid to `core`, ramp over
 *         `coreBlur`, so the text sits on white and metal creeps in at the rim
 *     4. text: Inter Semi Bold 12.222/1.4 #323232, box 26.667×13.333
 *     5. inset shadows: 0 0 8.333 #fff ×2, 0 0 0 0.833 rgba(255,255,255,.5),
 *        0 0.833 0 rgba(255,255,255,.78)
 *
 * The gradient AND the inset shadows have to sit above the metal canvas
 * (z 0) and below the text (content z 5) — on the root they'd be painted
 * under the opaque metal and vanish. Both live on one overlay inside the
 * content layer, one level down: MetalFx normalises the *direct* child's
 * background/box-shadow to transparent/none, so the overlay is nested under
 * a plain wrapper to keep them.
 */
import React, { useCallback, useRef } from 'react';
import { MetalFx } from './MetalFx';
import type { MetalFxReflectionTarget, MetalFxTheme } from './types';
import type { MaskFn } from './engine/renderer/core';

const RADIUS = 55.556;
const W = 45, H = 25;
const TEXT_W = 26.667;
const PAD_X = (W - TEXT_W) / 2;

const LAYER: React.CSSProperties = { position: 'absolute', inset: 0, pointerEvents: 'none' };

/** `glow` scales the two soft inner glows; the hairline rims stay as designed. */
const shadowFor = (k: number, glow: number) =>
  `inset 0px 0px ${8.333 * k}px 0px rgba(255,255,255,${glow}), ` +
  `inset 0px 0px ${8.333 * k}px 0px rgba(255,255,255,${glow}), ` +
  `inset 0px 0px 0px ${0.833 * k}px rgba(255,255,255,0.5), ` +
  `inset 0px ${0.833 * k}px 0px 0px rgba(255,255,255,0.78)`;

/** Tuned on the demo's "Live mode · New" card. */
export const METAL_BADGE_DEFAULTS = Object.freeze({
  metalOpacity: 0.8,
  shaderScale: 1.6,
  /** White core under the label: solid radius (% of ellipse), ramp width, opacity, ellipse size (% of box). */
  core: Object.freeze({ r: 46, blur: 100, a: 0.94, size: 49 }),
  gradient: 0,
  glow: 0.41,
});

export interface MetalBadgeCore { r: number; blur: number; a: number; size: number }

export function MetalBadge({
  children = 'New',
  strength = 1,
  theme,
  scale = 1,
  reflectionTargets,
  metalOpacity = METAL_BADGE_DEFAULTS.metalOpacity,
  shaderScale = METAL_BADGE_DEFAULTS.shaderScale,
  core = METAL_BADGE_DEFAULTS.core,
  gradient = METAL_BADGE_DEFAULTS.gradient,
  glow = METAL_BADGE_DEFAULTS.glow,
  textColor = '#323232',
}: {
  children?: string;
  strength?: number;
  theme?: MetalFxTheme;
  /** Size multiplier on the Figma metrics (45×25, 12.222px). */
  scale?: number;
  reflectionTargets?: ReadonlyArray<MetalFxReflectionTarget>;
  /** How much metal shows over the white fill (0..1), multiplied with `strength`. */
  metalOpacity?: number;
  shaderScale?: number;
  core?: MetalBadgeCore;
  /** Top→bottom white wash strength (0..1). */
  gradient?: number;
  /** Inner white glow strength (0..1). */
  glow?: number;
  textColor?: string;
}) {
  const rootRef = useRef<HTMLDivElement>(null);
  const opacity = metalOpacity;

  // Full-fill mask: the pill itself.
  const mask = useCallback<MaskFn>((ctx, w, h, dpr) => {
    ctx.beginPath();
    ctx.roundRect(0, 0, w, h, RADIUS * dpr);
    ctx.fill();
  }, []);

  return (
    <MetalFx
      ref={rootRef}
      preset="chromatic"
      theme={theme}
      strength={strength * opacity}
      shaderScale={shaderScale}
      mask={mask}
      glowMode="ring"
      reflectionTargets={reflectionTargets}
      borderRadius={RADIUS * scale}
      style={{ background: '#ffffff', borderRadius: RADIUS * scale }}
    >
      {/* Inline layout only — no utility classes, so the badge renders the
          same with or without a CSS framework on the host page. */}
      <div style={{ position: 'relative', width: W * scale, height: H * scale, borderRadius: RADIUS * scale }}>
        {/* layer 3b — clean white core under the label (rim-only metal) */}
        <div
          aria-hidden="true"
          style={{
            ...LAYER,
            borderRadius: RADIUS * scale,
            // Stops are relative to the ellipse radius, so 100% = its edge.
            background: `radial-gradient(ellipse ${core.size}% ${core.size}% at 50% 50%, rgba(255,255,255,1) ${core.r}%, rgba(255,255,255,0) ${Math.min(100, core.r + core.blur)}%)`,
            opacity: core.a,
          }}
        />
        {/* layers 3 + 5 — white gradient and inset rims, over the metal */}
        <div
          aria-hidden="true"
          style={{
            ...LAYER,
            borderRadius: RADIUS * scale,
            background: `linear-gradient(to bottom, rgba(255,255,255,${gradient}), rgba(255,255,255,0))`,
            boxShadow: shadowFor(scale, glow),
          }}
        />
        <span
          style={{
            position: 'relative',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            boxSizing: 'border-box',
            width: W * scale,
            height: H * scale,
            paddingLeft: PAD_X * scale,
            paddingRight: PAD_X * scale,
            font: `600 ${12.222 * scale}px/1.4 Inter, sans-serif`,
            color: textColor,
            letterSpacing: 0,
            whiteSpace: 'nowrap',
          }}
          aria-label={children}
        >
          {children}
        </span>
      </div>
    </MetalFx>
  );
}

import { useEffect, type RefObject } from 'react';
import { redrawInstance, setInstanceDeform } from './engine/renderer/loop';
import type { DeformLayers } from './engine/renderer/core';
import { BEND, type BendConfig } from './engine/bend/config';

/**
 * Cursor-driven local deformation ("liquid dent") for a MetalFx root.
 *
 * Field
 * ─────
 * Two gaussian blobs centred at `c` (which lags the cursor by `follow`):
 *   • directional: `amp · g_bend(r)` — a 2-D spring chasing the cursor's
 *     smoothed velocity × gain, so motion toward the centre pushes the ring
 *     in and motion away drags it out; recoils on release.
 *   • liquid: `(p − c)/σ · g_liq(r) · la` — the gradient of a bump, i.e. a
 *     divergent push away from the contact point. This term *stretches*
 *     material rather than sliding it, so the stroke thins under the cursor
 *     and thickens either side. `la` is its own slower spring; pressure is 1
 *     with the cursor on the ring, fading over `liquidReach`.
 *
 * Two render paths, chosen by `applyTo`:
 *
 * `ring` — vector. The engine masks the ring with a rounded-rect outline it
 * traces every frame; we hand it a `DeformFn` that displaces those outline
 * points, plus the fill / rim / hairline that normally live on CSS boxes so
 * they bend along. Edges stay anti-aliased at any stretch. The instance is
 * redrawn from here at the pointer's frame rate, since the shared loop only
 * composites at 15 fps.
 *
 * `all` — SVG `feDisplacementMap` on the whole root. Bends the content too,
 * but the sampler duplicates source pixels where material is stretched, so
 * quality degrades with amplitude. Kept for comparison.
 */
export function useMetalBend(ref: RefObject<HTMLElement | null>, getCfg: () => BendConfig = () => BEND): void {
  useEffect(() => {
    const el = ref.current;
    if (!el || typeof document === 'undefined') return;

    const ring = el.querySelector<HTMLCanvasElement>('canvas.metal-fx-canvas');
    const inner = el.querySelector<HTMLElement>('.metal-fx-inner');

    // ── shared field state ──────────────────────────────────────────
    let pointer: { x: number; y: number } | null = null;
    let lastPointer: { x: number; y: number; t: number } | null = null;
    let pressed = false;
    let active = false;
    let cx = 0, cy = 0;          // blob centre, element-local px
    let ax = 0, ay = 0;          // directional displacement (px)
    let vax = 0, vay = 0;
    let la = 0, vla = 0;         // liquid amplitude
    let stx = 0, sty = 0, stl = 0; // low-passed targets (see smoothMs)
    let pressure = 0;
    let env = 0;                 // hover envelope 0..1 — no pops on enter/leave
    let svx = 0, svy = 0;        // smoothed cursor velocity, px/s
    let raf = 0, last = 0;
    // Redraw gate: physics integrates at display rate, but the canvas +
    // glow-mask rebuild is capped at 60 fps and skipped when nothing moved
    // more than 0.05 px — on a 120 Hz display that halves the bend's cost.
    let drawT = 0, dAx = NaN, dAy = NaN, dLa = NaN, dCx = NaN, dCy = NaN;

    // Per-frame constants for the field evaluators.
    let fDirX = 0, fDirY = 0, fRadK = 0, fS2b = 1, fS2l = 1;
    const evalField = (x: number, y: number, out: { x: number; y: number }) => {
      const dx = x - cx, dy = y - cy;
      const q = dx * dx + dy * dy;
      const gb = Math.exp(-q / fS2b);
      const gl = Math.exp(-q / fS2l);
      out.x = fDirX * gb + dx * fRadK * gl;
      out.y = fDirY * gb + dy * fRadK * gl;
    };
    const _f = { x: 0, y: 0 };
    const deform = (x: number, y: number, out: { x: number; y: number }) => {
      evalField(x, y, _f);
      out.x = x + _f.x;
      out.y = y + _f.y;
    };

    // ── vector path (ring mode) ─────────────────────────────────────
    const STYLE_ID = 'mfx-bend-style';
    if (!document.getElementById(STYLE_ID)) {
      const st = document.createElement('style');
      st.id = STYLE_ID;
      st.textContent = '.metal-fx-root[data-mfx-bend]::before,.metal-fx-root[data-mfx-bend]::after{box-shadow:none!important}';
      document.head.appendChild(st);
    }
    let vectorOn = false;
    let layers: DeformLayers | null = null;
    const prevRootBg = el.style.background;
    const prevInnerVis = inner?.style.visibility ?? '';

    /** "rgba(…) 0px 0px 0px 2px inset" → { color, spread } for the first shadow. */
    const parseShadow = (v: string): { color: string; spread: number } | null => {
      if (!v || v === 'none') return null;
      const m = v.match(/^(rgba?\([^)]*\)|#[0-9a-fA-F]+|[a-z]+)\s+(-?[\d.]+)px\s+(-?[\d.]+)px\s+(-?[\d.]+)px\s+(-?[\d.]+)px/);
      if (!m) return null;
      return { color: m[1], spread: Math.abs(parseFloat(m[5])) };
    };
    const vectorStart = (overscan: number) => {
      if (vectorOn || !ring) return;
      const rim = parseShadow(getComputedStyle(el, '::after').boxShadow);
      const hair = inner ? parseShadow(getComputedStyle(inner).boxShadow) : null;
      const innerInset = inner ? parseFloat(getComputedStyle(inner).inset) || 0 : 0;
      layers = {
        fill: getComputedStyle(el).backgroundColor,
        rim: rim && rim.spread > 0 ? { inset: 0, width: rim.spread, color: rim.color } : null,
        hairline: hair && hair.spread > 0 ? { inset: innerInset, width: hair.spread, color: hair.color } : null,
      };
      el.style.background = 'transparent';
      el.setAttribute('data-mfx-bend', '');
      if (inner) inner.style.visibility = 'hidden';
      setInstanceDeform(ring, deform, layers, overscan);
      vectorOn = true;
    };
    const vectorStop = () => {
      if (!vectorOn || !ring) return;
      setInstanceDeform(ring, null, null, 0);
      el.style.background = prevRootBg;
      el.removeAttribute('data-mfx-bend');
      if (inner) inner.style.visibility = prevInnerVis;
      vectorOn = false;
    };

    // ── filter path (all mode) ──────────────────────────────────────
    const id = `mfx-bend-${Math.random().toString(36).slice(2, 8)}`;
    const NS = 'http://www.w3.org/2000/svg';
    const REGION = 0.75;
    const svg = document.createElementNS(NS, 'svg');
    svg.setAttribute('aria-hidden', 'true');
    svg.style.cssText = 'position:absolute;width:0;height:0;overflow:hidden;pointer-events:none';
    const filter = document.createElementNS(NS, 'filter');
    filter.setAttribute('id', id);
    filter.setAttribute('x', `-${REGION * 100}%`); filter.setAttribute('y', `-${REGION * 100}%`);
    filter.setAttribute('width', `${(1 + 2 * REGION) * 100}%`); filter.setAttribute('height', `${(1 + 2 * REGION) * 100}%`);
    filter.setAttribute('color-interpolation-filters', 'sRGB');
    const feFlood = document.createElementNS(NS, 'feFlood');
    feFlood.setAttribute('flood-color', 'rgb(128,128,0)');
    feFlood.setAttribute('flood-opacity', '1');
    feFlood.setAttribute('result', 'neutral');
    const feImage = document.createElementNS(NS, 'feImage');
    feImage.setAttribute('result', 'img');
    feImage.setAttribute('preserveAspectRatio', 'none');
    const feComp = document.createElementNS(NS, 'feComposite');
    feComp.setAttribute('in', 'img'); feComp.setAttribute('in2', 'neutral');
    feComp.setAttribute('operator', 'over'); feComp.setAttribute('result', 'map');
    const feDisp = document.createElementNS(NS, 'feDisplacementMap');
    feDisp.setAttribute('in', 'SourceGraphic'); feDisp.setAttribute('in2', 'map');
    feDisp.setAttribute('xChannelSelector', 'R'); feDisp.setAttribute('yChannelSelector', 'G');
    feDisp.setAttribute('result', 'bent');
    const feSmooth = document.createElementNS(NS, 'feGaussianBlur');
    feSmooth.setAttribute('in', 'bent'); feSmooth.setAttribute('stdDeviation', '0');
    for (const n of [feFlood, feImage, feComp, feDisp, feSmooth]) filter.appendChild(n);
    svg.appendChild(filter);
    document.body.appendChild(svg);

    const map = document.createElement('canvas');
    const mctx = map.getContext('2d', { alpha: false, willReadFrequently: true });
    let img: ImageData | null = null;
    let img32: Uint32Array | null = null;
    const NEUTRAL = 0xff008080;
    let filterOn = false;
    const prevFilter = el.style.filter;
    const filterStop = () => {
      if (!filterOn) return;
      el.style.filter = prevFilter;
      filterOn = false;
    };
    const filterFrame = (cfg: BendConfig, W: number, H: number, scale: number) => {
      if (!mctx) return;
      const res = Math.max(0.25, cfg.mapRes);
      const mx = -W * REGION, my = -H * REGION, mw = W * (1 + 2 * REGION), mh = H * (1 + 2 * REGION);
      const pw = Math.max(2, Math.round(mw * res)), ph = Math.max(2, Math.round(mh * res));
      if (map.width !== pw || map.height !== ph || !img || !img32) {
        map.width = pw; map.height = ph;
        img = mctx.createImageData(pw, ph);
        img32 = new Uint32Array(img.data.buffer);
      }
      img32.fill(NEUTRAL);
      const data = img.data;
      const ext = 3 * Math.max(cfg.blob, cfg.liquidBlob);
      const px0 = Math.max(0, Math.floor((cx - ext - mx) * res));
      const px1 = Math.min(pw - 1, Math.ceil((cx + ext - mx) * res));
      const py0 = Math.max(0, Math.floor((cy - ext - my) * res));
      const py1 = Math.min(ph - 1, Math.ceil((cy + ext - my) * res));
      const inv = 255 / scale;
      for (let py = py0; py <= py1; py++) {
        const y = my + (py + 0.5) / res;
        let i = (py * pw + px0) * 4;
        for (let px = px0; px <= px1; px++, i += 4) {
          const x = mx + (px + 0.5) / res;
          evalField(x, y, _f);
          let r = 127.5 - _f.x * inv; r = r < 0 ? 0 : r > 255 ? 255 : r;
          let g = 127.5 - _f.y * inv; g = g < 0 ? 0 : g > 255 ? 255 : g;
          data[i] = r; data[i + 1] = g;
        }
      }
      mctx.putImageData(img, 0, 0);
      feImage.setAttribute('x', mx.toFixed(2)); feImage.setAttribute('y', my.toFixed(2));
      feImage.setAttribute('width', mw.toFixed(2)); feImage.setAttribute('height', mh.toFixed(2));
      feImage.setAttribute('href', map.toDataURL('image/png'));
      feDisp.setAttribute('scale', scale.toFixed(2));
      feSmooth.setAttribute('stdDeviation', Math.max(0, cfg.smooth).toFixed(3));
      if (!filterOn) { el.style.filter = `url(#${id})`; filterOn = true; }
    };

    // ── simulation ──────────────────────────────────────────────────
    const kick = () => {
      if (raf !== 0) return;
      last = performance.now();
      raf = requestAnimationFrame(step);
    };

    const step = (now: number) => {
      raf = 0;
      const cfg = getCfg();
      const dt = Math.min(0.032, Math.max(0.001, (now - last) / 1000));
      last = now;

      const r = el.getBoundingClientRect();
      const W = r.width, H = r.height;
      const ecx = W / 2, ecy = H / 2;

      let tx = 0, ty = 0;
      pressure = 0;
      if (cfg.enabled && pointer) {
        const lx = pointer.x - r.left, ly = pointer.y - r.top;
        const ddx = lx - ecx, ddy = ly - ecy;
        const d = Math.hypot(ddx, ddy);
        const R = Math.min(W, H) / 2;
        const reach = Math.max(W, H) / 2 + cfg.reach;
        const wasActive = active;
        active = d < reach;
        const u = Math.max(0, 1 - Math.abs(d - R) / Math.max(1, cfg.liquidReach));
        pressure = u * u * (3 - 2 * u);
        if (active) {
          if (!wasActive) { cx = lx; cy = ly; }
          // `follow` is defined per 60 Hz frame; convert to this frame's dt.
          const fa = 1 - Math.pow(1 - Math.min(0.999, cfg.follow), dt * 60);
          cx += (lx - cx) * fa;
          cy += (ly - cy) * fa;
          const edgeFade = 1 - Math.max(0, (d - (reach - cfg.reach)) / cfg.reach);
          // Transient kick from cursor speed.
          tx = svx * (cfg.gain / 100) * edgeFade;
          ty = svy * (cfg.gain / 100) * edgeFade;
          // Position-based, so the dent holds while the cursor sits there.
          // Inside the edge: press toward the centre by penetration.
          // Outside: pull toward the cursor, fading to zero at reach.
          const ux = d > 0.001 ? ddx / d : 0, uy = d > 0.001 ? ddy / d : 0;
          const pen = R - d;
          if (pen > 0) {
            const m = pen * cfg.pressGain;
            tx -= ux * m; ty -= uy * m;
          } else {
            const out = -pen;
            const f = Math.max(0, 1 - out / Math.max(1, cfg.reach));
            const m = out * cfg.pullGain * (f * f * (3 - 2 * f));
            tx += ux * m; ty += uy * m;
          }
          const tm = Math.hypot(tx, ty);
          if (tm > cfg.maxDisp) { tx *= cfg.maxDisp / tm; ty *= cfg.maxDisp / tm; }
        }
      } else {
        active = false;
      }
      svx *= Math.exp(-dt * 12); svy *= Math.exp(-dt * 12);

      // Low-pass the targets. Springs then chase a smooth signal instead of a
      // stepping one — the stepping is what read as "unnatural" on fast sweeps.
      const sa = 1 - Math.exp(-(dt * 1000) / Math.max(1, cfg.smoothMs));
      stx += (tx - stx) * sa;
      sty += (ty - sty) * sa;

      const m = Math.max(0.05, cfg.mass);
      vax += ((-cfg.stiffness * (ax - stx) - cfg.damping * vax) / m) * dt;
      vay += ((-cfg.stiffness * (ay - sty) - cfg.damping * vay) / m) * dt;
      ax += vax * dt; ay += vay * dt;

      const pressAmt = pressed && active && cfg.enabled ? cfg.press : 0;
      const tl = active && cfg.enabled ? cfg.liquid * (pressure + (pressed ? 0.5 : 0)) : 0;
      stl += (tl - stl) * sa;
      vla += ((-cfg.liquidStiffness * (la - stl) - cfg.liquidDamping * vla) / m) * dt;
      la += vla * dt;

      // Envelope: exponential approach, ~95% of the way by fadeIn/OutMs.
      const envTarget = active && cfg.enabled ? 1 : 0;
      const tauMs = Math.max(1, envTarget ? cfg.fadeInMs : cfg.fadeOutMs) / 3;
      env += (envTarget - env) * (1 - Math.exp(-(dt * 1000) / tauMs));
      if (env < 0.002 && envTarget === 0) env = 0;

      const amp = Math.hypot(ax, ay);
      const idle = !active && env === 0 && amp < 0.05 && Math.hypot(vax, vay) < 1 && Math.abs(la) < 0.05 && pressAmt === 0;

      // Mode switch releases whichever path was active.
      if (cfg.applyTo === 'ring') filterStop(); else vectorStop();

      if (idle) {
        ax = ay = vax = vay = la = vla = 0;
        stx = sty = stl = 0;
        dAx = dAy = dLa = dCx = dCy = NaN;
        vectorStop();
        filterStop();
        return;
      }

      // Field constants for this frame. The envelope scales the whole field.
      const k = Math.max(0, cfg.strength) * env;
      let pdx = ecx - cx, pdy = ecy - cy;
      const pl = Math.hypot(pdx, pdy) || 1; pdx /= pl; pdy /= pl;
      const sb = Math.max(0.5, cfg.blob), sl = Math.max(0.5, cfg.liquidBlob);
      fS2b = 2 * sb * sb; fS2l = 2 * sl * sl;
      fDirX = (ax + pdx * pressAmt) * k;
      fDirY = (ay + pdy * pressAmt) * k;
      fRadK = (la / sl) * k;

      const moved = !(Math.abs(ax - dAx) < 0.05 && Math.abs(ay - dAy) < 0.05 && Math.abs(la - dLa) < 0.05 &&
                      Math.abs(cx - dCx) < 0.05 && Math.abs(cy - dCy) < 0.05);
      const due = now - drawT >= 1000 / 60 - 0.5;
      if (moved && due) {
        drawT = now; dAx = ax; dAy = ay; dLa = la; dCx = cx; dCy = cy;
        if (cfg.applyTo === 'ring' && ring) {
          // Overscan budget: the furthest any point can travel.
          const reachPx = Math.ceil((cfg.maxDisp + cfg.liquid * 1.5) * Math.max(1, cfg.strength)) + 4;
          vectorStart(reachPx);
          redrawInstance(ring);
        } else {
          const scale = Math.max(1, (cfg.maxDisp + cfg.liquid * 1.5) * 2 * Math.max(1, cfg.strength));
          filterFrame(cfg, W, H, scale);
        }
      } else if (cfg.applyTo === 'ring' && ring && !vectorOn) {
        vectorStart(Math.ceil((cfg.maxDisp + cfg.liquid * 1.5) * Math.max(1, cfg.strength)) + 4);
      }

      raf = requestAnimationFrame(step);
    };

    const onMove = (e: PointerEvent) => {
      const now = performance.now();
      if (lastPointer) {
        const dt = Math.max(0.004, (now - lastPointer.t) / 1000);
        // ~40 ms time constant regardless of event rate.
        const a = 1 - Math.exp(-dt / 0.04);
        svx += ((e.clientX - lastPointer.x) / dt - svx) * a;
        svy += ((e.clientY - lastPointer.y) / dt - svy) * a;
      }
      lastPointer = { x: e.clientX, y: e.clientY, t: now };
      pointer = { x: e.clientX, y: e.clientY };
      kick();
    };
    const onLeave = () => { pointer = null; lastPointer = null; kick(); };
    const onDown = () => { pressed = true; kick(); };
    const onUp = () => { pressed = false; kick(); };

    document.addEventListener('pointermove', onMove, { passive: true });
    document.addEventListener('pointerleave', onLeave);
    window.addEventListener('blur', onLeave);
    el.addEventListener('pointerdown', onDown);
    document.addEventListener('pointerup', onUp);
    document.addEventListener('pointercancel', onUp);

    return () => {
      if (raf !== 0) cancelAnimationFrame(raf);
      document.removeEventListener('pointermove', onMove);
      document.removeEventListener('pointerleave', onLeave);
      window.removeEventListener('blur', onLeave);
      el.removeEventListener('pointerdown', onDown);
      document.removeEventListener('pointerup', onUp);
      document.removeEventListener('pointercancel', onUp);
      vectorStop();
      filterStop();
      if (svg.parentNode) svg.parentNode.removeChild(svg);
    };
  }, [ref, getCfg]);
}

/**
 * Live config for the cursor "bend" effect — a local liquid dent.
 *
 * The cursor carries a blob of displacement that rides the ring: moving
 * toward the button's centre dents the edge inward, moving away drags it
 * outward, and on release the bulge springs back. Implemented as an SVG
 * `feDisplacementMap` over the whole MetalFx root (button, ring, glow), with
 * the vector field regenerated each frame into a small canvas.
 *
 * Mutable singleton, read every frame by `useBend`.
 */
export interface BendConfig {
  enabled: boolean;
  /** What deforms. `ring` = the metal canvas only; button content and glow
   *  stay rigid. `all` = the whole MetalFx root. */
  applyTo: 'ring' | 'all';
  /** Global amplitude multiplier on the whole displacement field. */
  strength: number;
  /** Time for the effect to ease in after the cursor arrives, ms. Without
   *  this the directional spring lands the dent in 2–3 frames — a pop. */
  fadeInMs: number;
  /** Time for the effect to ease out after the cursor leaves, ms. */
  fadeOutMs: number;
  /** Low-pass on the field's *target* before the spring sees it, ms. A fast
   *  sweep across the ring flips press→pull and swings the direction vector
   *  within a frame; this keeps the dent from snapping to each new target. */
  smoothMs: number;
  /** How far beyond the element's edge the cursor is still felt, CSS px. */
  reach: number;
  /** Area of the directional bend (gaussian σ), CSS px. */
  blob: number;
  /** Area of the liquid push (gaussian σ), CSS px. Independent of `blob`. */
  liquidBlob: number;
  /** Displacement cap, CSS px. Also sets the filter's `scale`. */
  maxDisp: number;
  /** Displacement px produced per 100 px/s of cursor speed — a transient
   *  kick on fast moves. 0 disables. */
  gain: number;
  /** Position-based press: dent px per px the cursor sits inside the ring's
   *  edge, pushing toward the centre. Holds while the cursor stays. */
  pressGain: number;
  /** Position-based pull: bulge px per px the cursor sits outside the edge
   *  (within `reach`), dragging the ring toward the cursor — the sticky part. */
  pullGain: number;
  /** Extra inward dent (toward element centre) while pressed, px. */
  press: number;
  /** Radial push away from the contact point, px at full pressure. This is
   *  the divergent part of the field — it *stretches* material rather than
   *  sliding it, so the stroke thins under the cursor and bulges around it.
   *  Pressure is 1 with the cursor on the ring, fading to 0 at `reach`. */
  liquid: number;
  /** Distance from the ring (either side) over which liquid pressure fades
   *  to zero, px. Keep this small — a large value lets a cursor sitting
   *  inside the button push the whole ring outward, which reads as a scale. */
  liquidReach: number;
  /** Spring constant for the liquid push. Lower = slower swell. */
  liquidStiffness: number;
  /** Damping for the liquid push. Below 2·√k it overshoots on release. */
  liquidDamping: number;
  /** Spring on the displacement vector — snap back speed. */
  stiffness: number;
  /** Below 2·√(k·m) the surface wobbles after release. */
  damping: number;
  mass: number;
  /** Blob-centre tracking, as a per-frame lerp at 60 Hz (0..1); applied
   *  time-based so 120 Hz pointers don't track twice as hard. Lower = the
   *  blob lags and stretches behind the cursor — stickier. */
  follow: number;
  /** Map resolution multiplier. 1 = one texel per CSS px, 2 = device parity
   *  on a 2× display. Steps in the field are visible below device parity. */
  mapRes: number;
  /** Post-displacement blur, CSS px. `feDisplacementMap` samples the source
   *  nearest-neighbour, which shows as stepping where material is stretched;
   *  a quarter-pixel blur hides it. 0 disables. */
  smooth: number;
}

export const BEND_DEFAULTS: Readonly<BendConfig> = Object.freeze({
  enabled: true,
  applyTo: 'ring',
  strength: 0.74,
  fadeInMs: 200,
  fadeOutMs: 350,
  smoothMs: 140,
  reach: 36,
  blob: 13,
  liquidBlob: 10,
  maxDisp: 9,
  gain: 0.6,
  pressGain: 0.55,
  pullGain: 0.49,
  press: 5,
  liquid: 7.5,
  liquidReach: 8,
  liquidStiffness: 53,
  liquidDamping: 9,
  stiffness: 260,
  damping: 13,
  mass: 1,
  follow: 0.32,
  mapRes: 2,
  smooth: 0.25,
});

export const BEND: BendConfig = { ...BEND_DEFAULTS };

export function setBendConfig(patch: Partial<BendConfig>): void {
  Object.assign(BEND, patch);
}

export function resetBendConfig(): void {
  Object.assign(BEND, BEND_DEFAULTS);
}

import { useEffect, type RefObject } from 'react';
import { textMaskDataUrl } from './engine/textMask';

/**
 * Confine a proximity reflection to an element's glyphs.
 *
 * The engine paints reflections into a wrapper it inserts inside the target
 * (`[data-metal-fx-reflection]`, canvases inset:0). For a text node that
 * would light the whole line box and stroke its rectangle. This masks the
 * wrapper with the text rendered white-on-transparent, so only the
 * letterforms catch the light. Re-rendered on resize and once fonts load.
 */
export function useMetalTextReflection(ref: RefObject<HTMLElement | null>): void {
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    // Tells the engine to light this as letterforms, not as a chip: mirrored
    // metal only, no rim stroke / border highlight.
    el.setAttribute('data-metal-fx-text', '');
    let raf = 0;
    let disposed = false;
    let tries = 0;

    const apply = () => {
      if (disposed) return;
      const wrap = el.querySelector<HTMLElement>(':scope > [data-metal-fx-reflection]');
      // Engine attaches the wrapper after mount (and only in dark theme) —
      // wait a few seconds for it, then give up quietly.
      if (!wrap) { if (tries++ < 300) raf = requestAnimationFrame(apply); return; }
      tries = 0;
      const url = textMaskDataUrl(el, el);
      if (!url) return;
      const v = `url("${url}")`;
      wrap.style.maskImage = v;
      wrap.style.webkitMaskImage = v;
      wrap.style.maskRepeat = 'no-repeat';
      wrap.style.webkitMaskRepeat = 'no-repeat';
      wrap.style.maskSize = '100% 100%';
      wrap.style.webkitMaskSize = '100% 100%';
      // A mirror *replaces* what's under it. Additive blending on light-grey
      // text pushed everything to white and erased the metal's stripes and
      // dispersion fringes; normal compositing keeps them.
      wrap.style.mixBlendMode = 'normal';
    };

    apply();
    const ro = new ResizeObserver(() => apply());
    ro.observe(el);
    document.fonts?.ready.then(() => apply());
    // The engine tears down and re-inserts the wrapper whenever the owning
    // MetalFx's reflection effect re-runs — every new wrapper needs the mask.
    const mo = new MutationObserver((recs) => {
      for (const r of recs) {
        for (const n of Array.from(r.addedNodes)) {
          if (n instanceof HTMLElement && n.hasAttribute('data-metal-fx-reflection')) { apply(); return; }
        }
      }
    });
    mo.observe(el, { childList: true });

    return () => {
      disposed = true;
      if (raf) cancelAnimationFrame(raf);
      ro.disconnect();
      mo.disconnect();
    };
  }, [ref]);
}

