  font-weight: 500;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.records-more-tag {
  display: inline-flex;
  height: 23px;
  align-items: center;
  flex-shrink: 0;
  border: 1px solid var(--line-strong);
  border-radius: 6px;
  padding: 0 7px;
  color: var(--ink-3);
  background: var(--inset);
  font-size: 11px;
  font-weight: 500;
}

.records-more-tag {
  border-color: var(--line-strong);
  color: var(--ink-3);
  background: var(--inset);
}

.records-muted {
  color: var(--ink-3);
}

.records-strength {
