  color: var(--ink-2);
}

.records-strength-dot {
  display: inline-block;
  width: 8px;
  height: 8px;
  flex: 0 0 8px;
  border-radius: 50%;
}

.records-link {
  max-width: 100%;
  gap: 5px;
  overflow: hidden;
  color: var(--accent-ink);
